/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20150311-3","meetingId":"h27-c-budget","date":"2015年3月11日","dateIso":"2015-03-11","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を170件整理しています。","topics":[{"id":"topic-01","title":"平成２７年度品川区一般会計予算","agenda":"平成２７年度品川区一般会計予算","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"日野学園から始まって６校が立ち上がって、日野学園の１期目の子たちは卒業もされているということで、この中で幾つか質問したいと思います。具体的に少し内容ですとか、これはどういうところに向けて発信をしていくのか、もうちょっと詳しく教えてほしいと求めました。","respondent":"渋谷指導課長","answer":"今後の品川区の教育を考える上でのそういったものをこの場で発表、シンポジウム等を予定しています。それから特別支援教育、また体力向上、教育界をリードしていくような大きな心構えをお示ししたいというふうに考えているところです。","id":"exchange-001"},{"speaker":"渡部委員","kind":"意見","question":"ややもすると１,０００名といわず、入れないけれども２,０００名とか、品川区にお集まりいただく。午前中の学校見学も当然見ていただいて、また感想を述べてもらうなどの機会も欲しいなと思うのですが、ちょっとその辺の考え方をお願いいたしますとの意見を述べました。","respondent":"渋谷指導課長","answer":"この周知に関しましては、ホームページはもちろんのこと、全国の教育委員会にご案内を発送する予定です。春先には一次案内を出させていただいて、秋には二次案内ということで、広く周知をさせていただこうというふうに考えているところです。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"３５５ページの学校評価実施経費の中で、これまで私も再三にわたって、今回その細項目で学校運営協議会というものも予算書の中で登場いたしました。今後どのような方向性でこの外部評価なり、学校運営協議会なりが取り組まれていくのか、ご説明願います。","respondent":"渋谷指導課長","answer":"それから地域が上手に連携して育てていけるような、そういった仕組みをできないかということを今年１年間かけてじっくり検討していきたいと思います。地域の皆様、具体的な支援に積極的にかかわっていただけるように、またじっくりと検討してまいりたいと考えているところです。","id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"平成２８年度以降になるのでしょうか、防災、ある程度校区外部評価イコールこの学校運営協議会というような会議体になってくるはずなのですね。町会から上がっている声、いい点、悪い点を聞かせてください。","respondent":"品川庶務課長","answer":"その中で、いろいろ準備等を今行って実施をしているところですが、事前に町会に対してアンケートもとってあります。１人か２人でもやっぱり持ってきている子どもがいるとすれば、この事業もちょっとずつは浸透しているのかなというふうに感じている状況です。","id":"exchange-004"},{"speaker":"渡部委員","kind":"質問・要望","question":"これはもう一回再考していいのではないでしょうかね。学校で配るのではなくて、町会で配ったり、要するに町会の人が積極的にかかわっていただけるような仕組みでないと厳しいのではないか尋ねました。","respondent":"品川庶務課長","answer":"教育委員会としましても、ある程度説明がちょっと不十分なまま進めているということは非常に感じているところであります。しかし、この間、事業を始めてから延べ１０から２０ぐらいの町会に対しては、この事業の説明会を行っております。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、全学年に配っていただきたいなという思いがありまして、このような質問をさせていただきました。残念ながら行われていないわけですから、やってみてはというところなのですが、一言だけでいいです。","respondent":"野呂瀬学務課長","answer":"学務課としましても、いろいろとこういう就学人口のシミュレーションを重ねてまいりました。当面は学校選択の運用で対応していきたいと考えております。","id":"exchange-006"},{"speaker":"つる委員","kind":"提案","question":"私も昨年の第２回定例会で防災世界会議に触れつつ、レジリエンスの視点から品川区の防災対策の強化について幾つか提案もさせていただきました。こうした流れを受けて、一層の防災教育の充実が求められるところですが、新年度の防災教育の取組みについてお知らせくださいとの意見を述べました。","respondent":"村尾学校支援担当課長","answer":"来年度以降もまさに防災についての適切な知識、理解、これについては十分各教科を含め進めていこうというふうに考えております。どのような行動をするのか、またどのような判断をするのか、その辺についてしっかり対応していこうというふうに考えているところです。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"次は防災教育という視点で、就学前の子どもたちに対する防災教育についてお尋ねをいたします。今日は教育費ですので、幼稚園について、どのような防災教育を現在行っているか説明を求めました。","respondent":"竹田保育課長","answer":"防災に関する絵本、紙芝居等は幾つか種類があります。それぞれの園で随時読み聞かせ等を行うとともに、月１回は避難訓練を行い、幼保一体施設や小学校と同じ敷地の園では合同でやっているところです。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"次に、がん教育についてお尋ねします。改めて品川区も医師やがん経験者らの協力を得たがん教育を実施することを求めますけれども、いかがか尋ねました。","respondent":"村尾学校支援担当課長","answer":"まさにこれまでがん教育につきましては、それぞれ各教科、また生活習慣病という部分でも取り上げております。次年度におきましても、校長役員会等の場を活用しながらぜひ提案のございましたがん協会との連携、今後研究をしてまいりたいと考えているところです。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"１８歳選挙権が来年の参議院議員選挙から適用される方向で現在法案も提出されているところであります。昨年の決算特別委員会の総括の中で、改めてこの社会保障教育について先駆的に取り組むことを求めたいと思いますが、いかがか尋ねました。","respondent":"村尾学校支援担当課長","answer":"社会保障教育につきまして、実は今年度も社会保険労務士を呼んで、子どもたち、６年生の授業等を行いました。子どもたちにとって、このような活動をまた学校でそれぞれ社会科等の連携も含めながら、今後とも検討していきたいというふうに考えているところです。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"そういうことをしっかりと身につけていくことも必要であるというふうに思いますので、またこれについても積極的な取組みをお願いしたいと思います。この人権教育という観点でＬＧＢＴをはじめとする性的少数者への学校での教育について、どのような取組みを考えられているのか説明を求めました。","respondent":"村尾学校支援担当課長","answer":"この人権を大きな部分で取り上げますと、まさに自分の人権を守り、他者の人権を守ろうとする意識、意欲、態度の育成というふうに考えております。理解を深めるための研修会等について検討が始まっておりますので、その辺の内容を確認しながら、これから考えているところです。","id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"平成２５年の決算特別委員会、そして平成２６年の予算特別委員会でも学校図書館の名前を児童・生徒から募って命名したらどうか提案させていただいて。まだ１校というふうに理解しておりますが、その図書館の名前と、また今後どのようにそうしたところの推進を図っていくのか説明を求めました。","respondent":"中元品川図書館長","answer":"もう１校増えまして、源氏前小学校でも心の友と書きまして、「心友ブックランド」と名付けていただいているところです。今後今回の改訂版をこれから広く配付するなどして、このような取組みをご紹介して進めていけたらと思っているところです。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"推進計画を学校等に配っていただいていたのですが、やり方とかは当然学校単位でやると思うのですが、そのあたりは、何かアドバイスという形を教育委員会のほうとしてやっていくのか説明を求めました。","respondent":"中元品川図書館長","answer":"私どものほうで学校図書館担当でありますとか、そういうところから学校図書館サポートからのお知らせという広報物を不定期ではありますが、このような先進的な取り組みをご紹介するなどというところでサポートさせていただければと考えています。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"本を図書館に蔵書されているかどうか、絵本とかを検索するに当たっては、ある程度のあらすじとかは出てきたりとかはする。例えば３歳とか４歳とか５歳とか、もう少し簡単な方法でできるのか、この辺を教えてほしいと求めました。","respondent":"中元品川図書館長","answer":"すみません、そちらのほうのデータで持っていないと実現が難しいところがあります。０歳から２歳、３歳から５歳という年齢別で本のお勧めリストを発行していますので、そちらのほうをご活用いただければと存じます。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問","question":"ごめんなさい、今のリストはペーパーで配付ということですか、インターネット上であるのか。","respondent":"中元品川図書館長","answer":"図書館のホームページに子どものページという入り口がございまして、そちらから入っていただきますとブックリストの表示もあります。随時こちらも定期的に更新をしていますので、お使いいただければと存じています。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"大きいシステムの改修とかではない範疇で、より一層使いやすい、わかりやすい検索にしていただきたいというふうに思います。まさに今、未来を託す子どもたちのために、よりよき教育環境の充実を求めて終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ＩＣＴについては、昨年の秋からスタートされたと思うのですが、約半年間行ってきてどうだったかというのをまず教えてほしいと求めました。そのときのヘルプ対応がどのようになっているのか、教師と生徒、ともに教えてほしいと求めました。","respondent":"渋谷指導課長、野呂瀬学務課長","answer":"私からは、スクール・プロモーションについてご説明申し上げます。は子どもたちだけではなく、先ほどご説明申し上げましたフォーラムの場においてぜひ発表する機会を設けたい、そんなふうに考えているところです。 ２学期に導入されまして、研修体制も整っておりまして、各教員に対しては業者から設置のときに使い方の研修をやっております。デジタル教科書やプロジェクターの活用により動きや音声の教材を通して、子どもたちの興味は…","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"学校選択制を敷いているわけですから、新規事業であると思いますが、ぜひ力を入れてほしいと求めました。このヘルプデスクというのですかね、というのはどこの経費に入っているのか、そこを説明を求めました。","respondent":"野呂瀬学務課長","answer":"予算書の３６３ページの学校管理費の中の教材教具費の中の学校ＩＣＴ活用経費のところで、タブレット端末の運用ということで、計上しています。平成２６年度予算では、いわゆる設置みたいなのが新規事業でしたが、設置したのを平成２７年度予算は運用していくと…","id":"exchange-018"},{"speaker":"石田（し）委員","kind":"質問","question":"品川は先立って行っているわけですので、ある意味、全国のモデル校になると思います。どのような評価をこれまで行ってきたのか、またこれからどのような評価を行っていく予定なのか、その辺を説明を求めました。","respondent":"渋谷指導課長","answer":"そういった人間性の育成等々がどのように進んだのか等については、そういった客観的な資料を持って考えていきたい。先生たちの意識、それぞれアンケート調査を実施して、経年でずっと推移を見守っていきたいというふうに思っているところです。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もちろん自分の子どもと人の子だとどうしても違う目で見てしまうのかもしれませんが、あとはこれまで多くの自治体から視察に来られていると思います。今と前と何が違うのか、これは要望で終わりますが、ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは３６３ページの学校環境整備事業と、３６７ページの就学援助費、学校給食についても若干伺いたいと思います。学校のプールもぜひ温水にしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"品川庶務課長","answer":"その時期において、温水にする必要性がどこまであるかというところは少し考えなければいけないところではあるというふうに思っております。それからあと、例えばアトピー性皮膚炎がある子とか、そういう子についてはそれぞれの学校で対応という形でやっているような状況です。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ学校も温水に私はすべきだと思います。ぜひ学校の改築時はもちろん、既存校についてもシャワーを温水にしてほしいと求めましたけれども、改めていかがか尋ねました。","respondent":"品川庶務課長","answer":"やはりプールというのは暑い時期に入るというものですから、そこまで温水にというところをこだわるかどうかというところは少し疑問に思います。やはり、原則は水という形でシャワーはやっていく方向で考えております。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ子どもの教育環境の整備を進めてほしいと思います。ちょっと仕組みを伺いたいのと、ここに生徒会費、ＰＴＡ会費が就学援助の援助品目の対象になっていない理由は何か伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"品川区は１.２５倍ということで、それは平成２７年度からも継続しているということは、一般質問でもご答弁申し上げたところです。それよりも全体の就学援助の中で支給して、生徒たちのこれからの教育に寄与していくと、そのように考えているところです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"伺ったのは、生徒会費、ＰＴＡ会費がなぜ対象でないのかと伺ったのですけれども、要するにほかがやっていないからというのが区の理由なのでしょうか。これは負担がかかるわけですから、金額を引き上げることも私は必要だと思いますけれども、理由とあわせて伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"２２区、少なくとも品川区でやっていないというのは、当然その学校によってＰＴＡ会費も生徒会費も金額が違う。ＰＴＡ会費で支払うような負担は、こちらで補助していると、そういうふうに考えているところです。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ対象にすべきだと思いますので、この点、改めて伺いたいと思います。子育て支援としてぜひ給食の材料費に公費を入れて、献立の充実や保護者負担の軽減も進めていくべきだと思いますけれども、あわせていかがか尋ねました。","respondent":"野呂瀬学務課長","answer":"ですから、ＰＴＡ会費も含まれているというふうに考えているところです。それと、それ以外の食材費については保護者の負担と決まっていますので、それから見ても給食費については公費を投入する考えはございません。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"たしか平成２６年度は３７０万円ぐらいついていたと思うのですけれども、今回５万円ということで、この差についてお伺いします。２クラスずつですから、ここで１人合わないと私は思うのですけれども、その辺についても説明を求めました。","respondent":"村尾学校支援担当課長、品川庶務課長、野呂瀬学務課長、堀越人事課長","answer":"小学校２校が通級学級を指定して、通級学級に通っている子どもに対して、実際にどのような支援ができるかということで今研究をしているところです。… それから、３６５ページの屋内運動場整備ですが、こちらは冨士見台中学校の体育館の床の張り替えを予定しています。当然… 基準以上出たら数値が出るのですけれども、基準よりも低い場合というのは「不検出」というふうな形で出る。ですから… それから再任用フルタイムの教員が１名おりますので、４園で１３名の配置…","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"と私は思っているのですけれども、それと、モデルですから、何年ぐらいモデル事業を実施して、本事業は全国で展開していくおつもりなのでしょうか。もうそろそろ数字的にも結果が出ているわけですから、区切りをつけなくてはいけないと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"村尾学校支援担当課長、野呂瀬学務課長","answer":"本区では、平成２５年度から３年間モデル事業を進めております。このインクルーシブ教育は、今後、平成２８年度からいわゆる全国の全ての学校で取り入れる、そういう事業です。 放射性物質の検査というのは、当初やるときも食材については全て安全なものですと、それを確認するためも含めてやっているです。区としましてはさまざまな意見、またその予算作成のときに…","id":"exchange-027"},{"speaker":"藤原委員","kind":"確認","question":"インクルーシブなのですけれども、全校でやっていくおつもりなのですねというのをもう一回再確認でお願いいたします。","respondent":"村尾学校支援担当課長","answer":"区のほうでは、全校で平成２８年度から実施していく方向です。さらにこのインクルーシブについては、品川区はまさに文部科学省から委託を受け、先行的に研究を今進めているところです。","id":"exchange-028"},{"speaker":"吉田委員","kind":"提案","question":"先日、一般質問で横山委員から品川区の英語教育、一歩先の英語教育、グローバル教育について質問、また提案がありました。三木小学校と城南小学校ですかね、まず確認なのですが、日本人英語専科指導員学習指導とはどんな指導なのか尋ねました。","respondent":"渋谷指導課長","answer":"母音、そういった音素というものと文字とのつながりをしっかりと認識する、音素認識を高めるものですね。従来のような担任教諭による指導ではなく、専門の英語科専科教員を置く必要があるということで、順次導入をしています。","id":"exchange-029"},{"speaker":"吉田委員","kind":"意見","question":"どこから引っ張っていらっしゃったのか、どういう方なのか、採用の仕方ですね。それから平成２７年度は何人の採用をお考えなのか、平成２７年、それぞれの人数と勤務体制をお願いしますとの意見を述べました。","respondent":"渋谷指導課長","answer":"今ご説明したように、大変専門的な知識だったり技術が必要だということで、今回新たに１０名追加するに当たっては公募させていただきました。中学年担当の人がそのグループの３・４年生を見るということで、専門的な指導ができるような配置をさせていただいているところです。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"ベテランの担任の先生方の英語のスキルはどうなのだろうといつも思って質問させていただいておりました。月１回の英語の研修でどうやって英語力を子どもたちに教えていただけるのかなとちょっと心配だったのですけれども、担任の先生方の協力体制。","respondent":"渋谷指導課長","answer":"担任の先生はＪＴＥと一緒に教壇の前に立って、児童の様子を把握して学級をコントロールするという役割、またＪＴＥとともに授業を進める。上手にコラボレーションを組ながら、子どもたちが意欲的に授業に参加できる体制を担任は主に担っていくです。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"心が育つなどという大きなプラスアルファが期待できるのではないかと思うので、今後とも実りあるものにしてほしいと求めました。国際理解教育の中のグローバル人材育成塾が開始から２年経過しましたが、もう一つイングリッシュキャンプ、ついでにこの二つをお願いします。","respondent":"渋谷指導課長","answer":"それから、今年度新規事業として、中学生のイングリッシュキャンプというものをやらせていただくような予定です。２泊３日で宿泊研修に希望者を募っていくということで、また必要性等々を感じ取ってもらおうと、そういった試みです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"「パスポートの要らない英国」ですか、数多くの学校が利用しているようなのですけれども、希望者８０名だけでは寂しい。その機会を設けて、対象を広げて、これからいっていただきたいなと、私のこれは願いなのですけれども、ちょっとその辺を最後に一言説明を求めました。","respondent":"渋谷指導課長","answer":"多くの私立の高校、または東京都内ですと、都立の中等教育学校等が研修等で利用しているということもあります。そういった実績を踏まえて、また成果を検証して、今後考えていきたいというふうに思っております。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問","question":"こういう改修工事、大型の休暇に行うと思うのですけれども、これは一斉に夏休みに行うということでよろしいのでしょうか。昨年の定例会の議事録を見ると、これはやはり全校でやる五十何校のうち、複数か所あるということなのかどうか説明を求めました。","respondent":"品川庶務課長","answer":"学校別にそれぞれ校長先生と話し合いながらやっていくような予定になりますので、夏休み期間中のみで全てをやるということではございません。そういう点もありまして６７か所というような形になってあります。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問・要望","question":"工事を設計図書と照らし、建築士が行うとあるのですけれども、これは平成２６年度に調査を行った会社が行うということなのか教えてください。１社が全て行うのか、はたまた１校ずつ別会社が行うのか、説明を求めました。","respondent":"品川庶務課長","answer":"発注の仕方なのですけれども、これは現在検討している段階なのですが、基本的にはまとめて発注というような形を考えております。この場でどこでもできますというふうに答えるとなかなか厳しい点もありますが、基本的にはできるというふうに考えていただいて構いません。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"確認","question":"さまざまなちょっと細かいことを伺いました。一般質問で、そして施設整備課と連携をとられると思うのですが、この辺のお考えを確認させてください。","respondent":"品川庶務課長","answer":"当然災害時に避難所ということになりますので、そういう点につきましては、今後メンテナンスに非常に気をつけてやっていきたいというふうな考えです。それから適正価格に基づいた形で入札もかけていくというような考えで庶務課のほうもやっていきたいと考えていますので…","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"学校トイレの改修、今年は３校、８,０２３万円、今回のトイレ改修の対象の学校を教えてください。これは補助金を使っていると思うのですが、この理由を説明を求めました。","respondent":"品川庶務課長","answer":"それから、金額の面につきましては、今年度、非構造部材の耐震化、これが非常に予算上多くかかるという部分があります。やはり全体のメンテナンスの費用等を考えますと、今年度はトイレ費用を少し落としていくことで進めているというような状況です。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"ＴＯＴＯの全体の出荷数を見ると、１９７６年は和洋半々で出していたのが、現在は９９％が洋式であると。学校避難所となった場合、やっぱり混乱してしまうと思うのですけれども、その辺の考え方というのは何かあるのか説明を求めました。","respondent":"品川庶務課長","answer":"一部には、和式を残すという考え方です。それから、学校の授業の中で、例えば和式トイレの教育をするだとか、そういう点については、現在のところはやっていないという状況です。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問","question":"これも毎回質問させていただいているのですが、児童がトイレの使い方、デザインなどを一緒に考えるような場をつくってほしい。これは３年前に質問させていただいて、現在何校の小学校が子どもたちの意見を活かしたトイレ改修を行っているのか説明を求めました。","respondent":"品川庶務課長","answer":"具体的にはタイルの色とか、そういうものを決めてもらったりとか、そのようなことをやっております。平成２４年からこのデザインをしていただくということを始めていまして、平成２４年から平成２６年の間で現在のところ９校やっているという状況です。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回は２校、８,５４９万円ですか、一般財源ということですが、伊藤学園と日野学園、これを人工芝生化にした理由を教えてください。人工芝を対象としたスキームがあるのかないのか、もしあるのだとしたら、品川区はエントリーをしているのか説明を求めました。","respondent":"品川庶務課長","answer":"それから、人工芝につきましては、今年度、日野学園、それから伊藤学園と２校進めていく予定です。使う人数も多いという点もありまして、そういう面で非常に劣化が激しいということで今回人工芝のほうにかえていく予定です。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問","question":"小規模校はさまざまな努力をされているわけですけれども、教職員の努力ではどうにもならないので、こちらも力を入れていきたい。そこのところを最後にご答弁いただけますか尋ねました。","respondent":"品川庶務課長","answer":"補助金のほうにつきましては、今回計上はしておりませんが、申し込みはしております。地域の状況とそれから学校の校庭、基本的には土でと考えていますが、そういう状況を踏まえましてかえていきたいと考えております。","id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"質問","question":"３６９ページの３目、３７０ページの４目、感染性胃腸炎の扱いについてお尋ねいたします。さまざまなアレルギー対応の取組みをお伺いしましたが、なぜアレルギー対策費として予算に計上されていないのか、その理由をお尋ねいたします。","respondent":"野呂瀬学務課長","answer":"アレルギー対応費として予算に計上されていないということですが、アレルギー対応については、従前より給食費等で対応を行っているところです。給食運営費の中でアレルギー対応の色別のトレーや食器などを購入する際の食器購入等の中で通常の食器等と一緒に購入しております。","id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"予算書に食物アレルギーの計上が全くないというのはいかがなものでしょうか。しっかり品川区がアレルギー対応を行っているというメッセージにもなると思われますが、教育委員会のご見解はいかがか尋ねました。","respondent":"野呂瀬学務課長","answer":"アレルギー対応につきましては、何よりも必要なのが教職員等の危機管理意識の向上だと考えております。このために必要な予算措置等は今後も行い、アレルギーの事故の防止に努めていきたいと考えております。","id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区では色覚検査は原則どなたが行っているのでしょうか。眼科校医の先生方と色覚検査の進め方、検査の方法、配慮の仕方等について、ご相談などは密になされているのか尋ねました。","respondent":"野呂瀬学務課長","answer":"学校において色覚検査希望者にはまず養護教諭が色覚検査を行いまして、異常の疑いがある場合には眼科への診療を勧めるという流れでやっております。検査の方法や進め方につきましては、今現在、学校保健会の学校医師部会および品川区眼科医会等と相談調整を行っているところです。","id":"exchange-044"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"学校から特定の感染症の実施、ノロウイルスやインフルエンザ検査を求める必要はない」と述べられております。今、教育委員会のほうからご説明を伺いましたが、了解いたしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"松永委員","kind":"質問","question":"同じく３５１ページの教育相談事業と調査研究事業について、時間がありましたら３６５ページの学校運営費について伺いたいと思います。３４９ページの校長研修等とありますが、この研修内容について、また教育事情視察の内容についてお願いいたします。","respondent":"村尾学校支援担当課長","answer":"校長研修会は、本年度は２回実施しております。１回目は訪問させていただいて、さまざまな学校の人権教育の進め方について、一緒に研究をさせていただきました。","id":"exchange-046"},{"speaker":"松永委員","kind":"質問","question":"校長研修等では、本年度予算に比べて８４５万８,０００円から１,５３９万６,０００円と増えておりますけれども、内容が変わったのか尋ねました。","respondent":"村尾学校支援担当課長","answer":"この校長研修等の中に、実は学校経営監、指導員２名分の人件費が含まれているということで、金額的には大きくなっているというふうになっております。","id":"exchange-047"},{"speaker":"松永委員","kind":"質問","question":"次に、３５１ページのいじめ防止対策について伺います。それを受けて、この全国調査の内容と、また品川区ではどのような結果が出たのか説明を求めました。","respondent":"村尾学校支援担当課長","answer":"品川区でも文部科学省からおりてきた調査を実施いたしました。調査の内容は、「７日間連続して欠席し、さらに被害等、また暴力行為等、同様のものが考えられる事案はあるか」というような調査内容でございました。","id":"exchange-048"},{"speaker":"松永委員","kind":"質問・要望","question":"品川区でこういうことはないということであります。そのために、いじめ防止プログラムについてご説明ほしいと求めました。","respondent":"村尾学校支援担当課長","answer":"小学校の３年生と５年生が実施し、暴力を受けたときの対応の仕方であったり、またどのように相談をしていけばいいかというような学習です。それぞれ学校が実施し、それに付随してスクールバディというもので、そのような活動をしているプログラムです。","id":"exchange-049"},{"speaker":"松永委員","kind":"質問","question":"いじめ等根絶普及啓発では、前回たしか３１４万２,０００円から来年度は４１万３,０００円となっておりますけれども、その内容について改めて伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"これにつきましては、いじめ根絶協議会という協議会を立ち上げておりまして、そこでさまざまな議論をしております。各地域また関係団体にリーフレットを配る予定だったのですが、実際には来年度等を含めて検討していくということで、金額はこのようになっております。","id":"exchange-050"},{"speaker":"松永委員","kind":"質問","question":"次に、学級風土調査について伺います。この学校風土調査では、全校で７年生を対象にしていると伺っておりますが、なぜ７年生だけなのか尋ねました。","respondent":"村尾学校支援担当課長","answer":"いわゆる中一、品川区で言うと７年生、これについては全国的にもなかなかさまざまな問題が起きるということで上がっております。この７年生を対象に子どもたち、また指導に活かすため、７年生というふうになっております。","id":"exchange-051"},{"speaker":"松永委員","kind":"質問","question":"低学年に関しては、教員との、昔の交換日記のような方法をとってみてはいかがでしょうか。ぜひご検討いただけたらと思いますが、その点について伺います。","respondent":"村尾学校支援担当課長","answer":"この学級風土調査というものを小学校にといふうな考えはないのですが、逆にＱＵといういわゆる調査を小学校のほうに現在試験的に行っております。このＱＵ、小学校についてはそこで子どもたち、またはクラスの様子をはかっていこうというふうに考えているところです。","id":"exchange-052"},{"speaker":"松永委員","kind":"質問","question":"次に、３５１ページの教育相談事業と調査研究事業の内容について伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"心理職の部分、そして相談員の人件費等、またその教育相談センターで行っているさまざまな事例の研究、講師の謝礼等が含まれている金額です。音楽等の実技に関する研修を教員のほうが集まって、夏休み等が中心になるのですけれども、そのような形の部分になっております。","id":"exchange-053"},{"speaker":"松永委員","kind":"質問","question":"教育相談事業についてですが、品川区の教員の方から相談に来られたこともあると思いますが、相談内容とか、もしご紹介できたら伺いたいと思います。年間どのくらいの教員の方が相談に来られたのでしょうか、伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"かかってくる電話相談については２７４件と、やはり多くの相談が入っております。これにつきましては、それぞれセンターの心理士が、来室については親との相談や、また子どもとの直接相談等を含めて実際に進めているところです。","id":"exchange-054"},{"speaker":"松永委員","kind":"質問","question":"次に、調査研究事業についてですが、これは教員対象ということで、これは自主的に行うものなのでしょうか。そしてまた、何回も実技研修を行うことができるのか尋ねました。","respondent":"村尾学校支援担当課長","answer":"どのような実技研修を行っていきたいかということで、それぞれの各教科の代表から教育委員会のほうと調整をしまして、実際に進めているところです。一応基本的には予算取りもありますけれども、各年間１回、内容的には２回興行ということで行っているところが中心です。","id":"exchange-055"},{"speaker":"松永委員","kind":"意見","question":"最後に、今年の４月１日から設立予定の品川区立教育総合支援センターですが、いろいろな専門分野の方が対応できるセンターに生まれ変わろうとしておりますが、それに向けての意気込みを説明を求めました。","respondent":"村尾学校支援担当課長","answer":"今、委員からご説明していただいたとおり、今年の４月から実際に五反田にこの品川区立教育総合支援センターというものを設立いたします。それにおける対応力、より子どもたち、それから保護者の皆様にとって教育について十分な支援をしていきたいというふうに考えているところで…","id":"exchange-056"},{"speaker":"松永委員","kind":"確認","question":"最後に、３６５ページの学校運営費について伺います。ここでは１点だけの確認なのですが、平成２６年度には以前、平成２７年度では掲載されていない理由について伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"平成２６年度で補助が終了したものです。","id":"exchange-057"},{"speaker":"横山委員","kind":"確認","question":"３５３ページのイングリッシュキャンプ実施、３５５ページのしながわドリームジョブ、そして３６３ページの学校環境整備事業についての確認をします。ブリティッシュヒルズでのキャンプの詳細とグローバル人材育成塾受講希望者への周知方法、そして時期を説明を求めました。","respondent":"渋谷指導課長","answer":"今のところ、４月の第３土曜日に説明会を実施する予定です。イングリッシュキャンプの概要ですが、２泊３日を予定しておりまして、２泊３日のプログラムを考えているところです。","id":"exchange-058"},{"speaker":"横山委員","kind":"質問","question":"２点目なのですけれども、学校環境整備事業についてお伺いいたします。工事期間の授業、部活動など、生徒、保護者、近隣の地域の方々などへの影響と対策についてもあわせて説明を求めました。","respondent":"品川庶務課長","answer":"それから、工期につきましては、大体７月から工事を始めまして、完了は１月末となっております。近隣関係の周知に関しましては、これから説明会を行っていく予定です。","id":"exchange-059"},{"speaker":"横山委員","kind":"質問","question":"すみません、ちょっと今、私の質問がちょっと早かったのでもう一度申し上げます。近隣の方への影響と対策について、こちらを説明を求めました。","respondent":"品川庶務課長","answer":"近隣への影響ですけれども、土地の高低差が多少ありますので、擁壁工事等、そういう部分で振動等が発生する可能性が若干あるです。","id":"exchange-060"},{"speaker":"横山委員","kind":"質問","question":"次、３点目なのですけれども、品川区研究学校についてお伺いいたします。教えて考えさせる授業がありますが、平成２７年度品川区教育委員会教育研究校、ご説明ください。","respondent":"渋谷指導課長","answer":"今、委員がご説明いただいたのは、第二延山小学校が研究学校として１年次の中間発表を行ったものです。特に算数等々を中心にしながら、１年生から６年生までの提案授業実践の発表と、そういった事例研究もあわせて行ったというふうに聞いております。","id":"exchange-061"},{"speaker":"横山委員","kind":"質問・要望","question":"ノートの見直しを習慣化するような学習法を指導することによって、児童みずからが学習のつまずきを確認、改善する機会を得ることができると考えます。１年目の成果を教育委員会としてどのように捉え、区全体の学力向上に活かしていくお考えなのか、２年目の研究内容と課題についてもお伺いいたします。","respondent":"渋谷指導課長","answer":"２年次につきましては、２年次の発表で広く区内の学校に周知をさせていく、そんなふうに聞いているところです。どのような声かけがいいのか、見守り方がいいのか等について、ぜひ提案をしていただきたいと考えているところです。","id":"exchange-062"},{"speaker":"横山委員","kind":"質問・要望","question":"そこでお伺いいたします。将来の夢を持ち、かつその実現に向けて具体的に努力をする児童・生徒を育てるために、どのような指導、そして支援が必要か尋ねました。","respondent":"渋谷指導課長","answer":"１年生ではＣＡＰ、８年生でファイナンスパークというように、社会の仕組みや経済のことを知るということがまず大きな流れの中であります。これもこれからなのですけれども、子どもたちがこんな人になりたいと思ってもらえるような、すばらしい機会にしたいと考えているところで…","id":"exchange-063"},{"speaker":"横山委員","kind":"質問・要望","question":"２分の１成人式では、お母さんが介護士として働く姿を見て、自分もお母さんのような介護士になりたいという児童がいました。児童への価値ある複数の選択肢の発見を支援していただきたいと考えますが、最後に説明を求めました。","respondent":"渋谷指導課長","answer":"まさに今検討しているところで、今後、教育大使のような形でさまざまな場面でかかわり合っていただきたいというふうに考えているところです。実施学年については、今のところ４年生を想定しています。","id":"exchange-064"},{"speaker":"塚本委員","kind":"質問","question":"私からは、３５７ページの特別支援教育費と３６５ページの学校運営費に関してだと思うのですけれども、この２点についてお伺いしたいと思います。３５７ページの特別支援教育費に関連してなのですが、また中学校、今どのような設置になっているのかということを最初にお伺いしたいと思います。","respondent":"村尾学校支援担当課長","answer":"品川区においては、情緒学級の固定級というものはございません。","id":"exchange-065"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。今の品川区の区立の小中学校の中でどういう形で指導というか、学校を勧めるか、お伺いします。","respondent":"村尾学校支援担当課長","answer":"いわゆる情緒障害等における固定学級を設置しているのは、２３区内では小学校が３校、そして中学校が２校というまだ現状です。さまざまな部分を総合的に考えて、保護者につきましては、そのような形で現在は通級学級ということでご理解いただいているところです。","id":"exchange-066"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういう中で、固定級の中でしっかりとしたそういう対応をしていただきたいという要望が、やはり一定程度あるのだろうと思うのですね。この中で、中学校に設けていくという必要性もあるのではないかと思いますので、もう一度その点についてご答弁ほしいと求めました。","respondent":"村尾学校支援担当課長","answer":"実際にそのような声があることについては十分承知しています。今後、国また都全体の流れ等を踏まえまして、しっかり検討していくことになるかなというふうに考えております。","id":"exchange-067"},{"speaker":"塚本委員","kind":"質問","question":"１７号でしたでしょうか、その翌日の登校をどうするかという対応のことで、昨年の決算特別委員会でも少し質疑があったかと思います。そのことを受けて、２月６日の大雪のときもまた同じような対応で現状もしているということについて、まず最初に区のご見解をお伺いします。","respondent":"村尾学校支援担当課長","answer":"大雨、それから台風等への対応についてのご質問です。それから保護者のほうには今委員のご説明いただいたとおり７時、こちらでもさまざま検討したのですけれども、また急に対応を変えるよとなると。","id":"exchange-068"},{"speaker":"塚本委員","kind":"質問・要望","question":"せめて当日の朝７時ぐらいまでには判断していただけないものかというような話も聞いておりますので、次のそういったときには検討ほしいと求めましたけれども、最後にご答弁をお願いいたします。","respondent":"村尾学校支援担当課長","answer":"今まさにこちらのほうで検討し、また校長役員会等でも検討している中で、７時の時点での判断というふうに方向性としては考えております。これについてもさまざまな意見を聞きながら検討したいと思います。","id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問","question":"このＨＥＡＲＴＳ、また学校現場でつかんでいる現在のいじめや学校の現状、そしてまた問題や課題が今あるのかどうか伺いたいと思います。教職員みんなで話し合う場は、学校ごとにあるのか、そういう仕組みがつくられているのか伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"２番目については、品川区でいじめ等さまざまな問題が起きたときに対応できるということで、ＨＥＡＲＴＳが区に設置されました。それぞれの学校がどのような体制をとっていくかという、組織で対応する、そういうような形で学校では取り組んでいるところです。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"一般紙の調査でも７割以上が時間が足りないということを教員が答えているわけですね。このような状況を一刻も早く改善させるべきだと思うのですけれども、いかがか尋ねました。","respondent":"村尾学校支援担当課長","answer":"そういうような関係づくりについては区のほうも各学校、また先生方に声をかけながら、ぜひ協力をしていただいているところです。教員だけではなくて、そういうような触れ合う時間も特に大切にしてほしい、そのような形でいじめの早期発見については努めているところです。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"教員は休みを潰して働いても、肝心の子どもと遊んだり向き合う時間を日ごろからも持てないと悩んでいるのですね。先生の多忙化、そういった子どもと教員が一緒に向き合って信頼関係をつくっていく条件をつくっていくべきだと思いますけれども、いかがか尋ねました。","respondent":"村尾学校支援担当課長","answer":"委員おっしゃるとおり先生とそれから児童・生徒との信頼関係、これは本当に大事なことだというふうにこちらも考えております。例えば会議を少し減らしていくとか、また放課後なるべく会議を入れないような工夫は、それぞれの学校が今取り組んでいるというふうに聞いております。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういった一つ一つの例を見れば、時間をつくっていく手だて、条件を整備していくということを一刻も早く本当に進めていっていただきたい。ですので、教員と子どものストレス、そして多忙化の関係をどうお考えか尋ねました。","respondent":"村尾学校支援担当課長","answer":"担任、それから保護者がどのような形で連携をしていくか、その辺については現在も各学校が十分取り組んでいるところです。いろいろな場面で学校では対応しておりますし、異変に気付くような、そういうようなことで考えていければというふうに思っております。","id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり、私はこの子どものストレスや教員の多忙化、そして親たちも本当に忙しい大もとには、政治があると思います。平成２６年度の予算には、平成２７年度、非正規の雇用形態に変わりはあるのかちょっと伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"おっしゃるとおり、スクールカウンセラー等派遣費という部分が今回は巡回相談員等経費という形で変わっております。そこを２週間に一遍、学校の支援をしていく、そういうような形になっております。","id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、子どもたちと接するというか、学校に行く回数が減ったということなのか、そして人数は変わりないのか、そして雇用形態も伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"区内の小中学校を１０ブロックに分けて、そこを２週間に一遍、配置するです。勤務については全て非常勤職員ということで進めているところです。","id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"では人数が減っているということですね。ぜひ増やしていただきたい、いじめを学校からなくしていく、この対策を強化してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"井上委員","kind":"質問","question":"私は、３６７ページの教育振興費の就学援助費と、３４９ページの教育指導費、巡回相談員等経費についてお伺いをいたします。この答弁の真意を伺います。","respondent":"野呂瀬学務課長","answer":"それと、社会状況の変化です。そういうのを総合的に勘案して、それで社会状況の変化を見極めながら判断する、そういうことでご答弁申し上げたです。","id":"exchange-077"},{"speaker":"井上委員","kind":"質問・要望","question":"この就学援助費は大切にしていただきたいと思うのですけれども、これは要望として、取り組んでいただきたいというふうに思います。次、そして変更したことで解決が図られるのか、そして期待される成果についてどのようなものを持たれているのかお伺いをいたします。","respondent":"村尾学校支援担当課長","answer":"さまざまな対応しておりますので、今度は巡回相談員ということで、また今までは小学校に区費のスクールカウンセラーは配置されておりませんでした。小学校と中学校をグループで回ることによって子どもたちの９年間の学びの一つの視点としてカウンセラーが対応できるというふうに…","id":"exchange-078"},{"speaker":"井上委員","kind":"質問","question":"教育委員会とか指導者側がどういうふうな合理的配慮とか、子どもたちが抱える心の問題について対応しようということだったと思うのですけれども、それについてきちんとそこが保障されるのかというところについてはいかがか尋ねました。","respondent":"村尾学校支援担当課長","answer":"その部分につきましては、まさに心の部分についてはそれぞれの都費、また区の巡回相談も同じような形で子どもたちにかかわることについて変わりはございません。","id":"exchange-079"},{"speaker":"井上委員","kind":"質問・要望","question":"そこにもっと早く福祉が介入することが必要だったのではないかというふうに思っております。福祉の視点で子どもを救済できたケースというのは、区内にあったのか、そのような事例があれば紹介してください。","respondent":"村尾学校支援担当課長","answer":"まさに来年度からスクールソーシャルワーカー４名ということで、より幅広く子どもたちの対応ができると考えております。保護者といわゆる福祉のほうの区の行政側に橋渡しをして、そのような形で進めていく、そういうような話を聞いております。","id":"exchange-080"},{"speaker":"井上委員","kind":"意見","question":"具体的には橋渡しと。子どもをいかにいろいろな環境資源を使って救っていくかということなのですけれども、紹介できる範囲で、もう少し具体的にお願いしますとの意見を述べました。","respondent":"村尾学校支援担当課長","answer":"具体的にはちょっとなかなかこういう場で説明が難しいところなのですが、それから本人の結びつき、環境整備について進めているところは多くあります。","id":"exchange-081"},{"speaker":"井上委員","kind":"質問・要望","question":"ですから、結果的に子どもを追い詰めてしまうので、ぜひ信頼し合って事業を進めていただきたいというふうに思います。私も見にいってきましたけれども、やっぱりモデル事業を持っている品川区ですから、ぜひご覧ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"沢田委員","kind":"質問・要望","question":"３５７ページの教科書採択事務についてお伺いをします。この委員会について、それからどれくらいの期間で、どのような客観的な調査を行っているのかを詳しく説明を求めました。","respondent":"渋谷指導課長","answer":"教科用図書調査検討委員会では、今ご説明申し上げた１５名以内の委員が適正に資料ができているのかどうかということを検討して。資料の作成については７月上旬ぐらいまでをめど行いまして、その間、できたものからこの教科用図書調査検討委員会のほうに教科ごとに上げて。","id":"exchange-083"},{"speaker":"沢田委員","kind":"質問","question":"必要な客観的な調査というのは、ここでやられているということでしたけれども、具体的にどのような調査をされているのか、その前段階での教職員の方たちによる教科書調査研究会から上がってきた教科書に関するデータをもとにした客観的な調査というのはどういったことをされているのか説明を求めまし…","respondent":"渋谷指導課長","answer":"具体的に申し上げますと、調査研究における調査基準というものがこの要領で定められております。学習活動、地域性など六つの項目に関してかなり細かく実際研究会のほうで現場の先生方が詳しく分析したものを検討委員会に上げているという手順です。","id":"exchange-084"},{"speaker":"沢田委員","kind":"質問","question":"昨年の一般質問の中でも、教科書採択の採択理由を明確に公表すべきという質問に対して、採択理由も公表するという答弁を区からいただきました。この採択理由を公表するということについて、これをどのような形で公表をされていくのか、内容等、方法等についても聞きたいと思っています。","respondent":"渋谷指導課長","answer":"この要綱、要領については、今後きちっと公開するということで見直す予定です。内容、方法については、ただいま研究中ということで、今この場で確定的なことは申し上げられません。","id":"exchange-085"},{"speaker":"沢田委員","kind":"質問・要望","question":"先ほどそういったいろいろなことがそこで話し合われているということをぜひ情報公開というか、公開をしていっていただきたいなと思います。そういったところのお考えというか、点数化して、しっかりと評価をしていくということに関するお考えを説明を求めました。","respondent":"渋谷指導課長","answer":"今後検討していくところですが、その部分での評価基準をどういうふうにするのかというところが大変難しい問題だというふうに思っております。それぞれの項目に基づいて…","id":"exchange-086"},{"speaker":"沢田委員","kind":"質問・要望","question":"ただ、これからの日本を背負っていく子どもたちがしっかりとその教科書をもとに勉強していくわけですから、それをしっかりとした過程で。教育基本法の理念をしっかりと遵守した教科書の採択をしっかりと進めていっていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"大倉委員","kind":"提案","question":"これはどこにあるのですかというところの質問とか、どういう理由で参加するのか、ちょっと教えてほしいと求めました。その際に、まもるっちに相談番号を登録してはどうですかというご提案をさせていただいたときに、どういった検討がされたか教えていただきたいとの意見を述べました。","respondent":"品川庶務課長、上垣外生活安全担当課長、小林施設整備課長、村尾学校支援担当課長","answer":"地元の町会に子どもたちが参加しないという点でご説明はいたしましたが、それ以外にもいろいろな効果を考えて、この事業をしております。… 窓口対応するまもるっちセンターのオペレーターも相談の専門ではありませんので、この場所で対応するのは難しいだろうというふうに考えています。… 今も毎月１回、目視により全面を見ております。その報告をもとに最近の床の隙間等はかなり落ち着いてきたかなという考えを持っております。 現在品川区の中学校にアイシグナルといういわゆるいじめ対策のものについて…","id":"exchange-088"},{"speaker":"大倉委員","kind":"質問・要望","question":"番号を登録してはどうですかということだったのですけれども、なかなか難しくて、窓口が多いという部分で必要だと思ったので聞きました。学校の床なのですが、これはそのままずっとその対応をしていくしかないのかなというところを教えてほしいと求めました。","respondent":"小林施設整備課長","answer":"床下の換気量が過大過ぎたのではないかということがありましたので、まずはその対策を講じていきましょうということで装置をつけたところです。その後、隙間が落ち着いてきたというのが目視でわかりました。","id":"exchange-089"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３６１ページの地区図書館運営費、３６３ページの学校環境整備事業、３６９ページの小中一貫校標準服費、この３点でお伺いします。おおよそで結構です、冬服で１人当たりどれぐらい金額がかかっているのか、説明を求めました。","respondent":"中元品川図書館長、品川庶務課長、野呂瀬学務課長","answer":"迅速な対応に努めていきたいです。児童サービスにつきましても、職場体験の受け入れも全地区館も含めて対応する予定で、現在調整を行っているところです。 土のグラウンドなのですけれども、おおむねですけれども、大体３５校程度が土のグラウンドとなっています。そこの水たまりに少しかぶせて… １５校、中学校はありまして、大体２万７,０００円から３万３,０００円、３万４,０００円の範囲ですので、平均しますと３万円ぐらいかなです。…","id":"exchange-090"},{"speaker":"こんの委員","kind":"提案","question":"それから、宅配というようなサービスを妊婦さんとかあるいは高齢者の方にもどうなのでしょうかというところもお願いしたいと思います。コストを工夫して、買い替えられるような状況をという声がありますけれども、いかがか尋ねました。","respondent":"中元品川図書館長、野呂瀬学務課長、品川庶務課長","answer":"１点目のカートの導入ですが、ちょっと実施に当たっては検討する課題が大きいかなと考えています。ただちょっと妊婦さんにつきましては、申し訳ないのです… 制服の件です。基本的に制服は私費でやっていただくものですし、今後コストが安くならないかはご意見として伺っておいて、学校のほうに伝えたいと思います。 校庭の件につきましては、何かいい事例等があるかどうかもいろいろ今後研究していきたいと思いますので、よろしくお願いいたします。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"防災ヘルメットなのですが、設置状況はどういうふうになっているでしょうか。それと、どこに保管していますかということをまずお聞きしたいと思います。","respondent":"野呂瀬学務課長","answer":"設置状況ですけれども、３・１１以降、その翌年に全中学生に配りました。保管ですけれども、基本的に机の横だとかに置いて、すぐ使えるような形にしているです。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"７年生に配付をして訓練をしているよ、保管のほうは何か邪魔になっている部分があるのですよね。折り畳み式ですと持ち歩きもできるということで、非常にいいものが出ているので、ぜひご検討してほしいと求めましたのでいかがか尋ねました。","respondent":"野呂瀬学務課長","answer":"うちで配付しているのは、品川区のマークがついて、しかも学校名もついているようなヘルメットです。それとやはり、折り畳み式は強度の面だとかコストの面でいろいろ課題があるということで、今配付は普通のヘルメットをしています。","id":"exchange-093"},{"speaker":"西本委員","kind":"質問・要望","question":"そのアンケートは、こそこそ話は何を話しているのですか。啓発の取組みをやっていますけれども、少し見直しを図ってはどうかと思うのですが、品川区の見解をお聞きします。","respondent":"村尾学校支援担当課長","answer":"まさにいじめ防止に向けて児童みずからがかかわりを持ちながら取り組んでいこうと、その中で、大変重要な取組みだと考えております。やはり子どもたちがみずから自分たちでいじめをなくそうと、そういうような取組みについては、今後とも進めていきたいと考えております。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"そして、小中一貫校は６校で終わりなのでしょうか。一応６校で終わりですよということなのですが、全くそれは考えないという方向でいくのか、いかがか尋ねました。","respondent":"品川庶務課長","answer":"一貫校の件ですが、６校までということで言い切ることはできないというような状況です。ただ、今後つくっていくというところに関しましては、いろいろと研究をしながらやっていきたいと考えております。","id":"exchange-095"},{"speaker":"西本委員","kind":"質問","question":"と考えています。いろいろ５年先なのか、１０年先なのか、その辺のご意見はいかがか尋ねました。","respondent":"品川庶務課長","answer":"改築に関しましては、先ほど言いましたように老朽化の順番等を考えていきたいと思います。","id":"exchange-096"},{"speaker":"渡辺委員","kind":"質問","question":"３５３ページ、合同部活動実施経費を中心に関連も含めて伺っていきます。自分たちが子どものころ、学生のころというものと照らし合わせるご感想というのは結構あるものですから、そういったところの比較ですよね。","respondent":"渋谷指導課長","answer":"全体で言うと中学校の場合は１０％ぐらいのお子さんが部活動の状況というのを、中学校の入学の希望理由に挙げているです。特に女子の中学生については運動離れが進んでいるということが現実として認識されているのかなというふうに感じているところです。","id":"exchange-097"},{"speaker":"渡辺委員","kind":"質問・要望","question":"この点の仕組みをどうしていくか、意向をくみ取るといいますか、要望をくみ取るのを今後どのように発展させていくかを聞きたいのが一つです。現在、重立った点で現場の先生方が部活動を、いろいろな忙しさの中で優先できるような配慮がどうなされているのかを説明を求めました。","respondent":"渋谷指導課長","answer":"そういう意味においては、なかなかとっても実現できない意向調査等は行っていないし、行う予定がないというのが今の実情です。授業だったり、通常の教育活動をやる、部活動をやるがために何らかの公務が軽減されるということは基本的にないというのが実態です。","id":"exchange-098"},{"speaker":"渡辺委員","kind":"質問","question":"こういうところでの含み、応用というのは、考えられるのかどうか、伺いたいと思います。あるいは地域力との協働といい、かなり僕は大きなウエイトを占めていると思いますので、そのあたりの考えも最後にまとめて伺えればと思います。","respondent":"渋谷指導課長","answer":"その活用の中でどういうふうに子どもたちの体力向上を図っていくのかという流れの中で部活動のやり方についてもあわせて研究させていただきたいと考…いずれかの形で、また文化・スポーツに推進できるような体制について…","id":"exchange-099"},{"speaker":"向委員","kind":"質問","question":"グローバル教育についてお伺いしたいのですが、３５３ページ、ほかの委員からも先ほど幾つか質問が出ていました。中世の英国のそういった環境の中で語学研修を行うということで、ちょっとだけ気になったので先に教えてほしいのですが、それを説明を求めました。","respondent":"渋谷指導課長","answer":"ああいうマントを部屋ごとに貸し出してくれたり、またそういった文化そのものを体験するです。イギリスとか、その部分での違いを大きく感じるようなところはないので、子どもたちの戸惑いはないかなというふうに思っているところです。","id":"exchange-100"},{"speaker":"向委員","kind":"質問","question":"品川区のグローバル教育についてお伺いしますが、来年度も本当にさまざまな新規事業が出てきています。最初にお伺いしたいのは、海外留学をする子どもたちの数を増やしたいとか、ちょっと簡単にお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"就職活動をするときには、近隣の東南アジア諸国の人たちとも一緒に面接を受けたりするような状況もきっと想像できます。近くは、国際的な窓口となる品川区としては、堂々と自信を持って活躍できる子どもたちをぜひ品川区では育てていきたいと考えているところです。","id":"exchange-101"},{"speaker":"向委員","kind":"質問・要望","question":"１０位以内に入っている大学は国公立で幾つあるでしょうかというような状況にもあり、本当に危機感を抱いているということで、なぜかというと。やっぱりできるだけ外に出てほしい、自己負担、これは基本的に自己負担は必ずしなければならないということですよね。","respondent":"渋谷指導課長","answer":"基本的には宿泊費と食費の部分については、これは日常生活してもかかるわけですので、その部分について自己負担をしていただくと。研修費や交通費については公費で負担でということで考えているところです。","id":"exchange-102"},{"speaker":"向委員","kind":"質問・要望","question":"同時に日本のことを学んだり、知ったり、このあたりについてのお考えというのはいかがでしょうか。もちろん自分が、このあたりは本当に区の事業としてもバランスのよさというものを求めていきたいなと思うのですが、お考えをお願いします。","respondent":"渋谷指導課長","answer":"昨年の５月に派遣された子どもたち、各中学校に戻って、その成果を自信満々に発表してくれたりだとかというようなことがあります。そういった子どもたちが生き生きと表現できる機会というものを今後もぜひ多く取り入れていきたいと考えております。","id":"exchange-103"},{"speaker":"向委員","kind":"質問","question":"知力と体力の限界に挑戦するというのですか、そういったところで得られるものというのは本当にはかり知れないものがあります。そういったところも、そして区のリーダーシップのもとにそういった心とさまざまな経験を育んでいってくれればいいなと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"},{"speaker":"山元委員","kind":"提案","question":"昨年１人でも多くの子どもたちに本を読んでほしいという思いで、夏のスタンプラリーを提案いたしまして、そんな喜びの声を聞きました。今回図書１万８,０００冊ですか、子どもたちにとって興味深い本を選んだかなと思いますが、その辺の基準はどのように選んだのか説明を求めました。","respondent":"中元品川図書館長","answer":"１点目の不読率の目標ですが、目標として、不読率としてはとってございません。学校教育に関連するもの、また子どもたちが本の中で想像力を広げて、情操教育に寄与するものを配慮して選定しています。","id":"exchange-105"},{"speaker":"山元委員","kind":"質問・要望","question":"読書履歴というのですかね、何冊読んだとかということで、５０冊読むごとにそこは何か特製のしおりをいただけるという話です。この辺、今すぐとは言いませんが、先々何かこういうＤＶＤとかを返す方法を、何か簡単な方法を考えてほしいと求めましたが、いかがか尋ねました。","respondent":"中元品川図書館長","answer":"ちょっと課題が大きいところでございまして、ちょっとしばらく、当面ちょっと実施は難しいのかなと考えています。大井町と武蔵小山の行政サービスコーナーのほうも少し時間をずらして長い時間営業しておりますので、そちらのほうをご活用いただければと存じます。","id":"exchange-106"},{"speaker":"山元委員","kind":"質問","question":"ご遠慮くださいというのは当然なのですけれども、結構館内で電話をどうしようと、いろいろ緊急の電話に出なければいけないということがあります。その辺、図書館に携帯電話ボックスというのですかね、その辺のお考えはいかがか尋ねました。","respondent":"中元品川図書館長","answer":"設置するのは、４階の上のところに飲食コーナーがございまして、そういう状況です。","id":"exchange-107"},{"speaker":"山元委員","kind":"質問・要望","question":"緊急の電話ですので、４階まで走ってというのはあれなんですが、どうか前向きに考えてほしいと求めました。どうか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-108"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この点を質問しますけれども、どのように変わっていくのか、また内容について教えていただきたいのが１点。特別支援学級、固定級がどうなっていくのか、あと情緒障害等の通級学級がどう変わっていくのか、この３点を説明を求めました。","respondent":"村尾学校支援担当課長","answer":"３点目の通級学校はどう変わるのかと多分一緒のセットでご説明をさせていただければと思いますが、２回通っている現状があります。これが実際の支援教室モデルの今の状況で言いますと、また支援をしたりするという形に変わるというのが今回の支援教室モデルです。","id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その子だけで、通級学級をなくさないでほしいという親御さんたちの声がかなり聞こえてくるのですけれども、そこを教えていただきたいのが一つです。総合的、教員の配置がこの変化によってどういうふうになっていくのかを教えていただきたいのが１点です。","respondent":"村尾学校支援担当課長","answer":"現段階では、いわゆる通級学級をすぐになくすという考えではなくて、訪問して個別に対応できるようなパターンというふうに現在考えているところです。本年度も、また昨年中も特別支援教育の研修会をやっておりますし…","id":"exchange-110"},{"speaker":"飯沼委員","kind":"質問・要望","question":"普通学級と特別支援学級との交流、どのような位置づけになっているのか、１点教えていただきたいのが一つです。介助員と学習支援員のところを必要な時間をつけてほしいという要望も届いているのですが、どのような基準で配置をされているのか説明を求めました。","respondent":"村尾学校支援担当課長","answer":"１点目なのですけれども、これはやっぱり設置校についてはさまざまな形で現在交流は進めているということはこちらのほうで認識しております。来年度以降、学習支援員については各学校づきということで…","id":"exchange-111"},{"speaker":"飯沼委員","kind":"質問・要望","question":"把握はできているのでしょうか、そういうのもあるのでしょうかというところで、ぐっと交流学習が減ってしまったということです。その辺がやはり十分付くような予算を組んでいただきたいなと思うので、その点を伺わせていただきます。","respondent":"村尾学校支援担当課長、品川庶務課長","answer":"介助員と支援員の関係についてのご質問ですが、実際に新１年生のいわゆる固定級のお子様が結構増加したに当たって、現状です。学習支援員につきましては、また担任による対応だけでは十分な効果が期待できない… 傍聴人の人数につきましては、これを３０人に拡大しているという経緯もありますので、現在のところ３０人以上に拡大する考えはございません。そういう中で、基本的にはスピード感を持つためには今の状況を続けていきたいと…","id":"exchange-112"},{"speaker":"飯沼委員","kind":"質問","question":"時間がなくなって、トイレなのですけれども、改築の順番は決まっていないようですけれども、トイレがとても汚くて、子どもに選ばれないというところで、ぜひ改修を前倒しでやってほしいのですが、いかがか尋ねました。","respondent":"品川庶務課長","answer":"各校の状況によって全体的に、総合的な考えで改修は行ってまいります。","id":"exchange-113"},{"speaker":"松澤委員","kind":"質問","question":"２点目が２項の学校教育費に関連して、３６３ページ、防災教育についてお伺いしたいと思います。あれが文化財になるのかならないのか、その辺の基準、どのように基準をしてこれは選んでいるのか尋ねました。","respondent":"品川庶務課長","answer":"絵馬の文化財指定の基準ですけれども、基準につきましては、制定年代、それから文化財的な価値、希少性等も踏まえまして文化財保護審議会で決定をしているというような状況です。","id":"exchange-114"},{"speaker":"松澤委員","kind":"質問","question":"当然文化財ですから、補助金が出ているのかどうかわかりません。これの修復なんかをしたときに費用が出るのかどうか、あるいは修復したらだめになってしまうのですかね、その辺、いかがか尋ねました。","respondent":"品川庶務課長","answer":"絵馬の修復に関しましては、現在のところ区の指定文化財、これに入っておりますと、基本的には補修等をした場合には、経費の５割から６割、これを補助するというようになってあります。","id":"exchange-115"},{"speaker":"松澤委員","kind":"質問","question":"あるいは住居跡というものがあるということで、私も何回か見ているのですけれども。ただ、「掘るときは慎重にしてくださいね」というようなことが保護審議会のほうから言えるのかどうか、その辺をちょっとお聞きしたいと思います。","respondent":"品川庶務課長","answer":"こちらは文化財保護法によりまして、必ずこういう工事をやるときには届出をするということになっておりますので、その法に準じて行っていただくということになってあります。","id":"exchange-116"},{"speaker":"松澤委員","kind":"質問・要望","question":"崖から区道１本、家を潰してやりますので、この辺の工事を慎重にしていただきたい。こういうものが含まれているという話は聞かないのですけれども、品川区ではそういう建物についての文化財保護という規定はないのか尋ねました。","respondent":"品川庶務課長","answer":"品川区内で今建物の文化財指定、指定文化財は一つあります。１か所、居木神社末社、これの旧松原家屋敷神というところが指定をされてあります。","id":"exchange-117"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、木造の建物が文化財として登録される条件みたいなものはありますでしょうか。その辺、ちょっと詳しくお願いします。","respondent":"品川庶務課長","answer":"文化財登録に関しましては、ちょっと先ほどと答弁が重なるところもありますが、やはり文化財価値、それから希少性等、この辺の部分を文化財保護審議会で検討して決定するというような流れになってあります。","id":"exchange-118"},{"speaker":"松澤委員","kind":"質問","question":"それで、結構です。もう１点のほう、１週間か知りませんけれども、どれぐらいこれに時間をとっているのかをお聞きいたします。","respondent":"村尾学校支援担当課長","answer":"防災学習におきましては、時間数ははっきりお答えすることは難しいのですが、社会科の学習、それから保健体育の中の５・６年生で行っています。１・２年生から８・９年生まで、それぞれ地震また火災等の対応、また活動の方法等について学習をしています。","id":"exchange-119"},{"speaker":"松澤委員","kind":"質問","question":"平成２７年度に防災活動の若手の育成に乗り出すということで、全区立中学１０校に「防災部」というものをつくって、救命訓練などを日常に行う。これはやはり、これほど荒川区が力を入れようというのですけれども、品川区での取組みはいかがなものか尋ねました。","respondent":"村尾学校支援担当課長","answer":"この荒川区の「防災部」という取組み、大変興味深い、そして全国でも本当に珍しい取組みだということで、私もマスコミ、新聞を通して知りました。ただ、区のほうでこの被災地のほうに子どもたちをということは考えてはいないのですが…","id":"exchange-120"},{"speaker":"松澤委員","kind":"質問・要望","question":"荒川区では、こういう訓練を通じてどうするかというと、こういう訓練をするのが自助・共助の本当の根本かというふうに思っているのですよ。一度視察に行って改めて本会議で質問しなくてはと思っているのですけれども、改めて子どもたちの防災教育について一言ほしいと求めました。","respondent":"村尾学校支援担当課長","answer":"あくまでも中学生は義務教育という中で、体は大きいのですが、やはりさまざまな部分での判断力については課題がまだあるかなと思っています。例えば物資を運ぶとか、その辺で中学生としてできる範囲の活動について考えていこうと、それは思っております。","id":"exchange-121"},{"speaker":"高橋委員","kind":"意見","question":"それから、３５７ページ、グローバル人材育成塾についてお尋ねします。そして、今年度、昨年度で結構ですので、その小中学生の自転車による事故が、どれぐらいあるか、もしおわかりになればお願いしますとの意見を述べました。","respondent":"村尾学校支援担当課長","answer":"１点目の自転車安全教室の実施についてのお尋ねです。乗り方について、教室での指導とさまざまな形で交通安全、いわゆる自転車安全教室を実施しています。","id":"exchange-122"},{"speaker":"高橋委員","kind":"質問","question":"１５件が自転車との関係と、対人や対物の、賠償責任が生じた例は先ほどの事故の中であるのでしょうか。そして、そういった自転車保険というのでしょうか、それに加入しているかどうかを学校としては把握をどの程度されているか。","respondent":"村尾学校支援担当課長","answer":"２点のご質問だと思います。それから２点目、子どもたちが自転車事故等の賠償保険の加入をしているかどうかについては、その辺の調査をしたことはございません。","id":"exchange-123"},{"speaker":"高橋委員","kind":"質問","question":"たしか２００円でしょうか、学校によって違うのですが、入っています。ほかの自治体で学校の判断で入っているところがあるのですが、こういった保険の存在についてどのようにお考えか尋ねました。","respondent":"品川庶務課長","answer":"若干ちょっと営利の部分もありますので、教育委員会としてどのようにご紹介できるかというのは、少し難しいところではあるかというふうに思います。これはＰＴＡがいろいろな保険を見ていただいて、その中で一つ判断するものだというふうに教育委員会としては考えてあります。","id":"exchange-124"},{"speaker":"高橋委員","kind":"質問","question":"グローバル人材育成塾のほうなのですが、先ほど成果についてお話しいただきましたけれども、その一方で、課題が幾つかあったと思います。その課題についてご説明をお願いします。","respondent":"渋谷指導課長","answer":"グローバル人材育成塾については、２月末現在で３９９人ということで、約１００名の子どもたちが何らかの理由で通うことを中断しました。それから３年生、９年生の場合は受験のため、そんな課題を踏まえて次年度は改善していきたいというふうに考えているところです。","id":"exchange-125"},{"speaker":"高橋委員","kind":"質問・要望","question":"平成２７年度の授業がぜひレベル分け等、期待を持って塾を受講している中学生の気持ちに応えるような授業にしてほしいと求めました。これは教育委員会のほうに申請してオーケーが出たといいますが、これに対する評価はどのようなことか尋ねました。","respondent":"渋谷指導課長","answer":"宿泊行事の開始予定については、４年生段階から宿泊行事に取り組むということについては、先生方の評価も分かれるところであります。ここの部分については、学校の取り組みについて注視してまいって、成果があれば広く進めてまいりたいというふうに考えているところです。","id":"exchange-126"},{"speaker":"高橋委員","kind":"意見","question":"５年生の初めての宿泊、日光につながる実績のある宿泊研修ですので、教育委員会としてもバックアップのほうをお願いいたします。これは特色ある教育活動経費ではないので、独自の中でやっていらっしゃるので、そこをフォローしていただけるとよろしいかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-127"},{"speaker":"あべ委員","kind":"質問・要望","question":"それから３４９ページの教育指導費全般にかかってくるかと思います、それから３５７ページ、これは簡単な確認です。それから、３５９ページ、図書館について、特に資料費の部分についてお伺いしたいと思います。","respondent":"村尾学校支援担当課長","answer":"実際に今まで２名で動いていたものが４名になることで、一貫校というような形にしようか、今それはまさに検討させていただいているところです。川崎の事件ではありませんが、問題行動、非行等についても十分対応していこうというふうに考えております。","id":"exchange-128"},{"speaker":"あべ委員","kind":"提案","question":"どうしても報告で上がってきたところから動き始めると取りこぼしもあると思いますので、現場重視で動いてほしいと求めました。以前提案したものとしては大変うれしいのですけれども、待ってもらうのか、あるいは予算をさらにつけるのかということで対応について説明を求めました。","respondent":"村尾学校支援担当課長","answer":"平成２５年度から進めているさまざまな各学校の取組み等を紹介する中で、学級の様子を調べてみたいということで、現在は増えている状況です。希望がございましたら、これにつきましては推進している現状です。","id":"exchange-129"},{"speaker":"あべ委員","kind":"質問・要望","question":"プラスして何かの折に、ぜひこの分野での教員研修というのも力を入れていただきたいとともに、非常に勇気付けられる子どももいるかと思います。こういったことはすぐできることですので、ぜひやっていただきたいと思うのですが、一言お願いします。","respondent":"村尾学校支援担当課長","answer":"その辺につながる危険性もありますので、未然防止を進めるのは重要だということで、国のほうからも伝えられております。このような流れを踏まえまして十分こちらのほうでも検討させていただきたいと考えています。","id":"exchange-130"},{"speaker":"あべ委員","kind":"確認","question":"私は一番基本にあると思っているのですが、その点、教育委員会としてはどのようにお考えかということを確認したいと思います。地区館のほうは資料費として出ていないけれども、実は委託費の中に入っているとか、何かそのような形のことなのか尋ねました。","respondent":"渋谷指導課長、中元品川図書館長","answer":"教科書採択についてお答えいたします。先ほどもご答弁申し上げたとおり、委員ご指摘のとおり教育的な観点からどうかというところは大変重要な点であるというふうに考えております。 ６億４,３５４万５,０００円という中に資料費も入ってお渡しをいたします。全体のスキームとしては縮小しているものではございません。","id":"exchange-131"},{"speaker":"あべ委員","kind":"確認","question":"ある程度業者に任されるのかなと思いながら、選書の全体のバランスがどうなるかと思っておりましたので、今のご答弁を伺って安心しました。これの簡易鑑定というのでしょうかね、例えば大崎図書館で、そういったものを保管するような可能性はあるかどうかというのをちょっとお伺いします。","respondent":"中元品川図書館長","answer":"基本的な考え方といたしまして、大崎図書館移転先のほうに共同書庫のほうも今段階では持っていく方向で検討している状況です。本を置いている場合も除湿器を常に２台稼働させているような状況ですので、大変申しわけございませんが、辞退をさせていただきたいと思います。","id":"exchange-132"},{"speaker":"あべ委員","kind":"質問","question":"すみません、新しいほうの書庫でというふうな意味でお伺いしました。","respondent":"中元品川図書館長","answer":"新しいほうの書庫、まだちょっと現在準備調整中ですので、ちょっと現段階でのお返事はできません。","id":"exchange-133"},{"speaker":"浅野委員","kind":"質問","question":"小学校８校、中学校２校、それぞれ活用されたと先ほども伺ったところです。それぞれの設備について期待していた効果というものが出すことができたのかどうかということについて伺います。","respondent":"渋谷指導課長、野呂瀬学務課長","answer":"すみません、大体各校２名ぐらいですと３０名前後が英語の教員というふうに推測できるところです。東京都も英語教育を重視していくということで… 小学校にアンケートをとったところ、指導課が２月に上げておりましたプロジェクターを毎週使用していると回答した教員は７２.８％。算数、理科、市民科等です。","id":"exchange-134"},{"speaker":"浅野委員","kind":"質問","question":"利用した教科はわかったのですけれども、プロジェクターはそこそこ使っていますが、タブレット端末はどうだったのでしょうか。それとあと、これは評価をされているかと思いますけれども、今後全校に展開をするという、このような計画はいかがか尋ねました。","respondent":"野呂瀬学務課長、渋谷指導課長","answer":"タブレット端末につきましても、アンケートとか実際の教員の話からも活用されているというふうに伺っているところです。それと今後の配置ですけれども、一応計画上は小規模支援ということで配備しましたので… なかなかちょっとまた研究をしなければいけないところがあろうと思います。しかしながら、固有教員については英語の資格等々を積極的に推進するように努めてまいりたいというふうに思っているところです。","id":"exchange-135"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回土地をいただいて整備を広げるということですが、当時そういう話だったと思うのですが、それが事実かどうかということを教えてください。これは結構厳しい要望かなと思いますけれども、地元の方の声をしっかりと受けとめてほしいと求めました。","respondent":"野呂瀬学務課長、品川庶務課長","answer":"学校保健のことですけれども、いわゆる金額が増えたというのは予定人数の増、それと検診、これは単価契約でやっていますので、その単価アップ等です。 当然、学校避難所ということになっていますので、そういう機能を付けるということは非常にいいことであると思います。ただ、学校の管理上どうかというところもありますので、その辺も学校といろいろ話し合って…","id":"exchange-136"},{"speaker":"浅野委員","kind":"質問・要望","question":"単価アップにしてはかなりのアップかなというふうに思うのですけれども、中身は本当にそれでいいのかというのを再度お伺いしたいと思います。要望です。","respondent":"野呂瀬学務課長","answer":"単価アップとあとは人数の増です。","id":"exchange-137"},{"speaker":"須藤委員","kind":"質問","question":"品川の教育で不易であると考えているものは、どういうことが不易であると、これが絶対必要だ、変えられないというものは何でしょうか。いろいろお話を伺っていると、そういう考え方についてはいかがでしょうか、説明を求めました。","respondent":"渋谷指導課長","answer":"子どもが何らかの思いを持って、きちっと目的を持って教育を受けるという意味合いにおいては、大変これは非常に重要なことだというふうに思います。やる気のある子…","id":"exchange-138"},{"speaker":"須藤委員","kind":"意見","question":"どうしても何かあっても人のせいにしたりとかというのが、そうではなくて、しっかり自覚を持って育っていくようにお願いしたいと思います。この目的はどういうことなのかということと、どういう方々がお集まりになって、説明を求めました。","respondent":"渋谷指導課長","answer":"場所については、午前中は品川区内全ての小中学校、小中一貫校を会場として授業公開と、各学校の取組みの発表を行っていただく予定です。全国の方たち、１,０００名の皆様を対象に広く品川区の取組みについて発表させていただきたいと、そのように考えているところです。","id":"exchange-139"},{"speaker":"須藤委員","kind":"質問","question":"多くの市区町村の首長が入っていらっしゃるのだけれども、この品川区教育フォーラムについては、そういう方々にご案内は出さないのかどうか。そういうものの関心があるかどうか、お聞きになって、いかがか尋ねました。","respondent":"渋谷指導課長","answer":"それから、教育再生首長会議については、濱野区長も参加しているですので、周知については、そういった方々にもぜひお願いをしたいと考えています。区長、ぜひご登壇いただいて、いろいろなお考え等についてはお願いをしたいなというふうに事務局としては考えているところです。","id":"exchange-140"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、さっき言った「向上向下の道」なんていうのも、英語にしようとしたってなかなか意味がついてこないと思う。ただ、それを子どもたちに教育していくことをよく承知しておいていただきたいと思うのですが、いかがか尋ねました。","respondent":"渋谷指導課長","answer":"武道も他地区ではやっておりませんが、小学校５年生から日本の武道をしっかり学ばせて、伝統文化を大切にする心を育んでおります。そういったものを大切にしながら、なおかつ国際社会でも活躍できる子どもたちをしっかり育ててまいりたいというふうに考えているところです。","id":"exchange-141"},{"speaker":"須藤委員","kind":"質問・要望","question":"このオリンピック・パラリンピック推進事業の中に入ってきてほしいと思っている。ですから、広くそういう事業が世間で営まれてきているのですから、そのあたりも説明を求めました。","respondent":"村尾学校支援担当課長","answer":"体力向上につきましても、まさに質の高い授業を進めて、結果的に子どもたちの体力部分を含めていこうと考えています。民間またはＮＰＯとの地域の人材も活用しながら、より一層この体力向上に向けて大きく動き出したいと考えているところです。","id":"exchange-142"},{"speaker":"須藤委員","kind":"質問","question":"最後に、３５９ページの家庭教育力向上支援とありますけれども、これはどんなことをなさるのか。それから学校でというのでいくのだと思うのだけれども、このあたりはどういうふうな支援をしていくのか説明を求めました。","respondent":"品川庶務課長","answer":"チェックシートは、大体２０から３０項目ぐらいの問いを出しております。基本的には親御さんに、こちらから何か言うのではなく、そういうチェックシートを見て気づいていただくと、そういうような趣旨でつくっております。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"小学６年生、本人の学力を本人や保護者に対して、「あなたはこのぐらいの位置にあるよ」ということをきちんと報告しているのでしょうか。保護者に対してもそうですが、どのような方法で報告したのか説明を求めました。","respondent":"渋谷指導課長","answer":"いわゆる相対的な評価、順位を出したりだとか、そういう形での情報提供はないということです。子どもたち、また保護者の方は情報を知ることができる、そういうような内容です。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"やはり、そういうことをきちんと義務教育の間に教えてあげるのが教育委員会の仕事ではないのですか。それを教えて、納得すればいいのですか、そうではないか尋ねました。","respondent":"渋谷指導課長","answer":"進路選択を進めてきたということで、不登校の子どもだったり、そういう反省のもとに現在の進路指導というものが行われています。不登校の子ども、退学するような子ども、子どもたちに絶望感を与えるような結果になってしまうのではないでしょうか。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"でも、なぜ教育委員会の皆さんは、いや、そこまでやる必要はない、私たちはそんなことはしませんよと言い切れるのですか。どうですか、もし自分の子どもがそうだとしたら、同じことを思われますか。","respondent":"渋谷指導課長","answer":"予測不可能な時代において、課題があったときにどのように解決するのか、それをつくり出していく２１世紀型の学力というものが今問われている。そういう意味において、単純に順位だけとか、成績だけで進路選択を図っていくというふうな考え方については…","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"これはさっき生きる力、社会で働き生き抜いていく力もありますけれども、もともとは勉強するため、学問を学ぶためにできたのではないのですか。実際、実社会はどうなのだということを真剣に考えてほしいのですね。","respondent":"渋谷指導課長","answer":"一つの問題集を解いて、偏差値７０をとって、それでよしとするのは学校ではありません。そういったものをしっかり身につけさせることが必要だと考えています。","id":"exchange-147"},{"speaker":"南委員","kind":"質問","question":"３６１ページの御殿山小学校西側敷地図書館建設工事設計費、２,５００万円計上されていますが、この問題について質問します。スケジュールを説明を求めました。","respondent":"中元品川図書館長","answer":"西側敷地につきましては、現在調整中ですので、まだ最終的なスケジュールにつきましては確定していないと認識しております。","id":"exchange-148"},{"speaker":"南委員","kind":"質問・要望","question":"その辺をちょっと確認したいと考えています。そして、この大崎図書館が現在実施している住民へのサービスというのは、どのような内容なのか、それについて伺いたいと思います。","respondent":"中元品川図書館長","answer":"よろず相談、ものづくり・経営支援課のほうで再度検討しまして、一旦大崎ビジネス支援図書館の事業としては終了するという方向で話を詰めてきました。そちらの産業交流支援施設の近くに、そちらのほうに大崎図書館が移転するほうが…","id":"exchange-149"},{"speaker":"南委員","kind":"質問・要望","question":"児童図書は５番目ということで、利用度の高い図書館ではないかというふうに私は思っているのですけれども、その点についての認識を伺います。時期的にちょっと教えていただきたいですけれども、そこでは一般的な図書館のサービスが行えるのかどうか、そこについて伺いたいと思います。","respondent":"中元品川図書館長","answer":"既に区議会の請願の審査の際のお答えでもしておりますけれども、大崎駅西口の駅前に取り次ぎサービスと図書の閲覧コーナーの設置を検討しています。現在予算要求の準備を進めている芳水小学校の改築計画の中で、大崎図書館の取り次ぎサービスなどの設置を検討していくです。","id":"exchange-150"},{"speaker":"南委員","kind":"意見","question":"そこの二つの取り次ぎサービス、閲覧もできるというふうになるのですけれども、そこでは今、大崎図書館が行っている一般サービス、それができるのかどうかということのお答えがなかったので、簡潔にお願いしますとの意見を述べました。","respondent":"中元品川図書館長","answer":"図書館の指定管理者のスタッフを配置することで検討していますので、当然レファレンスに関する部分とか、ある程度の書棚を置くスペースも確保できるということで検討しています。","id":"exchange-151"},{"speaker":"南委員","kind":"質問","question":"そして、大崎図書館利用者に対して移転計画があることを知らせているのでしょうか。そして移転計画を知らせないまま進めていくつもりなのかどうか、その辺について伺います。","respondent":"中元品川図書館長","answer":"遜色なく行えるかというところでは、大崎駅西口はある一定程度、現在の予定ですと１５０m2の場所をお貸しいただけると伺っておりますので。広報等で、区議会だより等でも明らかになっているところですので、区民の方はご存じかと思います。","id":"exchange-152"},{"speaker":"南委員","kind":"質問","question":"館内では掲示して知らせているということですか、ちょっとその辺。こういうことであるべきだというふうに思うので、本当にきちんとしたことで知らせることがまず最低限の区の責任だというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-153"},{"speaker":"いながわ委員","kind":"質問","question":"平成２２年ということで、品川区はこれまでこのガイドブックのチェックリストというのですかね、その項目で何かアクションを起こしたのかどうなのか。先ほど６７か所ですか、見つかったというのですが、今まではそこまで深くは調べていなかったということなのかどうなのかというのを説明を求めました。","respondent":"品川庶務課長","answer":"今年度、八潮でその工事は完了する予定です。こういったことが起こりまして、今回平成２７年度の非構造部材というものを改めて予算要求していると、こういう流れです。","id":"exchange-154"},{"speaker":"いながわ委員","kind":"質問・要望","question":"この６７か所というのは、詳しく教えていただきたいのですが、あと非構造部材というのはいろいろなものがあると思います。電気とか、そういうものは全て終わっているという判断でいいのか、それもこれからやるのかどうなのか説明を求めました。","respondent":"品川庶務課長","answer":"あると思うのですけれども、こういった部分も落下の可能性もありますので、そういうものも対象となっています。それから、学校の家具類ですね、家具類に関しましては、家具転倒防止ということで、今年度の予算の中で全て行っていくような形で進めております。","id":"exchange-155"},{"speaker":"いながわ委員","kind":"質問・要望","question":"もう一度確認なのですが、小中学校においてのそういった非構造部材も含めて全てが完了するということでよろしいかどうか、最終確認をさせてください。入札ですから、そういうのをしっかりやってほしいと求めましたが、それを１点説明を求めました。","respondent":"品川庶務課長","answer":"ちょっと朝の説明で、私の説明不足だったかもしれませんが、そういうもろもろを含めて１０月以降に行う工事もあります。そういったスケジュール感をいろいろ各学校とも調整しながら、１年間かけて非構造部材の耐震化を行っていく予定です。","id":"exchange-156"},{"speaker":"いながわ委員","kind":"質問","question":"通学路の防犯カメラなのですが、もう時間があれなので簡単に聞きます。設置台数としてまずお伺いしたいということと、でもこれを足しても３０校で、その辺を説明を求めました。","respondent":"品川庶務課長","answer":"来年度は１４校今度設置を行っていく予定です。平成２８年度以降、残った学校については設置をしていくと、このような考えでおります。","id":"exchange-157"},{"speaker":"たけうち委員","kind":"質問","question":"３５１ページのいじめ防止対策費、それから３７３ページの幼稚園運営費に関連してお伺いします。先ほど品川区ではそうならないようにするというふうに答弁で伺ったのですけれども、具体的にはどのように対応していくのか説明を求めました。","respondent":"村尾学校支援担当課長","answer":"二つ目には、その要請がなくても、定期訪問という考え方で各中学校を定期的に回っております。教育委員会の中で情報を共有し、よりよい適切な支援等を進めている、そういう状況です。","id":"exchange-158"},{"speaker":"たけうち委員","kind":"意見","question":"スクールソーシャルワーカーということについての役割が学校現場にちゃんと伝わっていなかったのではないかという指摘もあるそうです。そういったことが品川区的にはどうなのかということと、その辺も含めて、もう一回どのような対応をしていくのかお知らせくださいとの意見を述べました。","respondent":"村尾学校支援担当課長","answer":"１点目、また生活指導主任会等でも先生方にまさに組織で対応することの重要性については、これまでも伝えているところです。それからスクールカウンセラー、そして警察ＯＢ等専門職が入って、さまざまな課題に対応できるように努めているところです。","id":"exchange-159"},{"speaker":"たけうち委員","kind":"確認","question":"今学校で通学安全確認業務委託ということで、そういった方たちとの連携というのですかね、この通学安全確認の方たちというのは。今日はいつも仲間でいるのに何かずっとこのところ１人だなとか、そういう各機関との連携はどのように図られているのかお知らせください。","respondent":"村尾学校支援担当課長","answer":"学校のほうで対応し、間接的にはなりますけれども、つながっているというふうに考えております。児童・生徒の問題行動とか、その学校からの情報をとりながらスクールソーシャルワーカーの取組みがなされるのではないかというふうに考えております。","id":"exchange-160"},{"speaker":"たけうち委員","kind":"質問・要望","question":"やはり子どもたちの発達とかいろいろな面で大事な部分なので、その辺は粘り強く丁寧に対応してほしいと求めました。品川区として子どもを所管する部署として、今日は幼稚園の部分で結構なのですが、どのようにこれについて取り組んでいくのか説明を求めました。","respondent":"竹田保育課長","answer":"今までも近隣の方に極力ご迷惑をかけないような形で数々工夫してまいりました。子どもは社会の宝とも言われておりますので、ぜひ地域の方にもご理解いただくように粘り強くお声かけをさせていただきたいと考えています。","id":"exchange-161"},{"speaker":"たけうち委員","kind":"意見","question":"そういう角度ではなくて、いわゆる品川区として条例改正をするかどうかということを所管としてどういうふうに担当部署とやりとりするのかということですとの意見を述べました。","respondent":"竹田保育課長、三ツ橋環境課長","answer":"今時点では所管としては考えておりません。 環境確保条例上の一部を改正するということになりますので、粛々と区としても……。〔時間切れにより答弁なし〕","id":"exchange-162"},{"speaker":"伊藤委員","kind":"確認","question":"それから３４９ページ、それから３４７ページ、区固有教員に関連して質問します。それからその後の対応、所在確認はされておりますでしょうか、確認をお願いいたします。","respondent":"野呂瀬学務課長","answer":"今品川区は、居所不明の子どもはおりません。","id":"exchange-163"},{"speaker":"伊藤委員","kind":"確認","question":"その確認がとれれば、ここではいいです。なので、よくモデル町会や自治会をつくって展開していくと思うのだけれども、そういうふうに仕切り直すべきだと思うのですが、いかがか尋ねました。","respondent":"品川庶務課長","answer":"子ども地域活動支援についてですが、現在も地域活動課と連携した形で進めている状況です。話を聞きますと、現在のところ、モデル地区というような形で出さなくてもいいのではないかというような考えでおります。","id":"exchange-164"},{"speaker":"伊藤委員","kind":"質問","question":"そういう現実がある中で、それをどう具体的に展開していくかということについては、もっともっといろいろな知恵が必要だなと思うのですよ。ですから、この事業の目的は達成されないのではないかなという思いを強くしたので、改めて答弁をお願いいたします。","respondent":"品川庶務課長","answer":"午前中も答弁したのですが、大体２０町会ぐらいに教育委員会としても出向きまして、このスタンプカードの事業の説明を行っております。本年度も続けまして、各町会からいろいろな意見を聞きまして、事業のほうはいろいろなところで見直していきたいと、そのように考えております。","id":"exchange-165"},{"speaker":"伊藤委員","kind":"質問","question":"先日私宛てにメールがありまして、匿名で具体的な学校名は記載されていなかったのですけれども、３年数か月前に区立学校内で教師から体罰を受けたと。だから、体罰根絶宣言をしている品川区教育委員会としては、こういうことに対しての再発防止策をどうお考えでしょうか、説明を求めました。","respondent":"渋谷指導課長","answer":"具体的な研修プログラムを学校に東京都から示された資料をもとにお示しして、夏休み前と秋に２回しっかり研修というような形で行っております。体罰については、強い決意を持って今後もしっかりと取り組んでまいりたいと思っているところです。","id":"exchange-166"},{"speaker":"伊藤委員","kind":"質問","question":"要はこういうメールが来たということは、教育委員会にはもっと頑張ってほしいと思うし、この保護者の方はそういうことを経験なさったのかもしれない。だけれども、今お話があったような具体的な指導をさらに拡大していくべき必要があると思うのですが、もう一言答弁をお願いします。","respondent":"渋谷指導課長","answer":"教師だけでなく、子どもたちも、保護者の皆様にもしっかりと声を上げていただけるように働きかけているところです。体罰がなくなるように、これでいいということはないと考えていますので、繰り返し繰り返し粘り強くしっかりと指導してまいりたいと考えています。","id":"exchange-167"},{"speaker":"伊藤委員","kind":"質問","question":"去年の１１月にオークランドに国際平和友好でお伺いしました。つまり何を言いたいかといいますと、品川区の区固有教員に対して、こういう機会を設定すべきではないか尋ねました。","respondent":"渋谷指導課長","answer":"大きな留学とまではいかないですけれども、そういった国際的な視野を広げる第一歩にしていただけるというふうなことも考えているところです。魅力ある品川区の固有教員ということでアピールできるような仕組みを考えてまいりたいと思っているところです。","id":"exchange-168"},{"speaker":"伊藤委員","kind":"質問","question":"だから、よく国際理解教育とか、それから世界に羽ばたく人材をつくっていくとおっしゃっているわけではないですか。そういうふうなことをしてあげるなり、そういう温かい配慮をすべきであると思うのですが、いかがか尋ねました。","respondent":"渋谷指導課長","answer":"指導的な役割を果たしていく固有教員がそういった国際的な視野を身につけるということも一つ大事だというふうに思っているところです。ただ、１年だとかということになると、そういった研修のあり方については今後前向きに研究させていただきたいというふうに思っているところで…","id":"exchange-169"},{"speaker":"伊藤委員","kind":"提案","question":"今日で款別の審査は最後ですから、委員会でいろいろ出された意見や提案、平成２８年度の予算に反映していただきますようお願いします。終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-170"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/592877?Template=document&Id=1030#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":125464,"voices":392}},{"id":"h27-20150317-3","meetingId":"h27-c-budget","date":"2015年3月17日","dateIso":"2015-03-17","committee":"予算特別委員会","time":"午前１０時００分～午後 ４時５２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を112件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その生徒は３学期になってからも一度も中学校に通っていなかったという状況で、結果として痛ましい結果になってしまいました。区としての調査、また現況、このような点につきましてご回答ほしいと求めました。","respondent":"田村教育次長","answer":"平成２３年度が１６３名、平成２４年度が１６０名、平成２５年度が１６３名という不登校の把握をしております。あるいは学力的に若干、特に不登校というだけの対応ではなく、いじめも含めた全体をＨＥＡＲＴＳ（ハーツ・心）で対応しているというのが現況です。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それからもう一点、別の質問になります。これも、学校での指導体制、それと同時に教育委員会からの指導体制についてお聞きいたします。","respondent":"田村教育次長","answer":"大きな括りで３つの項目が、東京都の文書と同時に、品川区に対応できる文書を各学校に周知して徹底を図ったです。今の現況については、そういうふうな対応を各学校あるいは教育委員会でしています。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"自民党から強く要望しておりました品川区災害対策基本条例が昨年４月に施行されました。４年前の東日本大震災の教訓を踏まえ、防災対策として、今までの取組み状況と成果についてお答えをお願いいたします。","respondent":"松代防災まちづくり事業部長","answer":"避難所機能の強化、民間事業者との協力協定拡充などを実施しまして、区の防災体制整備だけでなく地域の防災力の向上にも努めてきています。自主的な防災訓練の実施や応急対応訓練の実施といった取組みが活発になったなど、成果が出たと考えているところです。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"確認","question":"当日の状況の確認しかできない状況だったのですが、その中で、区民の意識というのは確かに上がってきているというのは感じております。２７年度における重点事業については何であるのか、またどのように進めていくのか、この点についてもお答えをお願いしたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"平成２７年度の防災対策の重点事業ですが、避難所機能の強化や津波・浸水等への対策にも引き続き取り組んでまいります。進め方としましては、災害に強いまちづくりと、品川区の防災力のさらなる向上を目指して全力で取り組んでまいります。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"意見","question":"既に実施している６地区においての、支援の内容と成果についてお答えをお願いしたいと思います。それだけ力を注いでいく中で、今後の折衝の方向性という点についてもお答えをお願いしたいと思いますとの意見を述べました。","respondent":"藤田都市環境事業部長","answer":"地元の説明会や該当者宅への各戸訪問、これまで専門家派遣が５０件程度、建物解体・除却については１００件程度の実績を成果としたところです。新たに住宅支援あるいは不燃化コンシェルジュ、未接道宅地の解消等を行うなどを進めまして、さらに力を注いでまいりたいと考えていま…","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今後、そのことを考えますと、各地域でもこの訓練の必要性もあるのではないかと考えますがいかがでしょうか。この辺も考えますと、帰宅困難者や滞留者対策について、これからどうやっていくのか、改めてお聞きしたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"平成２５年度に目黒駅周辺帰宅困難者対策協議会を設立しまして、目黒区と連携して、具体的な対策の協議や訓練を実施したところです。現在、大井町駅についても、同様の協議会の設立準備を進めておりまして、本年４月以降に設立総会を予定しています。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この建物につきましては、今までも出ておりますが、固定資産税の問題があるのではないかという話も伺っております。空き家に対しての６分の１の減免もなくなっていく方向性にあるときに、その点につきましてもお答えをお願いしたいと思います。","respondent":"藤田都市環境事業部長","answer":"これまで平成２４年１１月にＪＲと区のほうで、開発構想に向けた検討会を設置し、検討を進めているところです。事業を進める上で、これらも含めて引き続き協働で検討を行い、にぎわいあるまちづくりを進めていきたいと考えています。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺も十分、一般の区民の方に不便にならないように、また事故の起きないような体制もとってほしいと求めました。私も今聞いた中でどういうふうに考えるべきかというのもあったのですが、検討状況、その点をもう一回お答えをほしいと求めました。","respondent":"藤田都市環境事業部長","answer":"ゾーニング等の中でも、まちのにぎわいを引き込めるような要素をしっかりとその開発の中に取り込んでいきたいということが、まず一つあります。どのような形で整備を進めるのがいいのかしっかりと協議し、にぎわい、活気のあるまちづくりを進めたいと考えています。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ、にぎわいのあるまちづくりに努めていただきたいということを要望しておきます。都市公園法の解除についての課題と、区としてこの解除に対する考え方について説明を求めました。","respondent":"松代防災まちづくり事業部長","answer":"さらには利用可能な適地があるかなど、不確定な要素があることから、調査を進める必要があると考えております。国や他自治体の状況などについてさらなる情報収集を行いまして、活用できる制度は積極的に取り入れていきたいと考えておるところです。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もう結構、老朽化しておりますが、建替えの際には現状の建物が建たないのではないかということをお聞きしたことがあります。そういう建物というのはほかにも見受けられるような気がするのですが、何カ所ぐらいあるのか、その辺を教えてほしいと求めました。","respondent":"松代防災まちづくり事業部長","answer":"この都営住宅は昭和４５年に建築されまして、昭和４８年にその敷地の一部を都から移管を受けまして、区が公園として整備したものです。このほか、このような課題を抱える同様の形態の住宅につきましては２カ所ほどあります。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"公園の指定を外せばもとのとおり建てられるのかどうか、その辺が私もちょっとわからないのですが、その辺はどう考えたらいいのでしょうか。現在住んでいる方もまた住めるし、さらに区のほうの施設が一緒に入れば展開も図れると思うのですが、その辺はいかがか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"現行の法令の中では、公園敷地内に住宅を組み込んで建替えを行うということは非常に困難な状況だと認識しております。しかしながら、都の施設に当たっても区の施設に当たっても、このまま老朽したままでということではいかないと認識しております。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"新しい政策的にも、品川区にとってメリットのある政策を展開していってほしいと求めましたので、ぜひよろしくお願いしたいと思います。改めて、今回の改正の趣旨と、また大きな改正点についてお答えをお願いしたいと思います。","respondent":"榎本健康福祉事業部長","answer":"それから３つ目としては、低所得者の保険料の軽減を拡充するということで、今まで以上に軽減を図っていくと。それから４つ目が、一定所得のある利用者については自己負担を２割へ引き上げるということで、このような改正点です。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その中で、最初に地域支援事業、新しい総合事業について確認させてほしいと求めました。この方々に対するサービスについて変更が生じてくるのか尋ねました。","respondent":"榎本健康福祉事業部長","answer":"ただ、平成２７年４月から品川区は実施していきますけれども、サービスを継続利用できることを基本としてサービスを組み立てております。安定的にまず継続するということが第１点目で、そういうものも含めて、平成２７年度についても継続していろいろと検討していくという形です。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"介護予防に関して、特別養護老人ホームなどの利用というのは考えていかれないのかどうか、そこら辺もお考えをお聞きしたいと思います。こういう総合事業に対しても協力できないのかとか、そこら辺について区としてのお考えをお聞きしたいと思います。","respondent":"榎本健康福祉事業部長","answer":"１点目の要支援者への説明ですけれども、やはり総合事業に当たって、介護サービスを提供する事業所に対してまず説明会を行っております。要支援者に対しましては、地域のケアマネジャーから要支援者に対して丁寧に説明できるように、予防マネジメント研修会を実施しております。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"要介護度１・２の方もそうですし、要支援の方がこれから先、進んだときどうなるのということも、時々我々もお聞きします。区の中でどのように進めているのか、またこれからどう展開を図っていくのか、その点につきましてお聞きしたいと思います。","respondent":"榎本健康福祉事業部長","answer":"最近ですけれども、品川区医師会のほうで、在宅医療を主軸とする医療系事業所連携システムの構築の検討を開始しています。介護のほうで、地域包括支援センターシステムを持っておりますので、さらなる検討を進めてまいりたいと考えています。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"在宅医療ということでも、これからも大変な問題が出てくると思いますので、その辺につきましてもいろんな面でご手配をお願いしたいと思います。この辺も考えまして、厚生委員会を担当していただいております山田副区長から一言お答えをほしいと求めましたが、。","respondent":"山田副区長","answer":"障害者の施設であるとか、特別養護老人ホームも平成２８年・平成２９年と２カ所、そして平成３０年には老人保健施設を建設してまいります。やはり地域の中で温かい目・温かい手があって在宅サービスが充実されていくのだろうと考えています。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、２点、防災と介護についてお聞きしました。もちろん検討会をやっていることは承知しておりますが、改めて区としての考え方をお聞きしたいと思うのですが、。","respondent":"中川原地域振興事業部長","answer":"委員お尋ねの防災・介護など、区と町会・自治会との協働で、安心・安全のまちづくりを進めていくことがさらに大事になってくると考えております。町会・自治会の現状、これまで区がさまざま展開してまいりました加入促進をはじめとする支援が…","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後にもう一点、お聞きさせてほしいと求めました。その中で、今後の品川区の施策の展開、品川区の将来像につきまして、改めて濱野区長のお考えをお聞きしたいと思います。","respondent":"濱野区長","answer":"こうしたことについても対応していかなければならないということで、課題は山積していると考えています。平成２７年度はそれのスタートの年だと思っておりまして、今後もさまざまな分野でチャレンジしていきたいと思っているところです。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"意見","question":"法人住民税２３億円のマイナス、大きな金額も出てくるというお話もありました。行政部局、議会も一緒になって頑張っていきたいと思いますので、どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"本多委員","kind":"質問","question":"初めに代替地の考え方について伺います。この４例について、暫定的とはいえ代替地として機能したのか、それぞれについて説明を求めました。","respondent":"榎本健康福祉事業部長、中川原地域振興事業部長","answer":"３キロ弱ぐらいの移転の距離だったのですけれども、地域でのふれあい祭り等を２回実施しまして、ある程度効果はありました。その部分は機能として説明を十分、丁寧にしたところではありますけれども… 月平均の利用者数は、伊藤学園温水プールを開設していた６年間の月平均利用者数を大きく上回っております。現在に至るまで、伊藤学園温水プールを終了したことによる苦情は１件もなく、快適であるという声が区に届けられているところで…","id":"exchange-020"},{"speaker":"本多委員","kind":"質問","question":"東大井の１丁目から６丁目で銭湯がなくなったというようなケースは、やはり地域では、「近所でそういう施設が欲しい」というような意見があります。ただ、ある程度の物差しというものが必要なのではないかと思うのですが、その点についてはいかがでしょう。","respondent":"桑村副区長","answer":"サービスを低下させないようにしたいとは思ってありますが、いわゆる一律の基準はなかなか難しいというのが現在の状況だろうと思います。これまでの経験ですとか、それから利用者の状況等を考えて…","id":"exchange-021"},{"speaker":"本多委員","kind":"質問","question":"地域センター管内単位ですとか、ある程度そういった、望ましいというような部分について改めて答弁をお願いします。こんなところにこんな活用場所があるとか、そういった工夫ができるのではないかと思うのですが、その２点について説明を求めました。","respondent":"桑村副区長","answer":"例えば非常に小さい子が通っているような施設は、なかなか遠いところに代替施設を持っていくのは、これもまた難しいというのも事実だろうと思います。施設の有効活用という面で別途検討させていただいているのが今までの現状ですし…","id":"exchange-022"},{"speaker":"本多委員","kind":"質問・要望","question":"それと、次に関連して質問していくのですが、平成３０年に竣工予定の芳水小学校内に、現行の大崎図書館の機能を整備できないか、伺います。西口につきましては、１カ所で充実してほしいと求めましたが、いかがか尋ねました。","respondent":"田村教育次長","answer":"請願第８号で、１つは大崎駅西口に大崎図書館の取り次ぎサービスと、図書の閲覧コーナーの設置を検討すると。大崎図書館の取り次ぎサービス的な設置も、今考えているのは、それも含めて検討している状況です。","id":"exchange-023"},{"speaker":"本多委員","kind":"質問","question":"まさにここに当てはまることだと思いますので、その点を改めて聞くのと、それと請願第８号が趣旨採択されました。主眼は、「機能を大崎駅西口」ということで、その区議会の意思をどう反映されるのか、その２点、もう一度お願いします。","respondent":"田村教育次長","answer":"芳水小学校は１４学級ということですが、平成３２年度に２０学級まで、就学人口が増える予定なのです。もちろん、増加についても引き続き、これから各論に入っていきますので、検討してまいりたいと考えております。","id":"exchange-024"},{"speaker":"本多委員","kind":"質問・要望","question":"特に海外との交流促進の点で、深夜・早朝便に対応したバスダイヤとターミナル設備を確保していただきたいと考えますが、いかがでしょうか。五反田と羽田空港とが海上交通でつながるよう、東京都との連携を図っていただきたいと考えますが、いかがか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"羽田空港は今後も国内外からの観光客等によりまして多くの利用があると見込まれております。平時は民間利用が中心となることから、平成２７年度より需要推計や民間ニーズを把握したルートの検討、施設規模等の調査を行う予定です。","id":"exchange-025"},{"speaker":"本多委員","kind":"質問・要望","question":"中期的・長期的に取り組んでいく内容ですが、平成２７年度もしっかり取り組んでいってほしいと求めました。現状をどう捉えているか説明を求めました。","respondent":"松代防災まちづくり事業部長、藤田都市環境事業部長","answer":"２０２０年の完成を目指して計画・調整を図り、工事を進めていきたいということで、今、考えてあります。今ご質問にもありました正式な名称についても、さまざまな角度から検討し… 一定の方向に向かうときには、そのバス会社が運行したほうが効率的にできるということもあって、現在ではそういう運行になっていると考えています。その中で、それぞれのバス事業者が効率よく運行できるのがまず第一だと考えていますの…","id":"exchange-026"},{"speaker":"本多委員","kind":"提案","question":"臨海部と大崎駅間の増発・増便を働きかけてはいかがでしょうか。りんかい線の大崎・大井町駅区間を限定で、ＪＲと同額の１６０円となるように提案してはいかがか尋ねました。","respondent":"藤田都市環境事業部長","answer":"それから大規模災害時の各駅への情報モニターを設置しようと考えているなど、サービスの向上の面でもさまざまな対策を今考えていると聞いてあります。そういう中で、現段階では料金についての見直しは難しいのかと考えています。","id":"exchange-027"},{"speaker":"本多委員","kind":"質問","question":"２０２０年東京オリンピック・パラリンピックを見据えると、宿泊施設の拡充は必要であり、海外からのビジネス客の宿泊は欠かせません。ゆうぽうとは閉館しますが、この点、宿泊機能について説明を求めました。","respondent":"藤田都市環境事業部長","answer":"スーパーマーケット等の商業施設の導入を図り、地区内のみならず周辺の方々にもご利用いただけるような店舗等をつくる予定となっています。生活する上での必要な用途、ホテル等も含めた用途といった視点から、事業者を的確に誘導していきたいと考えています。","id":"exchange-028"},{"speaker":"本多委員","kind":"質問・要望","question":"今から山を刈って木を育てて、樹齢３００年以上のものを４００年後に充てるのだという話を聞いたときに、私は本当に日本人でよかったと思いました。こういうことというのは日本人の感覚だと思いますが、品川区の将来へ向けたまちづくりについて、思いをお聞かせほしいと求めました。","respondent":"藤田都市環境事業部長","answer":"それが１００年後に、ストレートではありませんけれども、今そのことに対応しなければ１００年後にはつながらないということになりますので。区民の、「輝く笑顔」が１つのキーワードになると考えていますので…","id":"exchange-029"},{"speaker":"本多委員","kind":"意見","question":"例えば大崎駅南口自由通路にはウェルカムビジョンと称するテレビが設置されていますが、人が立ち止まって情報を得る姿は見ることがありません。品川駅東西自由通路の液晶ビジョンを参考に、まちの情報発信力を確保していく必要もあると思いますが、この点について説明を求めました。","respondent":"藤田都市環境事業部長","answer":"大崎駅西口の再開発に合わせまして、平成２０年に設置された施設でございまして、現在は大崎エリアマネジメントにより管理運営を行っている施設です。区としても、さらなるにぎわいづくりに向けまして…","id":"exchange-030"},{"speaker":"本多委員","kind":"質問・要望","question":"携帯電話の電話メーカー業界ですとか、国とかに、笛の機能を持たせた機器の開発を働きかけてみてはいかがでしょうか。それとあわせて、そういう笛が必要なときというのは、人を呼ぶということですから、初動体制などの心がけなどについて説明を求めました。","respondent":"松代防災まちづくり事業部長","answer":"今後も、災害時の正しい判断、行動についての知識などの啓発とあわせて、災害時に役立つ用品等について普及・啓発に取り組んでまいります。そういった中に、こちらからも問い合わせをしたり、いろいろと意見調整する機会がありましたらしていきたいと考えているところです。","id":"exchange-031"},{"speaker":"本多委員","kind":"質問","question":"次の質問に行きます。品川区の小中一貫のさらなる推進を期すという意味で、教育長のご決意を説明を求めました。","respondent":"中島教育長","answer":"プラン２１から始まる小中一貫教育に続く、全国に先駆けた教育改革を実施するに当たりましては、そして支援。来年の２月２０日に実施する予定の品川区教育フォーラムをもちまして区民の方に広く発信し、また全国にも発信してまいりたいと考えているところです。","id":"exchange-032"},{"speaker":"本多委員","kind":"質問・要望","question":"万事、説明や理屈が求められる時代だからこそ、無形文化財が一層重要になってきています。この点について説明を求めました。","respondent":"田村教育次長","answer":"そういうものについては、本当に教育目標でも定めているとおり、子どもたちも大人も含めて大変重要な内容だと教育委員会も認識しております。そういうのを考えますと、あるいは広く一般の文化だとか習慣の重要性というのは、教育委員会としても大変重要だと認識しています。","id":"exchange-033"},{"speaker":"本多委員","kind":"質問","question":"最後に、東京オリンピック・パラリンピックに向けまして、品川区内の小中学校の全校の特色を参画させる仕組みづくりを伺います。何かしらの形で今から準備して、全校が東京オリンピック・パラリンピックに参画できるよう、その仕組みづくりについてお聞きします。","respondent":"田村教育次長","answer":"委員ご指摘のとおり、各校、特色を出してさまざまな取組みを実施しております。そういう趣旨も踏まえて、今後、まだスタートを切っていませんけれど、これからそういう準備に入りたいと考えております。","id":"exchange-034"},{"speaker":"本多委員","kind":"意見","question":"何か、国の創生の話みたいに、みずから手を挙げるということで答弁をいただきました。ぜひそうなるように、受け皿をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"塚本委員","kind":"質問","question":"初めに、区の防災対策について伺います。災害に強いまちづくりのため、どのような施策を実施していくのか、区の方針を説明を求めました。","respondent":"松代防災まちづくり事業部長","answer":"平成２５・２６年度についても、木密地域不燃化１０年プロジェクト、地域の防災力の向上にも努めてまいりました。平成２７年度も重点施策と据えまして、木密地域不燃化１０年プロジェクトの推進、これまで進めてまいりました事業の継続的な進め方。","id":"exchange-036"},{"speaker":"塚本委員","kind":"提案","question":"これからも防災にしっかりと取り組んでいくのだというところが確認できたと思いますけれども、防災対策について幾多の政策を提案してまいりました。デジタルサイネージなど、新たな情報媒体も活用した施策を求めますが、いかがか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"今後は災害時情報の提供に協力する事業者の確保について検討を進めてまいります。最後に多言語の案内表示板の設置についてですが、東京オリンピック・パラリンピック開催に向けた来訪外国人への対応のための多言語対応は。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"目視による調査だけでなく、より詳細な調査を実施して、危険性を正確に把握すべきと思いますがいかがでしょうか。区の現行制度を利用するなどして、費用負担について支援することはできないか尋ねました。","respondent":"松代防災まちづくり事業部長、藤田都市環境事業部長","answer":"環状６号線沿いに建物のガラス面のところにデジタルサイネージを配置していただきまして、災害時にそこでの災害情報等の情報を発信していただく。今後とも、こういった例を踏まえまして、さまざまなところで民間の力をお借りする中で… そういったものも対象になると考えていますので、さまざまなご相談をいただく中で、可能な方法については対応していけるかと考えています。補強のための支援については、区内全域でやるといっても…","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"次に、燃えにくいまちづくりについて伺います。そのため、平米当たりの工事単価が、他の工事よりも高くなる傾向があるのではないか尋ねました。","respondent":"藤田都市環境事業部長","answer":"重機が中に入っていけないことには、重機を使った工事ができませんので、おのずと手で壊すような工事になってまいります。単価を５,０００円アップいたしまして２万６,０００円とすることで、特区の目的でもある燃えないまちづくりを進めたいと考えています。","id":"exchange-039"},{"speaker":"塚本委員","kind":"提案","question":"ここで質問ですけれども、区の空き家条例第１４条で言うところの有効活用を促進することになるとの理解でよいか、お伺いいたします。空き家の除却においても、不燃化特区以外の木造住宅密集地域でも密集の解消を進めてはいかがかと提案いたしますが、区のご所見をお伺いしますとの意見を述べました。","respondent":"藤田都市環境事業部長","answer":"空き家条例の第１４条で言う有効活用の前提が、一つはそういう見解になるかと考えています。木密地域の改善のための特別な支援策として不燃化特区のエリアの中で行われているものですので、ほかの地域でも展開することは困難かと考えています。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"有識者検討会がまとめた報告書の内容とはどのようなものであり、今後、品川区に及ぼす影響について伺いたいと思います。検討会座長の関澤愛東京理科大学大学院教授は、感震ブレーカーの機能と火災防止の効力をどのように評価するか説明を求めました。","respondent":"松代防災まちづくり事業部長","answer":"しかしながら、本検討会の報告書については、密集市街地における重点的な普及促進や普及方策を検討するためのモデル調査の実施など。今後、本報告書の通知や公表等によりまして内容を確認し対応を検討する予定です。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"最も大きな被害が想定される東京湾北部地震による火災の死者数が５２０人ですので、この比率でいきますと、２９３人まで減るということになります。区は、購入あっ旋や取り付け工事助成なども検討の余地があるのではないかと思いますが、ご所見をお伺いします。","respondent":"松代防災まちづくり事業部長","answer":"検討会の報告書の詳細をはじめ、報告書を踏まえた国や東京都の感震ブレーカー等の普及促進の方針は、これから示されるものと思われます。こうした状況を把握した上で、感震ブレーカー等の普及における対応を検討していくことが必要であります。","id":"exchange-042"},{"speaker":"塚本委員","kind":"質問・要望","question":"次に、子育て支援のさらなる充実を求めて質問いたします。（仮称）しながわネウボラネットワーク検討を始めるに至った背景と、品川区の子育て支援のどのような課題を検討するのか説明を求めました。","respondent":"金子子ども未来事業部長","answer":"これから区で検討してまいります（仮称）しながわネウボラネットワークは、妊娠から出産、子育てまでの切れ目のない支援を行おうとするものです。現状のさまざまな事業を土台としまして…","id":"exchange-043"},{"speaker":"塚本委員","kind":"意見","question":"病後児保育は、感染症の子どもが１人いると他の子どもは預かれないなど、単に定員枠を増やすことで解決しない課題もあります。その上で、他自治体や民間事業者が実施している訪問型の病児・病後児保育をどのように評価するかも説明を求めました。","respondent":"金子子ども未来事業部長","answer":"先ほどと同じように、子どもの体調急変時に緊急の対応を必要とされていること。さらに家庭で子どもと１対１の対応となることから、労務管理の問題などがあります。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問・要望","question":"次に、核家族化が進む現代にあっての在宅での子育てということでお伺いいたしますが。そして、利用実績が上がらない理由について区の見解を伺います。","respondent":"金子子ども未来事業部長","answer":"支援の中身は、一般に産前は出産予定日より１カ月前から５日を限度、産後は退院した翌日から１年以内で１０日を限度としております。この２点が挙げられるかと考えています。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問・要望","question":"今、在宅子育ての日常生活において求められている支援とは何であるのかということをきめ細かく捉えていくべきではないかと考えています。その上で、現在の支援では足らざるところを適切に支援する体制を整備すべきと思いますが、区のご所見をお伺いします。","respondent":"金子子ども未来事業部長","answer":"現状でも子育て支援課あるいは保健センターと、さまざまな機関で実施しております子育て相談や育児支援の中で把握して。（仮称）しながわネウボラネットワークの検討の中でニーズをきめ細かく把握しまして、支援策について検討してまいりたいと思っています。","id":"exchange-046"},{"speaker":"こんの委員","kind":"質問・要望","question":"平成２７年度より子ども・子育て支援新制度が本格実施となり、今後、品川区における待機児童対策をどのようにお考えになっていくのでしょうか。残念ながら１次、２次とも不承諾となってしまった方々への支援策が求められますが、お考えを説明を求めました。","respondent":"金子子ども未来事業部長","answer":"加えて平成２２年度からは入園申込者の急増に対応しまして、あるいは児童センター、小学校を活用した受け入れ枠の拡大を図ってまいりました。２７年度につきましては、４月開設を予定しておりました保育園が工事で遅れたことも一因であると考えています。","id":"exchange-047"},{"speaker":"こんの委員","kind":"質問・要望","question":"今後の保育施設整備は、公有地活用など、どのように実行されようとお考えでしょうか。先ほどのご答弁でもありました、こうした国の動きを注視しながら、品川区としても総合的な保育施設のいわゆる福祉施設の整備も要望したいと思います。","respondent":"金子子ども未来事業部長","answer":"先ほどもお答えしましたとおり、劇団四季の隣に開設予定をするというような、幅広くさまざまな可能性を探ってまいりたいと考えています。さらに具体的な適地の検討など課題が多いところでありますけれども、国や都、活用できる制度は積極的に活用していく考えです。","id":"exchange-048"},{"speaker":"こんの委員","kind":"質問・要望","question":"子ども・子育て支援新制度に基づく保育の必要性の区分認定など、今後の短時間就労対応型保育事業はどのように展開されようとお考えでしょうか。短時間就労を希望する子育て家庭を支援するための短時間就労対応型保育事業の拡充を要望します。","respondent":"金子子ども未来事業部長","answer":"これまで多様な就労形態に対応して支援してまいりましたけれども、短時間でも保育を必要とする世帯を継続的に支援していきたいと考えています。今後のニーズというのは変化が予測されますので、このニーズの動向を見て…","id":"exchange-049"},{"speaker":"こんの委員","kind":"意見","question":"１年間の育児休業後、育児休業延長を勧められるなど、あまり実用されていない現状が見受けられます。今後ますます女性の活躍が期待される中で、育児休業をしっかり取得できるよう後押しをすることが必要と考えますが、ご見解を説明を求めました。","respondent":"金子子ども未来事業部長","answer":"この制度は平成２０年６月から開始した制度でありまして、その間、受け入れ枠を拡大してまいりました。倍率が高いことと、さらに１年後の職場復帰の際には１割の方が辞退するなど、現状では課題のあることも認識しております。","id":"exchange-050"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ、さまざまなニーズを捉えての保育施策、そして品川区の待機児童対策を求めてこの質問を終わります。今後の見通しとして、介護も含めニーズが多様化する中、地域包括ケアシステムの構築に向けた高齢者の住まいについてはどのようにお考えか尋ねました。","respondent":"榎本健康福祉事業部長","answer":"将来的に維持管理の方法、いろいろ課題はありますけれども、継続していきたいと考えています。なかなか生活支援サービス、最初のうちは自立していますので生活支援サービスで大丈夫なのですけれども、要介護状態になったときに。","id":"exchange-051"},{"speaker":"こんの委員","kind":"質問","question":"こうした相談窓口の開設により、今後、高齢者の生活実態や困窮度合いなど、どのように把握され対応されようとお考えでしょうか。民間賃貸住宅など、高齢者の住まいへの支援についても説明を求めました。","respondent":"榎本健康福祉事業部長","answer":"第２庁舎の３階のところに相談窓口を新たに設置しまして、生活に困窮されている方々の自立支援相談等、支援の実施をしてまいります。高齢者いきがい課または都市計画課住宅担当等の窓口等ともご案内はしまして、今後とも関係部署と連携して、相談・支援を実施してまいる考えです。","id":"exchange-052"},{"speaker":"こんの委員","kind":"提案","question":"課題解決の具体策としては、これまで区議会公明党より、居住支援協議会の設置を提案してきました。住宅担当とも連携を図りながら、生活に困窮している高齢者の居住安定確保のための居住支援協議会の設置を再度提案しますとの意見を述べました。","respondent":"榎本健康福祉事業部長","answer":"高齢者住宅が総計で２２３戸、高齢者向け優良賃貸住宅家賃助成で５７戸、さまざまな支援を行っているところです。居住支援協議会の設置というお尋ねですけれども、効果的な課題解決に結びついているかなど、そういうことを研究していきたいと考えています。","id":"exchange-053"},{"speaker":"こんの委員","kind":"質問・要望","question":"１６日に、各自治体に設置を求める、こうした呼びかけを決めたという情報があります。活用可能なその空き家を活用するという考え方を品川区にも持っていただきたい、このように求めますが、いかがか尋ねました。","respondent":"榎本健康福祉事業部長","answer":"都市部における今後の人口の動向、それから年代・年齢構成などを考えますと、今後の重要な課題であると認識しております。さまざまな想定がされてまいりますので、空き家活用のモデルケースなどを検討しつつ、継続的に調査・研究をしていきたいと考えています。","id":"exchange-054"},{"speaker":"こんの委員","kind":"意見","question":"ぜひ、調査・研究をしていただきながら、実態調査後、ぜひ品川区でもそのような活用をお願いしたいと思います。以上をもちまして、区議会公明党の総括質疑を終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"大倉委員","kind":"質問・要望","question":"平成２７年度においても７００名余の受け入れ枠を増やしていくところだと伺っておりますが、今後も待機児童の増加が危惧されるところであります。待機児童対策について、品川区の現状について伺います。","respondent":"金子子ども未来事業部長","answer":"家庭的保育事業の開設支援など、平成２２年度から平成２６年度まで、５年間で２,９７９人の受け入れ枠の拡大を実施してまいりました。新規開設数の調整あるいは定員の弾力化や見直し等をさまざまな手法で検討してまいりたいと考えております。","id":"exchange-056"},{"speaker":"大倉委員","kind":"質問・要望","question":"メルマガ配信など、区から主体的に育児情報の発信を行うことは今後可能でしょうか。より多くの方に拡散力のあるＳＮＳの活用も、既存のホームページとあわせて検討してほしいと求めましたが、お考えを説明を求めました。","respondent":"金子子ども未来事業部長","answer":"区ではさまざまな所管で多くの子育て支援の事業や相談を実施しておりまして、これらの周知というのは非常に重要なことだと考えております。しかしながら、結果的に孤立してしまうことも危惧されますので…","id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"品川区として、一時保育の育児支援の制度について現在抱えている課題は何があるとお考えでしょうか。今後、それぞれの制度について拡充を図っていただきたいと考えておりますが、お考えを説明を求めました。","respondent":"金子子ども未来事業部長","answer":"区立の各園では最大２名枠を確保しているわけなのですけれども、なかなか受け入れ数、すぐに緊急に対応するというのが難しいところがあります。あるいは、急な保育需要についても何らかの工夫をして可能な限り柔軟に対応していく。","id":"exchange-058"},{"speaker":"大倉委員","kind":"質問・要望","question":"幅広い防災訓練への参加について伺います。あわせて防災訓練の参加数の現在の考え方について伺います。","respondent":"松代防災まちづくり事業部長","answer":"総合防災訓練の実施状況ですが、毎年、１３の地区防災協議会が主催し、９月から１１月に１２の会場で実施されております。訓練の目的である区民一人ひとりの自助、地域における共助の担い手の確保といった防災力の向上の観点から課題だと認識しています。","id":"exchange-059"},{"speaker":"大倉委員","kind":"質問","question":"そういった若い世代も取り込むために、現状とはまた違う活動が必要になるのではないでしょうか。区としては、どういった点に若い世代を取り込むための課題があるとお考えでしょうか、説明を求めました。","respondent":"松代防災まちづくり事業部長","answer":"総合防災訓練以外の訓練への参加や、避難行動要援護者への支援体制づくりなど、発災時の地域における共助の基礎の強化が期待できる。波及効果も大きいと考えておるところです。","id":"exchange-060"},{"speaker":"大倉委員","kind":"質問・要望","question":"そこにちょっとかかわってきますが、次に子どもの防災訓練への参加について伺います。子どもの参加状況は、先ほど数字が多少出ていましたが、参加状況とあわせて、区の対応についてもお伺いいたします。","respondent":"松代防災まちづくり事業部長","answer":"区としても対応が必要だと認識しており、学年単位や学校単位での訓練に参加するなど、子どもの訓練参加促進に取り組んでおります。これまで災害時の正しい行動や考え方を身につけることを目的に訓練を組み立てており、検討できればというようなことも考えているところです。","id":"exchange-061"},{"speaker":"大倉委員","kind":"質問","question":"そうした、子どもが防災訓練に参加しやすいようなプログラムを考えていく必要があると考えますが、区のお考えをお伺いします。ＮＰＯ団体などと協力して、子どもに向けた防災訓練を行っていくような試みは可能か尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"防災訓練を実施するご提案ですが、地域における訓練の支援につきましては、さまざまな支援を行っております。必要な協力・連携の仕組みなど、地域ごとの状況により異なるため、各地区の防災協議会ともご相談しながら検討する必要があると考えているところです。","id":"exchange-062"},{"speaker":"大倉委員","kind":"確認","question":"それと同じ事態に陥っていないでしょうか、区の現状をお聞かせください。特に協定の確認について、例えば数年に１度、どのように進展しているのか説明を求めました。","respondent":"松代防災まちづくり事業部長","answer":"今後の協定の見直しや確認についてもこれまでの取組みを継続してまいります。協定内容の見直しや更新につきましては、適宜、実施して行う予定です。","id":"exchange-063"},{"speaker":"大倉委員","kind":"質問・要望","question":"しっかりと協定内容が機能しているのか、これからもしっかり確認を行ってほしいと求めました。以上で質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"品川区の観光について、まず区の考えを教えていただきたいのと、観光といって何を頭に浮かべるか尋ねました。","respondent":"中川原地域振興事業部長","answer":"来年度は１０年ぶりに、基本指針である観光アクションプランの見直しを図るとともに、文化・芸術・スポーツ部門との連携強化も図っていくものです。大きく三つほど考えてございまして、都内でも有数のやる気とアイデアあふれる商店街、そして海や河川等の水辺等が考えられます。","id":"exchange-065"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ここだったらこういう写真が撮れるというものを、ぜひ街角等に、このスポットはいい写真が撮れるなどというのを研究していただきたいと。訪れてもらうために、どのような施策を品川区として打っていくのか、そこをまずお答えください。","respondent":"中川原地域振興事業部長","answer":"そのときに大事なのは、品川区に訪れてくださる方のイメージを具体化して情報発信することだと考えています。暮らすように旅する方々、そういった状況を具体的にイメージしながら、ご提案のいろんな場面の紹介アプリ等に取り組んでいきたいと考えています。","id":"exchange-066"},{"speaker":"石田（し）委員","kind":"提案","question":"その泊まってもらった人たちにどうやって品川区の魅力を発信してもらうかというのも新たな展開だと思いますので、その辺の考えを教えていただきたい。提案ですが、私は品川区を、「アートのまち」にしてみてはどうかと思いますとの意見を述べました。","respondent":"中川原地域振興事業部長","answer":"それからゲストハウス等も、今さまざま稼働率を上げているところですので、そうした方々とも連携しながら考えていきたいと考えています。そうした民の力と、区が税金を使ってやるべきご支援とをさまざま組み合わせながら…","id":"exchange-067"},{"speaker":"石田（し）委員","kind":"提案","question":"花火大会の提案をしていますが、ぜひ、そういった花火大会の実現に向けてもぜひお願いしたいと思います。海外のガイドブックやパンフレットにぜひとも品川区の取組みを紹介するようなアプローチをかけるべきだと思いますが、その点もお答えくださいとの意見を述べました。","respondent":"中川原地域振興事業部長、山田副区長","answer":"それは、町会とか商店街に全国からの視察が多いということも言えるのだと思うのです。先ほどご提案のＳＮＳとか、訪れた人が本当によかったと広めていけるような、そういった広報手段についてさらに検討していきたいと考えています。 伺っていますと、これはまさにシティプロモーション、品川区のありようという部分をいかに外に発信するかという観点で非常に有効だと考えています。ある意味では民間の方がおっしゃる点もありますので、有効に…","id":"exchange-068"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いいものはそれを軸に、品川区の強みを活かした施策へと進んでいっていただきたいという思いもありますので、その辺もぜひお答えください。","respondent":"桑村副区長","answer":"後段のシティプロモーションあるいは観光アクションプラン、またはマスタープラン等の連携ということについてお答え申し上げたいと思います。その中で一つの目標としてやっていく意味では…","id":"exchange-069"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ対象にさまざまなものを施策に取り組んでいただきたいのですが、そこでまず区内の在勤者に対して品川区はどのような取組みを行っているのか。住み続けてもらうための施策、そして住んでもらうための施策について、どのような取組みをされていくのか、区のお考えを説明を求めました。","respondent":"中川原地域振興事業部長、桑村副区長","answer":"６月にＳＨＩＰのオープンを迎えまして、創業したいと思ったら、品川区に行こうと思っていただけるような仕事をしてまいりたいと考えています。この間、改善・改革を進めてまいりまして… 長期基本計画を確実に実施していくというのが基本の考え方ですけれども、安全で安心なまちをいかにつくっていくかということなのだろうと思います。これまで進めてきました小中一貫教育ですとか、それからオアシスルーム…","id":"exchange-070"},{"speaker":"石田（し）委員","kind":"質問","question":"収集したその情報をどう評価し検討しているのか、どのように安心を担保するような政策を打っているのかお答えください。","respondent":"中山総務部長","answer":"２３区の横の連携の会議等もありますので、例えば区でやっております総合評価制度あるいは最低制限価格制度というものをしっかり運用していく。こういうふうな動きにもしっかりと区としては対応しながら、また工事の質の確保といったものを図っていきたいと…","id":"exchange-071"},{"speaker":"石田（し）委員","kind":"質問","question":"」 そういった、コミュニケーションを重視した英語教育に進むべきだと思いますが、そこの区の考えをお答えください。それと、これまでの成果と今後の取組みについてもあわせてお答えください。","respondent":"田村教育次長","answer":"平成２５年度の保護者アンケートでも、小学校では９２.３％、中学校では８８.４％がよい取組みであるという回答をしております。小山台小学校のカリキュラムの実施を、３校で実施しているということでございまして、イングリッシュキャンプを実施したり。","id":"exchange-072"},{"speaker":"石田（し）委員","kind":"質問","question":"品川区の教育を行っていただけますので、そういった意味では留学制度等も導入するべきだと思いますが、その点についてもお答えください。アプリ等の活用をすることによって、育成カリキュラムをしっかりと構築する必要があると思いますが、区の考えをそれぞれお答えください。","respondent":"中山総務部長、田村教育次長","answer":"では、職員の育成・専門性という観点からお答えいたします。それから、研修あるいは自己啓発という観点での育成も図っているところです。 独自教員の海外派遣についてのご提案です。限られた人材の中で２,０００万円をかけて派遣という形になることについて… いろんな機関との連携もとりながら、いろんな仕組みも含めて、広報とも連携しながら伝えていく。このようなことを考えてあります。","id":"exchange-073"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そういったボランティアの育成にも努めてほしいと求めましたが、その点をお答えください。語れるような教育プログラムだったり、昔ながらの建物・風景の保存といった、日本の文化伝統を守る施策について区の考えをお答えください。","respondent":"中川原地域振興事業部長、田村教育次長","answer":"外国人向けボランティアの活動につきましては、委員ご提案のとおり、語学力の習得やコミュニケーション手段の工夫・開発が不可欠だと考えております。組織委員会や東京都からまだ具体的な内容は示されておりませんが… 品川区のまちをＰＲする授業等に取り組んでおりますし、８年生の教科書でも、グローバル人材としての資質も向上させる。両方セットでやっていく必要があるのではないかと、そのように考えております。","id":"exchange-074"},{"speaker":"石田（し）委員","kind":"提案","question":"さまざまな提案も含めて質問させていただきました。以上で、民主・改革ネットを代表しての総括質疑を終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは介護保険大改悪による要支援のサービス取り上げはやめ、充実を求めて質問します。予防通所事業、デイサービスの週１回の基本の単価が幾らになったのか、それぞれ説明を求めました。","respondent":"榎本健康福祉事業部長","answer":"そういった中で、今お尋ねの生活機能向上支援の部分につきましては、単位数ではなくて金額ということなので、１万１,４００円という形です。それぞれ個別に単価設定というのができますけれども、その基本の部分だけでいきますと、１万１,１１８円というものです。","id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問","question":"それによって要支援者を受け入れられない事業所が出れば、受け皿がなくなり、結局、サービス取り上げになるのではないでしょうか、伺います。介護報酬単価の引き下げが、さらに介護職の地位を低迷させ、募集しても集まらないという事態を広げると思うのですが、いかがか尋ねました。","respondent":"榎本健康福祉事業部長","answer":"例えば下の段、標準的な送迎・入浴を加えた場合には１万７,２２２円ということで、金額がそこに示されているものとは違うという形になります。今回は処遇改善加算というものも、そういうのも入れながら…","id":"exchange-077"},{"speaker":"石田（ち）委員","kind":"質問","question":"ほかの事業を考えなければ経営も危ないと、大変悩んでいます。赤字でも頑張れということなのでしょうか、伺います。","respondent":"榎本健康福祉事業部長","answer":"そういった意味で、中・重度の方を重要視して、そちらに集中しないとなかなか難しいだろうと。各自治体が創意工夫を図って、その地域に応じたものをできるようにということで、枠組みを切り替えたものです。","id":"exchange-078"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これをサービスの取り上げと言わずに何と言うのでしょうか。４月からの要支援者の介護給付費サービスの取り上げは中止し、事業所の単価は今までと同等にすべきと強く求めますが、いかがか尋ねました。","respondent":"榎本健康福祉事業部長","answer":"要介護認定の仕組みそのものは、何も変更してございません。事業所のほうですけれども、各事業所にも説明をして、４月からの実施に何ら問題はございません。","id":"exchange-079"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、品川区も給付費削減に伴い、保険料引き下げをするべきと思いますが、いかがでしょうか。低所得者ほど重くのしかかる介護保険料は、値上げではなく、この増収分も使って引き下げこそすべきですが、いかがか尋ねました。","respondent":"榎本健康福祉事業部長","answer":"その後の３年間だけでなくて、今後１０年間を見通した介護保険事業計画をつくるというのが、今回の大きな改定の趣旨です。これから後期高齢者が３年後には高齢者の中の半分を超えるという形も想定されていますので、５,３００円を引き下げるつもりはございません。","id":"exchange-080"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"決められるわけですから、そして準備基金からもどれだけ出すかを区が決定できるわけですから、２５億円の増収分が入るわけです。ですので、給付費、つまりサービスの量によって保険料は決まるわけですから、これだけ減らせると私は思うのですけれどもいかがか尋ねました。","respondent":"榎本健康福祉事業部長","answer":"そこに対して、１７億８,０００万円の基金のうち１１億５,０００万円ということで、６５％を入れて５,３００円ということを設定しております。２１区の平均の保険料は５,６９０円ということですので、品川区の５,３００円というのは…","id":"exchange-081"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"改めて、適地として選定してきたのはどこか、現在どこまで検討しているのか伺います。広町２丁目、劇団四季隣の区有地は、開発ではなく特別養護老人ホーム増設に使うべきと思いますけれどもいかがか尋ねました。","respondent":"榎本健康福祉事業部長","answer":"今後の介護保険サービス全体に対する利用者ニーズの変化、それから介護保険料への影響など総合的に判断して適切に対応していくという形です。暫定利用ということで、ある程度一定の数十年という期間で設置しないと…","id":"exchange-082"},{"speaker":"石田（ち）委員","kind":"質問","question":"広町２丁目の劇団四季隣の区有地は、開発の暫定地として２２年間も塩漬け状態になっている土地です。今こそ、区民の財産である区有地は、特別養護老人ホームなど区民の切実な願いの実現にこそ使うべきだと思いますけれども、いかがか尋ねました。","respondent":"榎本健康福祉事業部長","answer":"用地というものはそれぞれの目的でもって使うという形で整理しているわけですから、それぞれの目的のところでそういう用地の考え方をとっていかざるを得ないと考えております。","id":"exchange-083"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"誰もが入れる特別養護老人ホームのさらなる増設の計画を早急につくってほしいと求めました。いかがか尋ねました。","respondent":"榎本健康福祉事業部長","answer":"特別養護老人ホームがいいのか、グループホームがいいのか、それからあとは軽い要介護度の場合についてはサービス付き高齢者向け住宅がいいのか。一つだけの施設をとって、それでもっていくという形にはならないので、総合的な判断をしてやっていきたいと考えています。","id":"exchange-084"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、やはり誰でも入れる、低所得でも入れる特別養護老人ホームを、本当に多くの方が切実に求めています。ですので、ぜひとも特別養護老人ホーム増設、そして「公的保険の介護は充実を」を求めて私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、一人の待機児も出さないための認可保育園大幅増設を求めて質問をいたします。区長がこの思いを受けとめて、自治体としての責任を果たすこと、区長みずからが掲げた待機児ゼロの公約を守ることを求めて質問します。","respondent":"金子子ども未来事業部長","answer":"それから平成２７年度のいわゆる受け入れ枠の拡大数ですが、こちらについては７０９人です。そのうち、４月に新たに拡大する数が３７０人、そのうちの０から２歳は１８８人です。","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このことについてどう捉えているのかをまず伺いたいと思います。この人たちは一体どうすればいいと考えているのかについてもお答えください。","respondent":"金子子ども未来事業部長","answer":"それが現状でありますけれども、私どもとしましても、こういった事態を踏まえながらも、なお積極的に取り組んでいこうという考えです。７０９人という数を、保育園の入園申し込みが増加するような傾向に関しましては、積極的に対応していきたいと考えています。","id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"どこにも入れない人、こういう人はどうしたらいいのかと聞いているのです。どんな選択肢があると考えているのか改めて伺います。","respondent":"金子子ども未来事業部長","answer":"先ほど申し上げましたとおり、認証保育所等々の施設あるいは年度内に今年はさらに３３９人の枠を確保しておるわけですので、こういったところにお申し込みいただいて、あるいは私ども等にご相談いただければ丁寧なご相談に応じたいと考えています。","id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だからこそ、私たち共産党区議団は何度も何度も、「４月に一人の子どもも路頭に迷わせないための緊急対策をとりなさい」と求めてきました。こんな状況になっていることに対して区としては反省がないのでしょうか、お聞きします。","respondent":"金子子ども未来事業部長","answer":"ただ、工事等が結果としてできないなどの、残念ながらいろんな状況がありまして、７０９人にとどまったという状況であります。この数字でありますが、さまざまな手法を検討して、今後とも積極的に取り組んでまいりたいと考えております。","id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この公約に責任を持とうという思いはないのか、私は区長に伺いたいと思います。区長、いかがか尋ねました。","respondent":"金子子ども未来事業部長","answer":"認可保育園等々あるいは認証保育所等々に入れなかった方については、私どもとしましても重く受けとめているところであります。これは区としての政策目標ですので、これに向けて努力していくということですので、そのようにご理解いただければと考えています。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"これは福祉に使うべきお金ではないでしょうか。共産党が提案しています２０園増設は十分可能ですとの意見を述べました。","respondent":"金子子ども未来事業部長","answer":"私どもとしましては、必要な保育施策については、子ども未来事業部としても十分予算を執行して事業を進めているところです。来年度以降も保育の実施の責務というのは区にありますので、総合的に対策をとっていき、これを積極的にとっていくという姿勢に変わりはございません。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区が責任を持って、緊急対策と抜本対策をとることを強く求めます。もう一つ伺いたいのが待機児童の数え方です。","respondent":"金子子ども未来事業部長","answer":"平成２６年度までは保育所入所待機児童ということで国から調査が参りまして、これについて回答するという形の数字でございました。平成２７年度からは、子ども・子育て支援新制度がスタートしまして、変わっております。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だから、実態と大きく違う待機児童の数になるのではないでしょうか。改めて５月申請者を待機児にするのはやめるべきだと思いますけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"認可外保育園に絞って伺います。認可外保育園の区内の数、１人当たりの平米数と職員体制、補助金、保育料、立ち入り調査がどうなっているのか伺います。","respondent":"金子子ども未来事業部長","answer":"かなり差はありますが、１歳児を例にしますと、月額で約１０万円になります。実際の立ち入り調査の場面では、区の職員も同行するようにしておりますので、区としても現状の把握に努めているところです。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから園に対して、認可保育園や小規模保育事業などに移行への援助をすべきではないかと思うのですが、いかがでしょうかということが２点目です。それから３点目として、認証保育と同様の保育料助成をすべきではないかと思いますが、いかがか尋ねました。","respondent":"金子子ども未来事業部長","answer":"２番目の認可保育園等の移行ですけれども、基準等々の遵守もありますけれども、適切に支援するという考えで実際に支援しています。ですので、これを一律に助成するというのは非常に現状としては難しいものであると考えているところです。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どの子も豊かにすくすく育つ権利を保障すべきです。区が責任を持って、希望する子どもを安心して預けられるよう、必要な数の認可保育園をつくることを求めて、共産党の総括質疑を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"須貝委員","kind":"質問","question":"６５歳以上の高齢者のうち５人に１人が認知症であるという計算となりますが、現状はどうなのでしょうか、お答えください。その現状についてもお答えください。","respondent":"榎本健康福祉事業部長","answer":"全国的にやはり介護人材の確保というのが困難になっているということで、これからも一生懸命、介護人材の募集に努めてまいりたいと思います。全部、必要なところにきちんとケアマネジメントが届くような形で…","id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"今、質問したのですが、まず介護現場の処遇について改善されているのでしょうかという質問をいたしましたので、もう一度お願いいたします。実際、こういうふうに、こういう状態の方が増えているのだというケースがあると思うのですが、その辺について再度質問します。","respondent":"榎本健康福祉事業部長","answer":"要支援の方から要介護５までの方がいらっしゃいまして、車椅子での介護サービスをどういうふうにしていくかとか、そういう形になっていると思います。早期発見等が難しいので、どうやったらそういう発見ができるかとか、そういうものも含めて取り組んでいるところです。","id":"exchange-098"},{"speaker":"須貝委員","kind":"質問","question":"認知症高齢者がますます増えている現状に対して、区としてどう対処するお考えですか、教えてください。対応できないならば、介護される方がその入口でとめるような仕組みもつくらなければいけないと思うのですが、何か対策があれば説明を求めました。","respondent":"榎本健康福祉事業部長","answer":"例えば介護学校であれば、２年生が１年生を教えて、そのような形で品川区は進めていきたいと考えています。早いうちから心がけていくことで、これからの認知症高齢者の増加を防ぐような形をとっていきたいと考えています。","id":"exchange-099"},{"speaker":"須貝委員","kind":"意見","question":"もう認知症に入って、さらに要介護１、２になってしまったら、もうとまりません。やはりそういう仕組みというのは大事ではないかと思うのですが、ご見解を説明を求めました。","respondent":"榎本健康福祉事業部長","answer":"週１回でも、もしくは月１回でも、仲間と一緒に外に出て、食事をするなり話をするというものを習慣づける事業も始めております。ただ、そこだけに重点を置けば全てがうまくいくというものではありませんので、地域のお力を借りながら進めていかなければいけないと考えています。","id":"exchange-100"},{"speaker":"須貝委員","kind":"質問・要望","question":"できなかった問題や苦手な問題に対して、できるようになるまで継続的に教えていますか。それについてもお答えください。","respondent":"田村教育次長","answer":"学力定着度についてのお尋ねにお答えします。それをわかるような形でフォローしてやっているかというお尋ねなので、それは各学校、取組みを実施しております。","id":"exchange-101"},{"speaker":"須貝委員","kind":"質問","question":"子どもたちを９年間にわたって見守っているわけですから、そして中学２年生、３年生も毎年実施するべきではないのかお答えください。年度初めに本人の実力を計るためにも都立高校入学試験の過去問を実施したらどうか、お答えください。","respondent":"田村教育次長","answer":"ですから、そういうことを考えますと、区は２学年ですけれど、国だとか都を踏まえると、全学年のうち４年生以上は実施しているです。早くて夏休み以降ですか、各学校で都立高校の過去問を実施するということで、一律この時期にやるという考えは現在のところ持っておりません。","id":"exchange-102"},{"speaker":"須貝委員","kind":"意見","question":"そして、宿題も出ていますし、３年になりますと、入試対策のプリントも出されています。他県の公立学校でも、このように実施し、成果を上げていますので、品川区でも可能ではないかと思いますが、お答えくださいとの意見を述べました。","respondent":"田村教育次長","answer":"例えば全校で実施している朝学習を実施していたり、あるいは夏季休業中の補習教室ということで、全中学校でも実施しています。宿泊型４校だとか通所型２校だとか、福井県の例も参考に研究はしていきますけれど、現在の状況で充実を図ってまいりたいと考えております。","id":"exchange-103"},{"speaker":"須貝委員","kind":"質問","question":"それが、学校、また教育委員会の仕事ではないのでしょうか。その辺について、もう一度、再度お答えください。","respondent":"田村教育次長","answer":"１万８,４９４人のそれぞれの多様性に合わせて教育を、義務教育ですから実施するというのが大きな使命なのです。義務教育は、決して、そういうような多様化する子どもたちも受け皿として将来設計ができるようにするのが義務教育の使命だと考えております。","id":"exchange-104"},{"speaker":"須貝委員","kind":"質問","question":"ではどうやって、学校は学力の底上げに対してきちんと取り組んでいるのですかといったときに、では何を見ればいいのでしょうか。例えば僕らがたまたまそこで見た生徒は本当にまれな例なのか尋ねました。","respondent":"田村教育次長","answer":"例えば、小学校では６８.６％、「現在通っている学校に満足していますか」という保護者アンケートの質問では小学校で８９.７％が満足していると。中学校の保護者は８２.５％が満足しているという、やはり品川区の取組みが…","id":"exchange-105"},{"speaker":"須貝委員","kind":"質問","question":"学校というのは勉強をするためにできたわけですから、それは大事にしてほしいと思います。学習指導も、それを見きわめてきちんとする必要があると思いますが、ご見解を説明を求めました。","respondent":"田村教育次長","answer":"学校全体の成績は、全体の、あまり勉強は得意ではないという児童・生徒も含めてステップアップしてもらいたいという取組みです。志望校選択の相談に当たっては、そういう今までの蓄積を活かして相談に応じているということで、教育委員会としても考えております。","id":"exchange-106"},{"speaker":"須貝委員","kind":"質問・要望","question":"厳しい実社会で生き抜いていけるように、確かな学力を身につけさせる教育をするべきだと思います。以上で無所属品川の総括質疑を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-107"},{"speaker":"伊藤委員","kind":"提案","question":"２０％プレミアム付区内共通商品券発行、平成２７年度７９名拡大、品川区議会自民党が提案した多くの政策が予算化されました。本委員会で我が会派委員が指摘・提案・質問した全庁共通プロジェクト、これらを真摯に捉え、平成２８年度予算での具体化を強く望むものでありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-108"},{"speaker":"浅野委員","kind":"提案","question":"防災対策の強化、合計９地区を事業対象として木造住宅密集地域の改善を推進、我が会派がこれまで提案・要望してきた施策が数多く反映されました。空き家・ごみ屋敷対策の推進などの提案・要望を真摯に受けとめて、今後の施策に反映されることを強く要望し…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-109"},{"speaker":"いながわ委員","kind":"提案","question":"今回の予算では、我が会派が要望した多くの項目が実現された予算であります。今回の予算特別委員会において我が会派の所属委員が質問の中で指摘・提案した各項目を真摯に受けとめ、予算執行することを強く要望しとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-110"},{"speaker":"南委員","kind":"質問・要望","question":"消費税の８％増税と、実質賃金の１９カ月連続マイナス、国の悪政から区民の暮らしを守る防波堤として自治体の役割を果たすことが求められます。子どもの豊かな学びを保障するために、３０人学級など、教育環境の整備を求めます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"須貝委員","kind":"質問・要望","question":"公立学校においては、子どもたちが実社会で生き抜いていけるように学力を身に付けさせてほしいと求めました。以上を無所属品川の意見表明といたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-112"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/592877?Template=document&Id=1032#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":104082,"voices":242}},{"id":"h27-20150318-7","meetingId":"h27-cm03","date":"2015年3月18日","dateIso":"2015-03-18","committee":"厚生委員会","time":"午前１０時００分～午前１０時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"第４６号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第４６号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"これはここの所管ではないのかもしれないけれども、つまり保険で支払われる部分についての精査をしていく必要があるのではないのかなと思うのです。適正な医療が行われているかということについてはどこかで確認していく必要があると思うのですが、そういう意識がまずあるのか尋ねました。","respondent":"高森国保医療年金課長","answer":"医療費通知ということで１年に２回ですけれども、ご本人にも逆に注意を促す、そういう形で現状では進めているところです。都道府県化になったりいろいろな形の流れの中で、もう一度検討課題ということにさせていただきたいと思います。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問・要望","question":"どうしても高齢化になることは避けられない事実だから、こういう社会保障制度そのものの根底がどんどん厳しくなっていくことはわかるのですよ。出ていくものに対して、ある程度の確認をする仕組みもあったらいいのではないかなという思いがありますので、もう一言お答えいただきたい。","respondent":"高森国保医療年金課長","answer":"例えば同じような病名で２か所でかかっていたり、ちょっと変な話ですけれども、過度にそういうふうな医療を受診されている方があったりなどもします。品川区のほうから直接被保険者に対して警告を兼ねて文書を発送するなりして…","id":"exchange-002"},{"speaker":"たけうち委員","kind":"質問","question":"３ページの２．保険財政共同安定化事業の拡大ということで、３０万円超から１円以上、ちょっとここがよくわからないので、もう一回詳しいご説明をいただいていいか尋ねました。","respondent":"高森国保医療年金課長","answer":"すみません、ちょっと説明不足で申し訳ございません。平成２６年度までは１件３０万円超のレセプトが対象だったのですけれども、再保険をもっと広げるというふうな制度に変わるです。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"質問","question":"イメージは何となくそうなのだろうなと思ったのですが、そうすると、区市町村としてはプラスの方向というか、安定化の拡大なのだから、財源としては今までよりも多く入ってくるということでよろしいのか尋ねました。","respondent":"高森国保医療年金課長","answer":"予算上の話で恐縮ですけれども、見込みでは、同額に２,０００万円ぐらい乗った形で戻ってくるような見込みを立ててあります。何とも言いようがないところなのですけれども、今までのところは、品川区の場合は交付額のほうが若干上回っているという状況です。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"今度はいわゆる市町村というのですか、三多摩というのですかね、そちらのほうとあわせていくということになるわけですよね。そこと保険料を一緒にしていくと、そういう考えになるのか尋ねました。","respondent":"高森国保医療年金課長","answer":"２３区に対しては一定の率でもって保険料を徴収するという、市町村のほうは全く別の保険料率になるということになります。２３区は今保険料という扱いになっているわけですけれども、保険税という形で対応していて、延滞金を徴収しているところもあります。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"まだ決定していないからあれなのでしょうけれども、そうすると、イメージとしては、今２３区は同じ保険料なわけですよね、それは変わらずにいて、なおかつ、わからないですけれども、市町村分のものまで、どちらかというと２３区のほうで少し負担してあげると、そういうイメージなのか尋ねました。","respondent":"高森国保医療年金課長","answer":"その負担するというイメージというのは、実際に具体化するためのいろいろな検討会がこれから設けられてくるというふうな状況になるのだと思います。その決定をしたのが平成２７年１月１３日ですので、平成２７年度以降にいろいろな問題を解決しなければ…","id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問・要望","question":"最後に要望ですけれども、こういうご説明を求める方も当然いらっしゃると思うのですけれども、丁寧なご説明をしっかりお願いしたいと要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"６５歳以上の方の介護保険料は上がっているのに、なぜこちらは下がっているのかなというちょっと素朴な疑問です。軽減措置、多分この２００万円の方は非課税だと思うのですけれども、どれだけ保険料総額は上がってきているのかをちょっと参考で伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"６５歳以上の方と４０歳から６４歳までの方の比率というのですか、それに増減がありまして、諸係数が変更になってあります。おそらくこの方は非課税に当たるのかなということになっていまして、均等割額を２割軽減しますと、１１万円程度になるのかなというふうなところです。","id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"平成２３年度から旧ただし書きですので、４年の中で１１万円程度、本当に大幅にやっぱり値上がってきているなというのを感じます。これが今回２年目と、１人当たり保険料３.３４％の伸びとなったというところでは、２,２００円ということなのかをちょっと伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"は支援金等をいただきながら、それから継続可能な社会保障制度を進めていくという流れの中で今進めているところですので、その辺のところはご理解いただきたいと思います。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"これだけ景気もよくない状況ですので、どんなに保険料を上げていっても、やっぱり払い切れなくなってくる世帯は出てくると思うのですよね。ですので、こういったところをどう考えられているのかなというのをちょっと説明を求めました。","respondent":"高森国保医療年金課長","answer":"平成２７年度から国のほうでも１,７００億円を国保のほうに入れていくと。平成２９年度からも１,７００億円、加入者の方、被保険者の側から見た安定というところまで視点に置きながら舵を取り始めているところです。","id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"２０１２年で言うと、国保加入者の平均所得が１４１万円です、区内で言うとどうかはちょっとわからないですけれども。ですので、払える保険料にしていかないことには、持続可能性もなくなっていくのではないかと思うのですけれども、そこはいかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"５割、２割ということで、いわゆる低所得者層の方については今回対応するという形になってあります。おおよそですが、平成２５年度の所得に合わせて進めていきますと、おおよそ３００人ほどがさらに該当するというふうに推定しています。","id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やっぱり１世帯、先ほど言った３人世帯、世帯主だけが働いている収入２００万円の家庭で２万２,０９１円上がるわけですよね。やはり、やはりそこから増収分は保険料軽減に充てていくということをやっていただきたいと思うのでけれども、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"どうも２００万円というところで今回シミュレーションしますと、確かに１５％、１４％と著しく上がっております。１.０１だとか、また１.００だとか、その辺のところを全体で見ていただいてご理解いただきたいと思います。","id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで最後に、国保の短期証とかの件数をちょっと教えてほしいと求めました。平成２６年度で短期証と資格証の発行件数、あと差し押さえ件数を説明を求めました。","respondent":"高森国保医療年金課長","answer":"平成２６年の１０月現在の資料がありますので、短期証の対象世帯数は３,７１５世帯でございまして、資格証の世帯は１３１世帯です。平成２５年度の差し押さえ件数は３９４件で、平成２６年度は１月末現在で４８５件です。","id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私たちはずっと言わせていただいているのですけれども、この差し押さえは、本当に連絡がとれて、状況がわかった世帯への差し押さえではないですよね。この間話を聞かせてもらっているところでは、この差し押さえで収納率が上がっているという状況、そういう関係なのか尋ねました。","respondent":"高森国保医療年金課長","answer":"現在は平成２６年度からですけれども、未納ではないですか、お支払いくださいということでご案内を差し上げるような形でアプローチをしています。６月に保険料を賦課させていただきまして、または生活状況調書を出していただいて、その辺のところもご理解いただきたいと思います。","id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そこを見つけ出すというのがなかなか難しいと思うのですけれども、そこは本当に粘り強くやってほしいと求めました。差し押さえを突然するということはしないでいただきたいなと思います。","respondent":"榎本健康福祉事業部長","answer":"差し押さえ関係につきましては、私のところまで決定が回ってきていますので、私もよく経過を見ております。分納約束をしたのにそれができていないとか、ご相談いただければ、そういう形になる前にきちんと対応ができるというふうに思っております。","id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"では、特殊事例だけで、この４８５件ということなのですか。やはり、そういった乱暴な差し押さえはすべきでないというふうに申し上げたのですけれども、これは全て特殊事例ということか尋ねました。","respondent":"高森国保医療年金課長","answer":"滞納して３ヶ月ぐらいで差し押さえ、最低でも半年以上は継続して未納が存在しているだとか、過去において納付約束をしたけれども守れない。この２年の中でどういう形で、開けない方もいらっしゃるのかもしれませんけれども、その辺のところだけは申し上げします。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"意見","question":"本議案に賛成いたします。品川区にお願いしたいのは、そういう個々の方々に対しては十分な説明とご理解していただくことをお願いしておきまして、賛成いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そして収入減も進んでいるというもとでは、払える国保料にしていくべきだと思いますので、さらなる値上げというのは私は反対です。そういった思いに応えて、一般財源の投入をしていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/841532?Template=document&Id=3412#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":18956,"voices":49}},{"id":"h27-20150326-10","meetingId":"h27-cm03","date":"2015年3月26日","dateIso":"2015-03-26","committee":"議会運営委員会","time":"午前１０時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"平成２７年請願第７号、区民の期待に応える品川区議会改革を求める請願","agenda":"平成２７年請願第７号、区民の期待に応える品川区議会改革を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"意見陳述は、採決の前ではなくて、この請願者の思いをしっかりと受けとめる立場で、審議に入る前に意見陳述をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところはやはり区民の思いですから、私たち議員としてはしっかりと受けとめることが必要だと思うのです。だから、ぜひとも審議の前に聞くように諮っていただけますか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"議会のことであるだけに、私は、区民の声を議会が真摯に受けとめるという、そういう姿勢を議員として持つべきだと思うのです。そういうことでの申し出ですから、そういう姿勢が求められていると思いますので、ぜひ諮ってください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"同じ会派の方が出席されているのですから、それに対してさらに本人が意見陳述するというのは、ちょっとどうなのかなと思います。私は、別段委員長の采配は間違っていないと思うのですが、どうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここに書き込めていない、もっと多くのたくさんの願いをぜひ聞いてほしいという区民、請願者に与えられた意見陳述の場です。なので、ぜひ諮ってほしいと求めましたので、委員長、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"このＡ４版の用紙に入る文面しか提出してはいけないのですか。例えば、これが５枚になろうが、１０枚になろうが、だめなのか尋ねました。","respondent":"伊藤委員長、原区議会事務局長","answer":"委員同士の議論、それから審議を踏まえた後にお諮りしますので、ぜひそういうことで進めていきたいと思いますので、よろしくお願いいたします。… 既に朗読が終わりましたので、本件について、事務局長の説明をお願いいたします。 ２点目になりますけれども、請願を提出した区民側の詳細説明や公平な発言の機会を設けること、こういった趣旨のところです。３点目につきましては…","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"４番に関しましては、規則の変更をしたりすることによって、いろいろ書くことは可能なのですかね。３週間後に議事録が上がりますから、そちらをご確認くださいのほうが、逆に親切なのかと思います。","respondent":"原区議会事務局長","answer":"１０時からの開議ですと、やはり３０分前に来なくてはいけないというようなことがありますし、これも方法としてはなかなか難しいかです。５つのところから音声を拾う形にして、５つの部屋を用意して、なかなか難しいというようなところです。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問・要望","question":"例えば、会議録をつけてお送りするとすれば、採択、不採択等の通知は、３週間後であれば、こちらがお求めになっていることは可能だということ。改めてもう１回、そこを先にお願いします。","respondent":"原区議会事務局長","answer":"これは議会のあり方検討会でも議論があって、そこについてはなるべく早く区民の方にお知らせをしていこうと、ただし。そういった意味では、ホームページで議論を確認できる仕組みとして、今は提供させてもらっているという位置づけです。","id":"exchange-008"},{"speaker":"渡部委員","kind":"意見","question":"１番は、今お話を聞いていたところですと、なかなか難しいのかなと思います。委員会自体の開催をどういうふうにしていくべきなのかというところから入っていかないと、今の段階では解決が難しいのかということを感じましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"請願が複数出てきていたときに、例えば１番目の請願を聞いて入れ替えるとかということが考えられるのか、それを教えていただきたい。それができてから３週間後に採決のご報告をするとなると、もし可能であれば、その点についてお伺いします。","respondent":"原区議会事務局長","answer":"書記を含めて１０名の職員が委員会に張りつく形になってありますので、あるいは各委員、現実的な運用としてはなかなか難しいというところがあります。考え方としてはありますけれども、これについても、徹底をしてくれというのは非常に難しいところもあります。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民要望を出して、働いている中身をもっともっと知っていただきたいという意味において、この傍聴の問題はすごく大きいと思うのです。皆さんにご意見をお伺いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問・要望","question":"１番目は、総務委員会にいるのですが、本当に傍聴者ゼロということがほとんどですかね。今回の請願の趣旨というのは、私はどうなのかなという疑問を感じます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"確認したい点、そのうえで確認があった中で、この議会改革を求める請願について傍聴等の現実を含めて。４点目だけ確認させていただきたいのが、そうした理由、根拠を明記している区もあるとおっしゃっていました。","respondent":"原区議会事務局長","answer":"そこで、いろいろな意見が出たときに、その意見を全て載せてくるというのはなかなか難しいということもあると想像します。それを幾つかの意見にまとめて確認を取っていくというのもなかなか難しいと、私どもも理解しています。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"最後の今のところだけ確認で、現状と課題の部分もいただいて、事務的な部分では非常に悩ましい部分であると思います。いかにもさもやっているような発言をするとか、そうしたことも含めて、正確性というところは非常に求められる部分があると思うのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"傍聴規則を変えればいいだけのことですから、ぜひそれはご検討いただきたいと思うのですけれども、ということが１点です。議会として、いかがでしょうか、皆さんのご意見をお聞かせいただけたらと思います。","respondent":"原区議会事務局長","answer":"その辺は事務局の考え方も一緒ですけれども、火災とかで避難をするとか、そういったことも状況としては考えていかなくてはいけない。本会議場の磁気ループの設置等々についても、そういったところで積極的に対応していると理解しておりますので…","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区民に本当に開かれて、常に改善を目指していくことは本当に必要だと思いますので、そういう立場でやっていきたいと思います。４番は、ここで決められたらいいと思っているのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"前回の区議の選挙が４０.５８％なのですよ。政治離れについて、どうですかね、皆さん、今の状況。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問","question":"品川区議会改革ということは、私たちが自発的にやっていくべきことであって、しかもそれを検討委員会等でもしてきたわけです。議会改革を自分たちでしっかりと進めてきているわけですから、意見陳述は、今回は必要ではないと考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"つる委員","kind":"提案","question":"それぞれの趣旨について発言がされて、相当程度、皆さんのほうから確認がなされた。逆に、提案も含めてあったと思いますので、私たちとしてはこの陳述については必要ではないと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"意見","question":"我々も、今さまざま議論をした中では、私としては十分、今回の請願の思いも含めてのお話をさせていただきましたので、我が会派としても、今回は特段あえて陳述を聞く必要はないという判断をしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本請願の中に、ぜひ意見を言わせていただきたい、意見陳述させていただきたいというのが盛り込まれている請願です。ここが不足しているという指摘が含まれていますので、ぜひ本委員会においてしっかり受けとめて、意見陳述をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"須貝委員","kind":"意見","question":"開かれていくと思いますので、我々も、皆さんのこういう話を聞きながら、また一歩一歩改革をしていきたいと思います。この趣旨に沿いがたい、ちょっと違うということで、これには賛成できないということの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"渡部委員","kind":"意見","question":"私たち既にやっているところもありますし、今の説明の中で、なかなかできてこないところもある。そのようなことを鑑みますと、結論を出して、不採択ということでお願いをいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"紹介議員の説明を求めることができると、また求めに応じなくてはならないとある中で、応分の趣旨を踏まえたご意見があったかと思います。そうした意味も含めて、これまでも当然取り組んできたということも踏まえて、この請願については不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"石田（し）委員","kind":"提案","question":"本当に議会をもっともっとよくしていくために改革を進めるべきだという立場で、これまでも、そしてこれからも改革には取り組んでいく所存であります。我々が提案をしている工夫の中でやっていただけるような話もあったので、既に十分に対応されていると思っていますので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民に開かれた議会、議会の傍聴の促進とか、議会の情報の公開、また、広報活動など促進を求めているこの請願は当然と受けとめています。採択を主張いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993740?Template=document&Id=5140#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":22920,"voices":51}},{"id":"h27-20150526-7","meetingId":"h27-cm05","date":"2015年5月26日","dateIso":"2015-05-26","committee":"厚生委員会","time":"午後 ３時０５分～午後 ３時５２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"第５０号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第５０号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"第１段階と第２段階でそれぞれ教えていただきたいということと、もとの０.４５で送られているのか、０.４で送られているのかという確認ですね。この改定に当たって、国から入ってきたお金というのが幾らなのかということをお答えいただけますか。","respondent":"永尾高齢者福祉課長","answer":"対象者へのお知らせについては、現在のところ条例が０.４５になっておりますので、０.４５ということで通知をしています。都が４分の１、区が４分の１ということで補填されるということになっておりまして、まだ金額については確定はしておりません。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"前期、第五期のときに既に０.４の保険料率だったと思うのですけれども、それで、今回第六期のときに、そのまま維持して０.４のままで行って、そこに国の軽減の額が０.０５入ってくるということで、０.３５にすることができなかったのかという、そこの考え方をお聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"そうすると、その上の方の、こういうことも考えながら料率というのを定めているものです。まだ確定はしていないのですけれども、消費税が１０％になるのが平成２９年４月という見込みという話が現在出ているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"第１段階、第２段階をさらに下げていくと、そこで財源をつくって下げることができるのではないかと考えています。そこの考え方はいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"保険料も引かれ、健康保険料も引かれ、所得が少ないという理由だけで極端に減らすというのは理解を得るのが難しいかと思います。今説明しているのは第一号被保険者のことですけれども、低所得者だけを見て変更するというのは、今回の料率の設定を考えたところです。","id":"exchange-003"},{"speaker":"のだて委員","kind":"意見","question":"第２段階の方で非課税の方もいらっしゃって、今２,０００万円にとどまらず、ほかの区でもやっておりますので品川区でも取り組んでいってもらいたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"１点ご質問させていただきたいのですけれども、ほとんどの方が掛け捨てというところで、サービスを利用されていないという状況があります。平成２９年の４月以降の消費税１０％に当たりまして、二号の設定、そして今後の方向性というところを詳しく教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"第１段階がマイナス０.１５、第２段階がマイナス０.２５、第３段階がマイナス０.０５になります。現在のというか、今回ご議論いただきます料率からさらにその同じ率を差し引いた料率にしようかというふうに考えているところです。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは平成２９年４月に上がったらまた改正するわけで、そういう予定が今あるのに、ここら辺の物事の考え方を教えていただきたいなというのが１つ。やっぱり丁寧にもう一段お考えをいただきたいということと、１を超える、やっぱりしっかり説明をしたほうがいいと思う。","respondent":"永尾高齢者福祉課長","answer":"２つ目のこの条例の改正、消費税１０％の見込みがあるのであれば平成２８年度まででというようなご意見でございましたけれども、区といたしましては。３つ目ですけれども、二号被保険者への説明につきましては…","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"意見","question":"高齢者が増えてきてサービスがどうだとか、それには繰り入れをどうしようとか、最終的には国の法律変えろみたいな話になってしまうわけで。それは今のこの制度の中でしっかり区が説明する責任があると思うので、そこについてはお願いだけしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"区が４分の１という説明があったような思いがしたのですけれども、そこのところの財源がどういう形で来るのかということをひとつ教えていただきたい。説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"保険の制度の仕組みの中で、公費の部分を増やすという考え方になっているので、そのルールにのっとって２分の１と４分の１と４分の１というふうになっているものです。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"品川でいえば第１段階、第２段階のところは、７割減額という形で０.３というのを出してきているという部分があると思うのですね。特にここのところが本当に大変な状況というのがあると思うのですけれども、そういう中で、そこの考え方というのはいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"それで、第３段階が０.３、第４段階が０.６５になるという見込みが出ているところです。高額の７段階から１４段階までの方については変更ないということですので、この平成２９年の４月のことを見据えますと、今回０.４にしたところです。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これだけ必要だというふうなことで打ち出したわけですから、消費税が８％に増税されて、２５億円の増収にもなっているわけですよね。私は低所得者のさらなる減額というところをぜひとも今後検討していただきたいというふうに求めておきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"やっぱり将来継続してきちんとしたサービスが受けられるような安心感というのが必要ですので、これからも考えていきたいと思っています。区民の皆様のご協力もいただきまして、健全財政でやっていっておりますので、あえて一般財源を入れるということは考えておりません。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は改めて、ここの先をさらに検討した場合どうなるのかという試算をぜひともしていただいて、示していただきたいというふうに思っているところです。それからもう一つ、６５歳以上の方の基金についても、さらなる活用もぜひともお願いしたいということを意見として述べておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認をします。例えば２３区、やっぱり特別区はこういうことなのだというのはもっとしっかり言っていくべきだと思うのだよね、区も。","respondent":"永尾高齢者福祉課長","answer":"なかなか難しいところはありますけれども。国のほうもそういうところはきちんと認識はされておりまして、保険者の裁量のきく部分というものも増やしてきているところですので。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"資料１の改正の趣旨で、趣旨でしっかりお話が来ているのかどうかということの確認、国の目的があるのであれば教えていただきたいのが１つです。消費税率１０％というお話がありましたので、そこの確認、そのとおりに国はこの財源を使っているのだというご説明があればお聞きしておきたいなと。","respondent":"永尾高齢者福祉課長","answer":"本当はもともとは３月の末までに予算が可決するという見込みを立てて、それを見込んで、それで計算をしていました。被保険者の人数とか、そこら辺は想定の中でやっていますので、多少流動される可能性はあるかというふうに考えているところです。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"財源はしっかり確保できているわけですから、地域包括ケアという考え方もありますので、またしっかり今年度も事業を進めていただきたいなと思います。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/841532?Template=document&Id=3414#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":14194,"voices":41}},{"id":"h27-20150526-9","meetingId":"h27-cm05","date":"2015年5月26日","dateIso":"2015-05-26","committee":"文教委員会","time":"午後 ３時０５分～午後 ４時２１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"第４９号議案、平成２７年度品川区一般会計補正予算","agenda":"第４９号議案、平成２７年度品川区一般会計補正予算","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"去年との比較などもあれば教えてほしいと求めました。それとも何らかの対応というのでしょうか、そういうものは何かお考えがあるのか、その成果等をあわせて教えてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"平成２６年度の当該年度の数が１２８名ですので、８７名プラスされまして、ことしの４月１日は残念ながら待機児童数は２１５名で増加しております。待機児童が多いエリアという形でございまして、約半数以下になりますけれども…","id":"exchange-001"},{"speaker":"浅野委員","kind":"提案","question":"今回は大井地区ということでこういう提案が出てきているかと思いますけれども、荏原地区でもこういうような提案が出てくればいいと考えていますが。小さい子どもたちですから、この点については本当に大丈夫なのかという、この確信のほどを教えてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"劇団四季が実施したときには、これは民間の劇団四季側が調査したのですが、出たところが、今回の施設計画と真反対のＪＲの駅側のところです。５月の中旬に中間報告が速報ということで調査いたしましたけれども、最終報告は６月の中旬になろうかと思いますが、問題はございません。","id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"最終は６月中旬ということですけれども、変わらないデータという形で、結果としていただけると伺いました。５年を超えてまだ待機児童の解消ができていないというような状況については、最長でどの程度、そこら辺も教えていただけたらと思います。","respondent":"今井待機児童対策担当課長","answer":"今後、そこのあいている部分、特に４歳児・５歳児についてどのようにやっていくかは、事業者とともに検討させていただきたいと考えています。冒頭ご説明申し上げましたとおり、今、５年以降の延長については現時点では申し上げかねます。","id":"exchange-003"},{"speaker":"浅野委員","kind":"確認","question":"定員が３００人ということですと、大丈夫でしょうねということを確認しておきたいと、そのように思います。この点についてどういう方策を考えられているか説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"この園舎の借上げ支援のほかに、これから大規模特有のニーズ等がありますので、検討する必要があるかと考えています。都内に５施設ぐらい既に保育施設をやっていらっしゃる事業者ですとか、今後、速やかにプロポーザルを進めていきたいと考えています。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"どうもありがとうございました。引き続き荏原地域にも尽力いただければと要望いたしまして、私の質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回３００人を預けられる保育所ができることは、なるべく早急にお願いしたいと思いますが、２点質問します。むしろ医院とか医療関係がどうなのかが心配な点がありまして、その辺のご検討はどうなのか、この２点についてお伺いしたいのですけれども。","respondent":"今井待機児童対策担当課長","answer":"今後また改めていろいろ協議のご依頼をしていく中でご検討いただく部分はあるかと思いますので、引き続き協議は進めさせていただきたいと思います。運営事業者と相談しながら、地域の医療従事者等もいろいろご紹介しながら、きちんと進めさせていただきたいと考えています。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"敷地面積が約１,６３６m2ということですけれども、駐車場としてはもう少し広いと思いますが、この全体の広さをお伺いしたいと思います。それと園庭があるのか、ないのかを伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"そして、そのうちの約６割のところを保育施設に充てることになります。それが予定では大体２００m2程度と考えておりますが、屋外遊戯場としての園庭はしながわ中央公園等で確保していくことになります。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、もともと２,７００m2あるのでしたら、そこを６割使ってということですけれども、全部使うことはできないのでしょうか。伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"代替の施設として、現在ではしながわ中央公園を考えておりますが、しながわ中央公園としてお届けする予定です。近隣の商業施設の方々の利用も含めて駐車場にしてほしいというご要望をいただきながら検討を進めてきたものですので、今も設置しておりますが。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"屋外遊戯場の設置をしてほしいと求めました。そして、今ある駐車場を保育園として使えるという工夫もして屋外遊戯場をつくっていく検討もしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"委員のご指摘の場所はＪＲの所有地です。民間事業者はそれぞれの考え方の中で運営しておられますので、品川区としては、今あります区有地の中できちんと対応してまいります。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"３００人規模のものが建てられるということであれば、ＪＲとも協議を進めていって駐車場のあり方と屋外遊戯場のあり方を検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"そういった中で、さらにＪＲの用地を借りて行うことは、区としては難しいと考えております。公立施設も同じだと考えておりますので、一定、まずは待機児童対策という形で定員をこのような形で進めさせていただきたいと考えております。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今後の計画について２点伺いたいのですが、その辺の方針がいつぐらいにどう出されていたのかをお伺いしたいのと、ぷりすくーるは公設民営で。委託の内容がどういった中身で、今後チェックができるのかどうか、そこをお伺いしたいのが２点目です。","respondent":"今井待機児童対策担当課長","answer":"保育所の部分、フルの認可保育園として１歳児から５歳児まで進めること、それから指定管理者ではなくて委託と考えております。子ども・子育て計画もそのようになっておりますので、子ども・子育て計画に合わせまして着実に開設は進めていきたいと考えています。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺の歯どめというか、そこをチェックすることができるのかどうかを１点お伺いします。４施設、一刻も早く待機児童をなくしていく方向で保育園をどんどんつくってほしいと求めましたが、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"私どもも、大規模保育特有の人数による主任保育士の加算ですとか、そういうことも含めて検討してまいりたいと考えています。検討は進めます。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"求めれば出て、どこまで議会が求められるのか、そこの点を教えていただきたい。この３００人と、合わせて５８０人で来年の４月１日の保育需要はどのぐらい満たされていると考えるのか、改めて説明を求めました。","respondent":"今井待機児童対策担当課長、金子子ども未来部長","answer":"ただし、現在の保育士確保の状況を言いますと、逆に言うと、低賃金では今はなかなか保育士を確保するのは難しいというのが、大体、民間の考え方です。さらに保育需要の伸びが想定される部分もありますけれども、来年につきましては… 今回、なかなか保育士が確保できないというところから、国のほうでも１人平均９,０００円のアップを盛り込んでいる考え方があります。プレス発表の段階で１人当たり、２万１,０００円の賃金アップを想定して…","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"まだよくわかりませんけれども、これは事業者に１人を雇うところで例えば国から９,０００円とか、そういった中身の算定になってくるわけでしょうか。もう少し詳しく教えてほしいのと、その辺がきちんと働く労働者に、保育者に回るようなチェックもできるのか、その辺も説明を求めました。","respondent":"金子子ども未来部長","answer":"あるいはさまざまな資格等々によって賃金体系も変わってきますので、そういうところについては、私どもとしてはまず質の確保が十分できるということを前提にしっかりチェックしていきたいと考えております。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひしっかりとチェックをしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"それは品川区としても何らかの安全対策をとるべきではないでしょうかということが１点と、５年後となっているのだけれども、所管が違うでしょうから。逆に言うと品川区は５年間それを認めてしまったのかなとなると、その辺はどういうお考えなのかということをまず確認をさせてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"詳しくは、あくまでも区としては暫定施設としまして一部の利用という形で考えておりますので、その検討を後ろ向きにするものでは全くございません。今後も引き続き検討すると聞いております。","id":"exchange-016"},{"speaker":"伊藤副委員長","kind":"質問","question":"そのときに、この園の子どもたちをどういうふうに吸収していくかということについても、我々は責任を持っていく必要があると思います。これが例えば５年先なのか７年先なのかわからないけれども、検討していくべきだと思いますが、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"そういうものを立てて注意喚起するということを少し手前からやっておりますので、それも含めて検討していきたいと考えています。この５年間がたって、今どのようにするかということがまだ明確には申しませんけれども、区として受け皿を確保する責務があると考えております。","id":"exchange-017"},{"speaker":"伊藤副委員長","kind":"質問","question":"もしくは、これも拡大してもいいわけじゃないですか、大井町だから。なかなかお答えしにくいとは思うのだけれども、対処すべきだと思いますが、いかがか尋ねました。","respondent":"金子子ども未来部長","answer":"再開発の折のさまざまな考え方についてのお尋ねですけれども、こういうものは必ず入れないとか申し上げにくいところがあります。私どもとしては全体の政策として考えていくべきものだと考えていますので、こういったものを踏まえた上で考えていかなければならないと考えています。","id":"exchange-018"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"開設期間のところだけ確認しますけれども、５年間ということで、協議がさまざまな形で進む可能性も出てくる可能性はありますよね。つくるわけですから。","respondent":"金子子ども未来部長","answer":"もう一方は別の問題として、公共施設の中でも私どもの児童関係の施設は、かなり年数がたってきております。そういう意味では、そういった施設をあわせて、そういう意味では少し広目なところで広範に考えていく必要があるのではないかと考えています。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認させてほしいと求めました。登園の安全性の確保という部分でいうと、今、どうやって安全性を確保するのかというところを教えてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"現在まだ検討中でございまして、１歳児はそこまでは入りませんので、４０人から５０人程度のところで１歳児というところで考えております。どちらかというとＪＲ専用の通路から入ってまいりますので、そこも今後ＪＲと協議しながら…","id":"exchange-020"},{"speaker":"大倉委員","kind":"確認","question":"ぜひ煙とか、ほこりという部分では、子どもたちには内庭が２００m2あるということで、そういった部分の配慮をお願いしたいと思います。１点、確認ですけれども、これはだから１カ月ごとに延長期間分だけ増えていくということか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"今回のリース契約は、全ての建物の設計から運営時のメンテナンス、そして解体工事も含めてのメンテナンスになりますので、もし期間を延長した場合には、再リース契約を結ぶ形になると考えておりますので、そのときまた適切な金額を算定してご審議いただければと考えています。","id":"exchange-021"},{"speaker":"高橋委員","kind":"質問","question":"こういった形で議案として出されたのだとすると、どれぐらいの期間でこういう計画を立てられたものなのでしょうか、お尋ねしたいです。","respondent":"今井待機児童対策担当課長","answer":"７月、貸し付けが終わった後にもし進められるのでしたら、いろいろな計画が進められるのではないかということで内部で検討してきた経過はあります。私ども、今回の当初予算の事前調査経費を実際に提案する検討の中で始めてきたものですので…","id":"exchange-022"},{"speaker":"高橋委員","kind":"意見","question":"平成２８年４月に開設しようという、私は３００人のものをつくることは賛成で、そこがわからないところなのですけれどもとの意見を述べました。","respondent":"金子子ども未来部長","answer":"まず、６月の終わりまで貸しているというところから、本来だと地質調査もそれ以降でなければできないことになるわけです。来年の４月開設に間に合うということがきちっと成立しましたので、急遽、臨時会に提案してご審議いただこうという考え方に至ったわけです。","id":"exchange-023"},{"speaker":"高橋委員","kind":"質問","question":"平成２８年４月開園に間に合うということなので、それに向けて、まだいろいろ出てくるかと思いますが、では合うように進めていってください。それを含めて全体のほかのものも含めて、もう新制度とは言わないですけれども、そちらの園についてどのような進め方をしていくのか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"ここは認定こども園という１号枠、保育の必要がない人の枠は考えずに、ここは認可保育所という形で考えているものです。今後の認定こども園の考え方ですけれども、今、品川区が進めております幼保一体施設の充実を図りながら今後の体制を考えていきたいと考えています。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大規模化と園庭のない保育園ということでは、子どもたちが日々生活をする成長の場ではいかがなものかと、改善を求めていきたいと思います。賛成いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/184577?Template=document&Id=4852#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":21934,"voices":65}},{"id":"h27-20150527-5","meetingId":"h27-cm05","date":"2015年5月27日","dateIso":"2015-05-27","committee":"総務委員会","time":"午前１０時００分～午前１０時４８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"３月３１日ぎりぎりということですけれども、そうなった背景や要因について伺いたいと思います。３月３１日ぎりぎりになったその背景や要因、経済的情勢を踏まえてとはどういうことか、そこをご説明ほしいと求めました。","respondent":"黒田税務課長","answer":"平成２７年度の税制改正の検討をそのときにされていたわけですが、１年見送ったほうがいいだろうというような議論があったと報道で聞いております。この法律自体が成立したのが３月３１日ということで…","id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"１年見送りの内容については、十分わかります。総額で平成２８年度以降の額と、区全体でどのくらいの差額というのでしょうか、大まかでつかんでいるのはどのような感じなのかを説明を求めました。","respondent":"黒田税務課長","answer":"台数としまして全部で２万４,３５０台、金額としましては２,８１２万円余の金額が、延期になったという意味ではこの分が減収になったものです。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"わかりました。細かいことですけれども教えてもらいたいのは、車種区分で「原付」と書いてありますけれども、表示はこのような仕方なのか尋ねました。","respondent":"黒田税務課長","answer":"５０ｃｃを超えまして９０ｃｃ以下ですと黄色いナンバー、９０ｃｃを超えまして１２５ｃｃ以下ですとピンクのナンバー、色が定められておりましてこういった区分になっているものです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"現実論はどうなのですか。やはり消費が落ち込んでいるという認識で捉えていいのでしょうか、それによって今回見送ったというようなことが中身なのか尋ねました。","respondent":"黒田税務課長","answer":"６６０ｃｃですが、グリーン課税と申しましょうか、そういった意味では税制としての体系を考えていくことが国のほうで検討されているところです。１年見送られたのは、二輪については１年遅らせるという意味では…","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"区民の消費の動向やそういうものの影響も大きな要因だったのですか。それについて先ほどお聞きしたのですが、どうなのか尋ねました。","respondent":"黒田税務課長","answer":"バイクの免税額が１,０００円と２,０００円という形で１,０００円違うところが、今持っているバイクを１年持っているところの消費動向に影響するというのは、国のほうではさまざまな要因を検討した上で二輪については遅らせるという決定がなされたと考えているものです。","id":"exchange-005"},{"speaker":"あべ委員","kind":"意見","question":"４月１日からの条例改正ということですけれども、事務的には二度手間、三度手間になっている。それから、またつくり直しのようなことも事務的には発生すると思いますけれども、そういった直前での変更によるコストは算出されていますかとの意見を述べました。","respondent":"黒田税務課長","answer":"そこを変更するという意味では大きなコストはかかっておりませんが、大きなコストとしては発生していないと認識しておりまして、特段の集計等は行っておりません。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"何か最近どうも年度末にバタバタと成立してということが多いように感じるのですけれども、他の自治体と話は出ないのでしょうか。言われるままにバタバタ尻拭いをしているような印象を受けるのですが、いかがか尋ねました。","respondent":"黒田税務課長","answer":"関連して国税庁ですとか厚生労働省へ行っておりまして、地方にとって税制をこういうふうにしてほしいという要望を上げる活動をしております。ただ、その要望活動の中で地方として必要なものを要望していくという活動は従来もしておりますし…","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうした要望活動があるようであれば、そういったことも自治体の事務ということも念頭に置いてスケジュールを組んでいただきたいというふうなことも加えていただければと、これはご検討いただきたいということで要望とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"税制の改正ですから、直後の議会にかけるのは当然ですけれども、何らかの情報提供や連絡があってもよかったのかなという点は思います。前回の任期が４月末ですので、それは重みがありますので、その点は工夫していただけたらと要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]},{"id":"topic-02","title":"第４９号議案 平成２７年度品川区一般会計補正予算","agenda":"第４９号議案 平成２７年度品川区一般会計補正予算","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"冒頭にも、早期に開設するため急ぎたかったという事態が伺えますけれども、その経過をご説明ほしいと求めました。その辺の品川区の財政状況も伺いたいと思っていたので、平成２６年度の基金が増える見通しなのか、そこら辺の概要を伺いたいと思います。","respondent":"秋山財政課長","answer":"今回、繰越金を財源ということでは控えておりまして、財政調整基金が適当であると判断したです。現在の基金の見通しですけれども、出納閉鎖期間ですので、詳しいことはまだ出ていないというところが今言える部分です。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、何が伺いたいかというと、いつぐらいからこの検討を始めていたのか、その辺の経過をご説明いただきたいというのが１つです。この認可保育園自体には園庭はなくて、一方で中庭という形で２００m2の中庭をつくるという話を伺ったのですけれども、中庭をつくる理由と。","respondent":"秋山財政課長","answer":"そういう６月末というものがありましたので、昨年の暮れあたりからこういう検討を始めて、そういう中身になってあります。従前から総合的な待機児童対策ということで区は進めておりますので、その中で、できるものがあれば検討していくというスタンスです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"所管からはいろいろな要望があるけれども、最終的な判断もあるでしょうから、そこの中身を伺いたいと思います。臨時や暫定ではなく常設の認可保育園をぜひとも進めてほしいとは思いますけれども、また誰が判断するのか、そこも伺いたいと思います。","respondent":"柏原企画調整課長","answer":"我々企画部門であるとか総務部門、そういう情報を持っているところは、相互に連携しながらそれぞれに検討している。もちろん検討の結果だめになったものもありますし、引き続き検討というのも中にはありますけれども、まだ検討段階ですので。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回、開設の目的が待機児童の解消をしたいということで暫定的にやるわけですから、そこだけ確認させてください。そういう働きかけは今後もできないものなのか、そこを伺いたいと思いますけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"１点目、そういった中で待機児童対策をするためにはどうしたらいいのかという中での検討ということで、それはさまざまなものがあると思います。ただ、全く検討から外していることではありませんけれども…","id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"早期開設に向けて前倒しにする対応は、非常に柔軟ですばらしいと思います。プレハブですか、それとあとは建設したり買い上げたほうが、その辺の検討はどうだったのかを説明を求めました。","respondent":"秋山財政課長","answer":"耐用年数も３０年以上はもつというものにはなっておりますけれども、今回、この工法を採用したです。解体費用まで含めて１つの契約でできるのも一つの利点ですから、今回、リース契約をしていくです。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"５年を目途にということですけれども、どちらのほうを優先しながら判断されていくのか、そこのところをお伺いしたいのですが。","respondent":"秋山財政課長","answer":"先ほど企画調整課長もお話しさせていただいたとおり、大きな判断の割合を占めているとは考えます。そのどちらか二者択一ではないのではないかとは考えておりますし、その辺を勘案して５年先にどういう状況かということで判断するです。","id":"exchange-015"},{"speaker":"あべ委員","kind":"確認","question":"イメージとしては５年間開園をして、最後の年度で解体するところまでという理解でよろしいでしょうか、これの確認です。ということは、全体を月割りすると１カ月分が１,０００万円になるという計算でよろしいのでしょうか、ということをまず確認させてください。","respondent":"秋山財政課長","answer":"１カ月１,０００万円で、今の想定では６２カ月という形で、総額で６億２,０００万円という形になってあります。１カ月１,０００万円という、そういう計算です。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"延長された場合は、これは月１,０００万円でいくのですか。５年間を超えていくと、月額は下がって当然だと思いますが、その辺は契約の中でどのような形なのか尋ねました。","respondent":"秋山財政課長","answer":"ほかのリース物件の例によると、大体半額ぐらいにはなるのではないかと。いろいろな使い勝手ですとか、いろいろリース会社によって違いますけれども、なるのではないかという想定はしております。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"では、５年間を過ぎたところで、一旦、契約更改のような形になって、その中で金額が変わっていくということでよろしいのでしょうか。でなければ、５年後以降は幾らと数字で出ているのか、何らかそういうことかと思いましたが、詳しく説明を求めました。","respondent":"立川経理課長","answer":"こちらは延長を前提として契約しているわけではございませんので、前提としましては、その時点で協議して決めていくということになろうかと考えているところです。","id":"exchange-018"},{"speaker":"あべ委員","kind":"確認","question":"何か特別なことがない限り５年で閉じるというぐらいなイメージでの柔軟性と考えていいのかと、受けとりましたが、確認させてください。可能性としては、例えば予備費ですとか何か幾つかの可能性があった中でこれを選んだということでしたら、その選んだ決め手も一緒に説明を求めました。","respondent":"秋山財政課長","answer":"契約上５年間ということは、先ほどからご説明させていただいたように、その時点でどういう状況なのかによっては延長もあり得るという考えです。通常、繰越金も第３回定例会の１０月の補正などですと、年度間の財源の調整用の財調基金を選んだというのが理由です。","id":"exchange-019"},{"speaker":"中塚委員","kind":"意見","question":"保育園待機児童問題が深刻な中、臨時で暫定ではあるけれども、認可保育園を増設することは歓迎します。５年限定でなく、また、根本的には認可保育園の増設をさらにしっかり進めていくことが大事だということを指摘して賛成ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"あべ委員","kind":"意見","question":"それから、品川区内最大の保育園となりますので、質の確保、運営面での配慮というものをぜひお願いしたいということ。初の暫定保育園でもあります、その面でも公募者等々に問題や不利益が生じないようにということをぜひ留意していただいた上で賛成をいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858739?Template=document&Id=2014#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":14655,"voices":64}},{"id":"h27-20150527-10","meetingId":"h27-cm05","date":"2015年5月27日","dateIso":"2015-05-27","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993740?Template=document&Id=5142#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":1348,"voices":11}},{"id":"h27-20150608-6","meetingId":"h27-cm06","date":"2015年6月8日","dateIso":"2015-06-08","committee":"区民委員会","time":"午後 １時００分～午後 ３時３３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"南委員","kind":"提案","question":"うちのところは確認できていないのですけれども、今までみんなで融通し合って、古いものは自分たちでもちろんはがすのが前提ですね。私は急ぐべきではないということをぜひ言っていただきたいと思っているのが一つと、個人の１２桁の番号はもちろんですけれども…","respondent":"久保田地域活動課長、山崎商業・ものづくり課長、立木産業活性化担当課長、井浦戸籍住民課長","answer":"１点目のふれあい掲示板についてですが、ふれあい掲示板は今建替え計画をやってありますが、これは各地域からの要望に基づいて建替えているものです… ３万部つくっておりまして、区内各企業数が大体統計上２万２,０００カ所なのですけれども、きめ細かく配布をしています。それから… 就業体験事業の対象者になりますけれども、１回目は区民のみで行いました。区民の方の就業という部分で今… ２点目の情報安全につきましては、区独自の基準に基づきまして制度的、技術的…","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、工夫をしていただけないかという声ですから、これからのやり方の中で考えてほしいと求めました。一定の方たちはいらっしゃるわけですから、生活なり、そういうことになってしまえば私はこれは大問題だと思うのです。","respondent":"久保田地域活動課長","answer":"今、ふれあい掲示板のお話ですが、新しいふれあい掲示板はいわゆる旧、今まで使っていたものの下段の部分がございませんので、上の、上段の部分の中で張っていただけるように、申請等があったときには丁寧に説明をしてまいります。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"１３ページの地域支援係のところですけれども、本当に新人なもので、そんなことも知らないのかと言われたらあれなのですけれども、区政協力委員というのは若い方はいらっしゃるのか尋ねました。","respondent":"久保田地域活動課長","answer":"区政協力委員ですが、町会・自治会長に委嘱をしているものですので、町会・自治会長の年齢に応じたものです。町会・自治会長の平均年齢が、平均７２歳ぐらいということになってありますので、そういう方々で構成されているというものです。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"では、この区民の要望等を正確に把握して区政に反映させることとかも見て、この目的が、若い方の声というのはなかなか通りにくいということか尋ねました。","respondent":"久保田地域活動課長","answer":"区にこういう機会を通して直接物を言いたいということもありますので、その中では若い世代の方の意見等も十分に踏まえた上で、区政協力委員会のほうに出されたと私どもは認識しています。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"２６ページの3)ですけれども、コンビニなどにある有害図書についてですけれども、これは陳列をきちんとしているとかいうことですよね。ただ、高校とか、学校が近いコンビニでも普通に並んでいるものとか、それは言えるのですか、ここに並べないでくださいとか、そういうことは。","respondent":"久保田地域活動課長","answer":"そういったものを地区委員に調査していただいて、それを取りまとめまして警察署のほうに、また東京都に報告を上げてあります。そちらのほうから警察や、また、直接的に地区委員が指導しているものではございません。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"要望ですけれども、小学生とかもそういうものを見ていたりするので、なるべく違う場所に置いてほしいと思うのです。そういう要望をもしも出せたら、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"組織改正についてお伺いしたいのですけれども、課長たちという形になっていて、今回４月の改正で２つになったわけですね。４月の組織改正のときに初めて見た役職で、初めてその役職を見たのですけれども、それは何か尋ねました。","respondent":"安藤文化スポーツ振興部長、小川オリンピック・パラリンピック準備課長","answer":"最初の３点について私のほうからお答えします。２０２０年以降も引き続き、継続していくと、現在やっていくところです。 区といたしましては、オリンピック・パラリンピックに向けての組織については、素早い対応をしてまいりました。そちらで庁内全庁的にオリンピック・パラリンピックに向けてはいろいろ取り組んでいくという覚悟を区としてお示しした組織…","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"これもこの間伺った区民の方は団体だったのですけれども、５館のうちの３館あればいいのですけれども、きゅりあんはそこから除いていますので。これからの問題として、これから多様な区民要求に合うような施設建設についてはどういうふうに考えておられるのかをこの際伺いたいと思いました。","respondent":"間部文化観光課長","answer":"今のところは既存の特色を活かして、区内にこれだけの施設がありますので、その中で対応していただくのが一番なのかと思っています。ただ、シルバーセンターについても多世代の利用ということも今検討されていますので、またその節に深く対応していきたいと考えています。","id":"exchange-008"}]},{"id":"topic-02","title":"少年少女スポーツ普及支援事業助成","agenda":"少年少女スポーツ普及支援事業助成","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"そういう強化もあわせて行うことが求められると思います。区のお考えを説明を求めました。","respondent":"池田スポーツ推進課長","answer":"本来の目的としましては少年少女スポーツ団体への支援ということになっておりますので、今ここで２０２０年で終わるということではなく。今回やるということでご報告させていただきました。","id":"exchange-009"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（し）委員長","kind":"提案","question":"ご要望を聴取し、事項を本年の区民委員会のテーマに掲げ、所管事務調査および行政視察を通して具体性を深めていきたいと考えております。委員会日程等を考慮しながらできる限り審査・調査し、委員会の活性化を図っていきたいと考えておりますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/878133?Template=document&Id=2722#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":52160,"voices":91}},{"id":"h27-20150608-7","meetingId":"h27-cm06","date":"2015年6月8日","dateIso":"2015-06-08","committee":"厚生委員会","time":"午後 １時００分～午後 ３時５０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"もしかしたら多くの方が知らないのではないかということがありますので、この見解をお聞きしたい。この影響を受ける人数と、変わることによって、これからどうなっていくのかということをお聞きしたいと思います。","respondent":"伊東生活福祉課長","answer":"そうでなければ、今で言う生活困窮者自立支援法のほうでの支援を視野に入れつつ、対応しておるところです。４人ということで、説明は省略しますけれども、金額ベースでは若干下がっているというようなことです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"それから、先日、東京では震度４の地震がありました。そういったときの受け入れの要望がありまして、今、どういうふうに考えていらっしゃるかをお聞きしたいと思います。","respondent":"永尾高齢者福祉課長、大串福祉計画課長、中山障害者福祉課長","answer":"紙おむつの現金支給の周知ですけれども、実際、４月から始めまして、従来使っている方については、当然、社会福祉法人のほうでやっております。… ４月、５月の実績、やはり昨年に比べるとかなり増えてきているといったところです。 先だっての地震は、一時的にエレベーターの停止はございましたが、区内に大きな被害があったものではございませんでした。…","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、一人の障害者の方が家に帰れなくて、野宿になるのではないかみたいな事態にもなりましたが、一応、知り合いの方のうちに上げてもらって何とかなったということだったのですけれども、これからこういったこともあると思いますので、ぜひこれも考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"意見","question":"国も２０２５年を見据えて、やはりあと１０年かかっていくのだろうというのは、私はいるのです。四年以内にはその部分はやっていくべきだろうと思っているのですけれども、感覚的なものは、それでいいのかどうかということだけ聞きたいと思いますとの意見を述べました。","respondent":"榎本（圭）福祉部長","answer":"特に今、医療と介護の部分に焦点が当たっていますけれども、それも含めながら進めていきたいと考えています。実際上、２０２５年は第九期になるのですけれども、なるべく早くそういうものに向けて形をつくっていきたいと考えております。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"８０人以下にすべきだという、この態勢に対しては、その考え方についてひとつお聞かせほしいと求めました。全国が１７.１‰ということで、なぜ品川区がこれだけ低いという状況になっているのか、お聞かせほしいと求めました。","respondent":"松山高齢者地域支援課長、伊東生活福祉課長","answer":"総合事業の要支援者の考え方ですけれども、要支援者については、高齢者地域支援課で行ってまいります。 そのほかに高齢者世帯自立支援員という、非常勤ですけれども、そちらは主に高齢世帯で比較的安定している方を見ていただく形で対応しております。そういうところは入っていないということで、２３区で考えますと…","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"多い方は、一人で１００名を超えている方もいらっしゃるとお聞きしています。ここから要介護のほうに移っていく方が多いと思いますので、そこら辺の連携はよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"厚生委員会所管の施設で避暑シェルターになるところは、あるのかどうなのか。たしか、避暑シェルターになると、たしか水分の補給もできるようになると思うのですが、その箇所数だけ説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"シルバーセンターが、その避暑シェルターとしての役目を果たしております。","id":"exchange-007"},{"speaker":"いながわ委員","kind":"意見","question":"シルバーセンターは何カ所かあると思うのですけれども、違う所管の施設で、シェルターと書いた旗がその施設の中に入ってはためいていたのです。ここはシェルターになっていると利用される方がいらっしゃると思いますので、ぜひ、そういうところも気をつけてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"私も、先ほど、質問させていただいたけれども、地域包括ケアは、ほんとうに今やっていくべきだろうと思っています。こういうところから入りながら、１年間やっていけることはたくさんあると思うので、積極的に取り上げてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/841532?Template=document&Id=3416#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":52829,"voices":85}},{"id":"h27-20150608-8","meetingId":"h27-cm06","date":"2015年6月8日","dateIso":"2015-06-08","committee":"建設委員会","time":"午後 １時００分～午後 ４時３３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"の１の幹部職員紹介","agenda":"の１の幹部職員紹介","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"１７年目にして初めて建設委員会をやります。どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"意見","question":"日本共産党品川区議団の安藤たい作と申します。どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"つる委員","kind":"質問","question":"よろしくお願いします。私も委員としては建設委員会は初めてですので、教えていただきながら。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"筒井委員","kind":"意見","question":"私も全くの新人です。そして品川区の発展のために微力ながらしっかりと寄与してまいりたいと思いますので、今年１年、何とぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"}]},{"id":"topic-02","title":"の２の事務事業概要","agenda":"の２の事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"基本姿勢に関わって幾つかお伺いしたいのですけれども、ぱっと見ると、そこに道路整備等は入っていないのです。税金と労力は国が示すような耐震化の推進と感震ブレーカーに費やすべきだと私は思っていますが、区の考えはいかがか尋ねました。","respondent":"中村都市計画課長","answer":"特定整備路線のことに関連して、今、防災・減災計画、これは国で広域的な計画ということで定めて推進していくという性質のものと認識しています。今回、特定整備路線の整備を行って、特定整備路線については引き続き進めてまいるという計画で区では考えてあります。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"これについてどう考えるかということをお伺いしたので、それをお答えいただきたいのと、この２つの住宅耐震化は２０２０年までに９５％やると。感震ブレーカー設置率も２５％を、２０２０年までにやるという目標は掲げられているので、どういうふうに取り組もうと考えているのかお伺いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区全体の防災計画に関わって、国がこういう方針を出しているので、そこに対する区の考え方はすごく重要な、防災全体を考える上ですごく大切な点だと思いますので、ぜひそちらは答弁いただきたいのですけれども。","respondent":"藤田都市環境部長","answer":"そういう中で、品川区、東京都２３区、木密地域と、そういうようなエリアの中でのそれぞれの具体的な課題というものがあるのかと考えています。これまでもそれらの施策を重ね合わせて進めることが総合的な防災対策につながると考えていますので、これまで同様、そういった考えで…","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"そこで、用途地域の合理的な配置についての区の考え方は何かあるのでしょうか。区としては用途地域をこのように配置していくという基本的な考えがあるのであれば、伺いたいと思います。","respondent":"中村都市計画課長","answer":"そういったところの近傍に幹線道路等が通行いたしますと、あるいは土地の高度利用、有効利用というような側面もまたあります。建物の高さや、あるいは建物の幅、そういったさまざまな手法を総合的に組み合わせて今の用途地域の配置がなされているものです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"この用途地域の変更の要望などが地域から上がった場合は、用途地域を区が主体的に変更するときはどういうときなのかをお伺いしたいのが。大変重要だと思いますけれども、「住み続けたいまちしながわ」という基本理念と公営住宅の建設との関係についての区の考えをあわせてお伺いします。","respondent":"中村都市計画課長、矢木住宅担当課長","answer":"用途地域の変更等についてですが、こちら、例えば区のまちづくりそれぞれ、品川区内で地域によってまちづくりの方針が異なっております。その地域一帯で住環境等の確保、区の判断によって… 公営住宅の増設につきましては、近年の空き家等の実態調査でも明らかなとおり、空き家の総数が増加している状況にあります。耐震改修や長寿命化等々の計画で、なるべく住み続けられるような計画を到達別に考えているものですので…","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"住み続けたいと品川区で思っても、家賃が安いところがないと、出ていかざるを得なくなるのではないかと思います。課長が言ったような答弁だけでは、そうした方々は区外に出ていかなければならなくなるように思ってしまうのですが、それはどうなのか尋ねました。","respondent":"矢木住宅担当課長","answer":"そういった住宅の施策を、今までも相談等でやってありますし、今後とも検討してまいりたいと思います。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"単身者等もそうだと思いますが、何らかの家賃助成とかそういったことも含めて検討していく必要があるのではないかと私は思いますので、ご意見します。採用の目的と経緯をもう少しお伺いしたいのですが、まずお伺いしたいのは、あわせてまずお伺いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"それでこれからやっていくわけですから。〔「今、個人の問題と今の話は違う」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"どうして、どういった役割をこれから果たしていただけるのかということはすごく大事な点だと思うので、そういった意味で聞いたのです。〔「以前は関係ないじゃない」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区のほうが自衛隊にぜひ防災政策を充実させるために来てほしいと要請したのか、それとも自衛隊から品川区に要請したのかをお伺いしたいのと、部長がこれからどのような業務で活躍するのかをお伺いしたいです。","respondent":"松代防災まちづくり部長","answer":"消防の連携は区民の身近なところでの火災に対する対応というところでは、これは大きな成果としてやっていただいているところです。もしくは全部を挙げて対応した経験がないような事象、そういったことで、この４月から着任していただいているものです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"それをあえて消防庁ではなく、自衛隊の方から来ていただいたというのは、何か理由があるのかと思ってしまうのです。ですから、それに対してどうでしょうかということが１つと、区国民保護計画の充実ということなのでしょうかということをお伺いします。","respondent":"松代防災まちづくり部長","answer":"我々行政が一体となって取り組むべき方向を、震災対策特別委員会等で３年間議論いただいた内容も含めまして、当たっているところです。そういったことの計画の中身を一歩一歩しっかりと進めていく上において、陸上自衛隊の幹部を招聘し、こういったものを考えてきたところです。","id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"３つだけ確認をさせてください。３点目は、これは路線バスの運用というところまでの話し合いはされているのか、されていないのかというところを説明を求めました。","respondent":"中村都市計画課長、溝口都市開発課長","answer":"補助２８号線、用地をお譲りいただくための権利関係の説明であります用地説明会という最後の説明会も、東京都としまして終わっているところです。この中で補助２９号線、豊町のところが１％というような形で… そういった中では、できるだけ早く今後の跡地での方針については求めていきたいと考えているものです。路線バスについては、その１便のみを今のところ計画しているものです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"計‐９ページを見ると、なるべく計画どおりにいきたいところではあるのでしょうが、これだけお聞きします。ＪＲ東日本の今の考え方はどういう状況なのか、なかなか相手があるものですから、それだけお聞きします。","respondent":"中村都市計画課長、溝口都市開発課長","answer":"特定整備路線の進捗率ですけれども、まことに申し訳ございません、東京都の進捗率、今年度どこまでいくかは、予測が非常に難しいところです。並行して各地域を進めているですので、また… 広町社宅跡地のＪＲ東日本の考え方です。早い時期に皆様に今後の跡地利用についてお話しできるように、ＪＲ東日本と引き続き協議を続けていきたいと考えているところです。","id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"は委員会の中でいろいろと話し合っていきたいと思いますが、先ほどから、これからの流れ方ですけれども、委員長から仕切りをしていただきました。建設委員会で話をしなければいけないことについては、しっかりと仕切りをしていただいて…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]},{"id":"topic-03","title":"の「東京における都市計画道路の整備方針（第四次事業化計画）中間のまとめ」の公表","agenda":"の「東京における都市計画道路の整備方針（第四次事業化計画）中間のまとめ」の公表","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ですから、やらないのかお伺いしたいということと、都から意見照会が来ると思います。３点目として、実際に今、東京都と優先整備路線について区は話し合いをしているのかどうかお伺いします。","respondent":"中村都市計画課長","answer":"パブリックコメントの予定ですけれども、具体的な整備路線の選定に入っていくですので、パブリックコメントが選定するための基礎となるものです。今後、連携ということは情報交換あるいは検討を行いながら、最後のまとめを行っていくスケジュールです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"最終的に都から意見照会があるときは、大体もう決まっていて、セレモニー的な要素が多いと思います。ですから、今の時点で区が優先整備路線に入れたいと思っている路線はどこなのかを聞かせていただきたいということです。","respondent":"中村都市計画課長","answer":"現在までに第三次優先整備路線ということで計画を進めておりましたけれども、まさにこれからこの１５項目、あるいは６項目につきまして検証項目を踏まえて検討していくですので、現在、区でも具体的な場所が決まっているということではございません。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"１日当たり６,０００台を設定して、これが６,０００台以上あれば、これは普通なのだとなっています。ですから、どういう考えをこの「中間のまとめ」をつくるに当たって東京都に意見を言ってきたのか、そこら辺をお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"その他におきましては、例えば道路閉塞ですとか、あるいは緊急物資などの災害時の輸送といったところも重点になると考えております。にぎわいが確保できる、そういったまちをつくるという目標が、品川区内の地域の特性としての目標であると考えて東京都に向き合ってあります。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"関西等を見比べますと、整備方針自体が道路を廃止させないといいますか、つくっていくというような中身になっていると思います。それは、品川区としては、この整備方針を必要ではない道路が廃止になるような具体的中身になっていると思っているのか尋ねました。","respondent":"中村都市計画課長、藤田都市環境部長","answer":"この検証項目につきましては、適切であると認識しております。品川区におきましては、他区の判断等に左右されることはなく、品川区は品川区でしっかりと検証してまいりたいと考えております。 そういうことで私どもも、今回、都としてパブリックコメントを実施するというような形でやってきてあります。今後の予定のところの真ん中の大きな、検討した上で、選定の考え方をまとめというふうに書かれてあります。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"計１００％になっていないわけですから、あと４０％が未着手という形になりますけれども、指定される道路は４０％を含めた形で選定されるのか。都市開発道路という選定と、プラス特定整備路線が出てきているわけですから、それらの優先順位はどうなっているのかということを説明を求めました。","respondent":"中村都市計画課長","answer":"今、特定整備路線のほうは平成３２年までに目標年次を定めて東京都としても事業を進めているものですので、平成３２年までの完成目標です。その他の都市計画道路につきまして、優先整備路線としての位置づけを行っている、特定整備路線は別に期限として定めているものです。","id":"exchange-023"},{"speaker":"西本委員","kind":"提案","question":"その数が何本あるのでしょうかということと、品川区のことは品川区が一番知っているというか、存じ上げているところだと思います。その中でいろいろ提案しているのだろうと思いますが、それとも要望がきっちりと言えているのかどうか、そこをお聞きしたいのですがとの意見を述べました。","respondent":"中村都市計画課長","answer":"これは事業をそのまま継続していくというものですので、こういった路線が何本あるかといいますと、１２本あります。区ではこの検証項目を踏まえて検討した後に、また検討会等が何回か開催が予定される中でしっかりと意見を述べていくということを考えてあります。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"この１２本の中で、あと土地開発とか、まちづくり全体にかかわってくると思います。その周りをどういう状況にしていったらいいか、そこをトータル的に考えていかないと、その辺のリンクの仕方はどういう考え方なのでしょうか伺います。","respondent":"中村都市計画課長","answer":"生活や商店街ですとか、影響について少なくなるような形で周知を行いながら進めていく、そういった形で進めていかなければならないと考えています。そういった中では、十分に説明等において理解を深めながら進めていくという姿勢です。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"結局、土地をとられてしまうわけですから、そうすると、上に高くしていくのかとか、まち全体をどういうまちにしていくのか。その考え方は区としてどういうふうに考えてもっていこうとしているのか尋ねました。","respondent":"中村都市計画課長、藤田都市環境部長","answer":"着々と密集事業、あるいは避難道路機能強化等、防災に対するまちづくりのハードウエアの整備を進めてきているところです。この都市計画道路の事業、こういったものが現在のところうまくリンクさせて、そして進んでいるという認識です。 再開発も含めたまちづくりの中で必要なものも、その優先整備路線の１つの項目に入れてきておりますし、防災の評価により入れてきたところもあります。さまざまな観点から今後検証して…","id":"exchange-026"},{"speaker":"筒井委員","kind":"意見","question":"計画決定から４５年以上たっているところもありまして、そうした状況の中、またさらに今後１０年間でまた検討を加えるというのは、一体どういう根拠なのか、なぜ１０年間になるのかという根拠を示してほしいと求めました。","respondent":"中村都市計画課長","answer":"こういったものを検討条件として加えていく中では、検討を引き続き重ねて、四次の次は五次というような形の考え方でいく。ここでは将来、五次を定めるとは示してはおりませんけれども、１０年単位ですので、引き続き検討がなされていくと考えております。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"いつまで、私としては、逆にスピード感を持って決定を実行するのかどうかを早目に区としてもお願いをしたいということを考えております。その点、区としてはどういったお考えなのかをお聞かせほしいと求めました。","respondent":"中村都市計画課長、松代防災まちづくり部長","answer":"ただ、いつ事業が始まるのか、その辺はやはり示す必要があるかと考えています。そういった考え方で計画道路の事業が進められていくよう、区としても東京都にはそういう意見を申し出て述べていきたいと考えています。 実施しないということは決してあり得ないと思っていますし、これは最後まで完成をしていかなければいけないものと考えています。そういった意味では、いまだまだ道半ばですので、そういったものはしっかり今後も実施していきたい…","id":"exchange-028"}]},{"id":"topic-04","title":"の区民住宅（空き室）入居予定者登録募集","agenda":"の区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"現状での空き室がどのぐらいあるのかをまず説明を求めました。","respondent":"矢木住宅担当課長","answer":"ご質問の件ですが、実は空き室の入居予定者募集は、空き室があるかないかではなく、登録して、それで空きがあればすぐ入れるし、なければ登録順で入れるようなシステムになってあります。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それは十分に理解しており、現状で空きがあるかないかということの確認です。","respondent":"矢木住宅担当課長","answer":"現状の空き室につきましては、トータルで１００戸弱の空きがあります。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"状況はわかりましたけれども、長期に空いている部屋がありますが、そこら辺をどう埋めていくのかという、そちらを確認したかったわけです。今回のは募集だから、内容は違うといえば違うけれども、そこら辺をもう一回、お答えほしいと求めました。","respondent":"矢木住宅担当課長","answer":"こちらは、指定管理者を通じまして申し込みの募集をしていますが、一層の募集の勧誘をいたしますとともに、今後の推移を見まして、また空き室の解消に向けて、家賃等々を含めまして検討が必要かとは考えております。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"なるべくその辺も空いたまま、結局は区の負担として出ている、その辺は委員会が初めてで状況はわかりませんので、ぜひお考えいただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"西本委員","kind":"意見","question":"どういう対策がオーナーと、そことはどういう話し合いになっているのか、それを比較して今後どういう対策をとられていくのかを聞きたいと思いますとの意見を述べました。","respondent":"矢木住宅担当課長","answer":"ただし、２０年の借上期間が終了に近づいてきているところが多い中で、私どもも苦慮しています。なかなかそれとも均衡上の中ではそれほど乖離はない中で、あとは設備等々に検討せざるを得ない段階に来ているのかとは考えてあります。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"２０年近く、それなりの期間があると思いますけれども、一番空きが多い区民住宅であと何年ぐらいあるのかがわかれば教えてください。ですので、なかなか選別はできにくいと思いますが、そこの回避をするための方策は何か考えられているのかを聞きたいと思います。","respondent":"矢木住宅担当課長","answer":"その中では、滞納２カ月ないし３カ月程度では使用者の方をお呼びして生活状況を確認いたしまして、そういう場合は早急に退去を勧めていく。入居者にとっても払えない状況で入られ続けていらっしゃるのはいいことではないと思いますので、早期の解決について種々の努力をしていま…","id":"exchange-034"},{"speaker":"西本委員","kind":"意見","question":"一番長いところで今年度２０年で出るということですが、しかしながら、税金がかなり使われている現状もあります。２０年で切れるということですが、その後については、それぞれのオーナーとは話し合いがどれだけ進んでいるのかを聞きたいと思いますとの意見を述べました。","respondent":"矢木住宅担当課長","answer":"もう一点、オーナーとの話し合いですが、返還時にはおおむね２年前、１年前、半年前ということでそれぞれ通知を申し上げます。遅くとも半年程度をめどにオーナーには１年前から話し合いを本格的に始めるのですが、家賃、その辺の条件を提示していただくようにお願いしています。","id":"exchange-035"}]},{"id":"topic-05","title":"の耐震診断が実施されない特定緊急輸送道路沿道建築物の公表","agenda":"の耐震診断が実施されない特定緊急輸送道路沿道建築物の公表","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この公表期間を過ぎたらどうなるのかをお伺いしたいのと、あと診断済みが１７３件ということですけれども、補強に実際この１７３件の診断から進んだ件数は何件になるのか尋ねました。","respondent":"鈴木建築課長","answer":"それと、耐震診断済みの中で補強工事を行った件数ですが、補強工事の費用につきましても支援事業を設けて実施しております。今、手元にはございませんが、東京都の支援事業を利用して補強工事を行った件数は１１件です。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"都の新事業を受けたのが１１件だということですが、すみません、その診断の結果の内訳をお伺いしたいのが１つでした。そういった点で、マンションで区の耐震補強を進める上で課題になっている点はどこなのかをお聞きします。","respondent":"鈴木建築課長","answer":"先ほど耐震診断未診断の建物を私は２１棟と申し上げましたけれども、補強工事には費用等がかかる、そういった２１棟の中には多うあります。都と連携しまして耐震補強工事につきましても相当手厚く支援事業を行っておりますし、大分緩和されたというところで、課題とすれば。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"診断対象建築物が２０５棟で、診断済みが１７３棟、未診断の課題はよくわかりました。診断済みの１７３棟のところで、耐震が必要だとなったところはどれぐらいあるのか、その内訳も伺いたいと思って質問しました。","respondent":"鈴木建築課長","answer":"申し訳ございません、今、診断結果ＮＧ、耐震性がないとなった建物の数字は手元にはございませんけれども、いろいろ担当、あるいは個々のやりとりを聞いていますと、旧耐震、耐震性がないという結果になる確率は非常に多いと認識しています。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"耐震の診断をしない中で、公表はされるけれども、これから区のほうもいろいろ折衝していく中で、どうしても耐震にならなかったときにどうするのか。そういう場合には、持ち主はどういう状況か今はわからないけれども、耐震しないでそのまま残ったときにはどうするか、後の問題を伺います。","respondent":"鈴木建築課長","answer":"これで公表になって３月３１日を過ぎれば、診断費用の助成制度がある今年度中にやっていただくような働きかけをしていきたい。必ずしも設計をして補強工事と進んでいかなくても、除却費の制度もありますので、そういったところを丁寧に説明していきたいと考えています。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"もう少し効力のある方法、処置をとるべきだろうと思いますが、あとは理解を求めていく。結局、公表しても不利益を被るわけでもないし、余り意味がないような気がするのですけれども、その辺の考え方というか、それはありますか尋ねました。","respondent":"鈴木建築課長","answer":"ちょっと説明が、実は公表に当たって東京都が条例に基づく意見聴取を各所有者の方にしております。あるいはやりとりをしていくかというところは、今後、考えていかなければいけないと考えております。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"本当は話し合いできっちりと済ませていただきたいとは思いますが、理由を聞くと、悪質といえば悪質。今後その形でされていくわけですから、何か時期的なところで東京都と打ち合わせ、すり合わせをしているのか尋ねました。","respondent":"鈴木建築課長、藤田都市環境部長","answer":"周知をしてきたというところで、現段階で東京都と直接そういったところも視野に入れて行っていくというような具体的なやりとりはしておりません。その上でどう所有者の方が対応していただけるか、東京都からも聞いておりませんし… 十数年とかそういう単位の中ではまた新たに建て替えの需要が出てくるようなことも恐らく考えながら今後の事業展開について考えているのだと思います。ほかのさまざまな建て替えを促進するような施策とあわせて進めることが…","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"多分、意思なしという１３棟は特にそうですが、どういう意図があってということがきっちりと認識されていない部分もあると思います。将来にわたってどうしていきたいのかと、まず認識不足だと私は思いますので、その辺を考慮しながら進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"確認","question":"これは私の確認ですけれども、東京都もしくは品川区が耐震診断の助成ができているのかどうか、それを確認したいと思います。","respondent":"鈴木建築課長","answer":"特定緊急輸送道路対象の建物につきましては、東京都の事業として区でも事業におきまして連携をして実施しております。２１棟につきましても、対象とすれば全て対象となっています。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"受けたくないというのは１３棟、どういった事情があるにせよ、かなり意思がかたいと思います。ですから、広報しながわにこういった未診断の建築物がありますと載せるか、そのあたりを当局はどう考えているのか尋ねました。","respondent":"鈴木建築課長","answer":"委員ご指摘のとおり、個別にヒアリング、聞き取りをしておりますと、診断未実施公表についても、「いいですよ」と言う方も確かにいらっしゃいます。２３区全体、できるだけ気持ちを変えていただくために、さらに積極的な働きかけを行っていきたいです。","id":"exchange-044"},{"speaker":"つる委員","kind":"質問","question":"２０年近くの間の中で何らかの手立てを尽くしていただいていたから、昭和５６年以前にそのものが建てられたのだけれども大丈夫だったという考え方で、１７３引く１６４の棟数はその中に入っているということか尋ねました。","respondent":"鈴木建築課長","answer":"基本的には、補強せずにそのまま診断をしてオーケーだったと。壁が多かったり、配置がよかったりというところで、診断した結果オーケーだというところがその数字です。","id":"exchange-045"}]},{"id":"topic-06","title":"の平成２７年度品川区電力節減方針","agenda":"の平成２７年度品川区電力節減方針","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"環境課からのご説明だったのですけれども、同時に環境課としては地球温暖化防止に取り組んでいるというご説明があったのですが、節電の目的ですけれども、温暖化防止という目的も入っているのか尋ねました。","respondent":"三ツ橋環境課長","answer":"東日本大震災を受けて電力の供給不足が考えられますため、数値の目標を掲げ、電力節減に取り組んでおります。今年度も引き続き実施しております。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"品川区が使う電力を既存の電力に依存することなく、新たに地産地消の自然エネルギーの普及も進めていく必要があるのではないかと私は思っています。そういう自然エネルギーの普及についてもセットで目標ですとか方針を持つという意味だと思いますが、区はどのようにお考えか尋ねました。","respondent":"三ツ橋環境課長","answer":"地産地消の考え方ですが、先ほど事務事業概要の中でもご説明しましたように、太陽光発電設置助成などを進めております。引き続きこの考えに基づいて実施してまいります。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"こういった節電目標はアクセス目標で、ぜひ自然エネルギーの普及についてもこうした方針といいますか、目標を持って取り組む必要があると思います。そういった目標を持つ考えはないのか尋ねました。","respondent":"三ツ橋環境課長、藤田都市環境部長","answer":"自然エネルギーについての考え方は、今現在、非常に流動的なこともあります。実際に太陽光発電設置助成は区として行っておりますけれども、ほかのものを考えていくに当たり、引き続き考えてまいりたいと考えています。 そういう中でこれらのことをなかなか明確に明記していくことは難しいと考えています。温暖化対策についてはしっかりと取り組んでいく考えですので、そういった中でしっかりと対策をとっていきたいと考えています。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"ただ、部署によってはできないです、福祉施設の管轄になっているところは、当然、１５％は無理かもしれない。いろいろな部署の中での１５％を引き出すという形に目標を掲げていくのか、考えはいかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"ほとんどのところが１５％となっておりますけれども、１５％までは目標だけれども、なかなか難しいところはあります。ただし、基本的には、皆さん、１５％というように考えていただいております。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"ですから、そういうことを考えると、区民サービスは低下はしています。今年はそれとはまた違う方向で、多少これぐらいはいいのかなというようにしていくのか、その辺の考え方はどうか尋ねました。","respondent":"藤田都市環境部長","answer":"現状としては、平成２２年度比の１５％はここ数年変わっていない数値ですので、当時の一生懸命頑張ったときは、たしか２５％だったのです。その時々では施設の中で臨機応変に対応できるようなことも考えていかなければいけないと思いますので…","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"区民もわかっていますから、そうしたら、「今こういう状況で１５％を目指しています。平成２３年度のときには、そこはお願いしたいと思いますが、いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"今回、区民へのご協力のお願いですが、実際に暑い現状もございまして、非常に皆様に影響がある可能性もありますので、特にご協力というお願いはしていく方向なのかと思いますので、そのあたりは検討させていただきたいと思いますので、よろしくお願いいたします。","id":"exchange-051"},{"speaker":"筒井委員","kind":"質問","question":"小・中学校、具体的にどの施設がそういう施設になっているかを事前に区民の皆さんにお伝えするような情報公開することはお考えでしょうか。区民もそれなりの覚悟を持ってその施設内に入ることができると思いますので、そういった具体的施設の情報公開をぜひお願いしたいのですけれども。","respondent":"三ツ橋環境課長","answer":"実際に全施設に関して節電は取り組んでいただけるものです。その避暑シェルターについては、のぼりなどを掲げておりまして、もっとこちらが涼しいですというお知らせはしております。","id":"exchange-052"},{"speaker":"筒井委員","kind":"質問","question":"ということは、品川区の全公共施設がそういった状態になるという理解でよろしいのか尋ねました。","respondent":"三ツ橋環境課長","answer":"全施設に関しまして、まずは１５％を掲げている、そして、その中でも避暑シェルターというものが存在するです。","id":"exchange-053"},{"speaker":"鈴木（真）委員","kind":"確認","question":"平成２４・２５・２６年度は１５％を切っているでしょうけれども、どのぐらいの数字になっているのか。徐々に上がっているのか、それともずっと維持できているのか、その確認をお願いします。","respondent":"三ツ橋環境課長","answer":"平成２５年度につきましては、マイナス９.１％でございました。そして、昨年度、平成２６年度につきましては、マイナス１０.８％でございました。","id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"意見","question":"どうしても暑いと、先ほど区民サービス低下ということも言っていたけれども、徐々に、自然に変わっていってしまう、意識が薄れてくると思いますので、これだけやってまた呼びかけをして、皆さんの意識をもう一度戻していってもらうためにも、ぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"藤田都市環境部長","answer":"１５％ぐらいクリアしていたり、なかなか難しい施設が中規模な施設で、そういった施設は数が多いのです。絶対量的には多くなってくるので、そこが１５％を少し切るような形であると、節減方針等の周知も含めて取り組んでまいりたいと考えています。","id":"exchange-055"}]},{"id":"topic-07","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"品川区の大崎西口駅前地区を東京都の募集に対して応募した理由をお伺いしたいのと、どれだけ今後こういった手法を取り入れていこうと考えているのでしょうか、２点お伺いします。","respondent":"溝口都市開発課長","answer":"まちづくりを検討している地区がございましたので、そこのまちづくりを進めていく上で、応募させていただいたものです。そういったものを大きく３点取り上げている中で、これを今後、普及させてまちの再生を図っていきたいというのが東京都の考えだと聞いているものです。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"何かメリットみたいなことがあるのですか。その辺がわからなかったので、もう一度お伺いします。","respondent":"溝口都市開発課長","answer":"１つは事業性、再開発事業までもっていく間の合意形成をどのように進めていくのか、そういったところでの支援ができると思います。今回、モデル事業として応募し、東京都から選定されたと認識しているものです。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"その後、将来的にはそれをもとにして再開発という形の流れになっていくのか、どういう位置づけでこういうモデル事業が進められているのか。実際それをもとにして再開発という形になろうかと思いますが、それはどういう意味でもって、いくのか尋ねました。","respondent":"溝口都市開発課長","answer":"駅前にふさわしい魅力的なにぎわいのあるまちづくりをどのように進めていくのか、詳細に検討していかなければいけない時期になっております。今回はモデル事業という形で応募し、選定されたと考えていますので…","id":"exchange-058"},{"speaker":"西本委員","kind":"質問・要望","question":"ここは老朽化もありますし、何らかの形で再開発をしないといけないのだろうとは思ってはいるのですが、いい事例になると思います。せっかくいい案が出ても、それが実現されなければ絵に描いた餅になってしまうので、そのめどはどういうふうに考えられていますか。","respondent":"溝口都市開発課長","answer":"調査等をかけていきますが、当然、準備組合とも十分連携をとりながら進めていかなければいけない部分が多々あると思います。都と連携しながら、また、地域とも連携しながら事業を進めていきたいと考えているものです。","id":"exchange-059"},{"speaker":"安藤委員","kind":"確認","question":"この資料についての確認ですけれども、調査費の話が出たのですけれども、今後の予定の都の財政的支援と計画等にかかわる助言とありますけれども、都がこのモデル事業に関してどういった役割を果たすのかがよくわからなかったのですけれども、財政的支援とは具体的にはどういうことか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"西本委員","kind":"意見","question":"次回の建設委員会でということですが、この１４類型が具体的にどういうことか、そして、どういう行為なのかが、私は運転免許を持っていないのでよくわからないので、何かそういう、具体的なものがわかる資料があればわかりやすいかと思うので…","respondent":"田口交通安全担当課長","answer":"個々具体的にそういったものも準備をします。免許証のない方でもわかるような工夫をしますので、よろしくお願いいたします。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"発生した５月３０日の小笠原諸島沖地震ですけれども、首都圏を中心に１万９,０００基のエレベーターが緊急停止したということですが、品川区内でも件数でいいますと、実態がどうだったかをお伺いしたいのですが。","respondent":"鈴木防災課長","answer":"ただ、エレベーター内の閉じ込みが１件ありましたが、大井消防署がすぐ駆けつけて救出されたという報告を受けております。それ以外には一切、具体的な被害はございません。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/557041?Template=document&Id=4136#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":63285,"voices":219}},{"id":"h27-20150608-9","meetingId":"h27-cm06","date":"2015年6月8日","dateIso":"2015-06-08","committee":"文教委員会","time":"午後 １時００分～午後 ４時２５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"の１、幹部職員紹介","agenda":"の１、幹部職員紹介","exchanges":[{"speaker":"鈴木（博）委員","kind":"意見","question":"自民党・子ども未来の鈴木博です。どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"の２、事務事業概要","agenda":"の２、事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"５ページの総合教育会議、総務課事業ということなのですけれども、これのスケジュールなんかがわかれば教えてほしいと求めました。考え方を教えてほしいと求めました。","respondent":"品川庶務課長","answer":"１点目、総合教育会議ですが、スケジュールとしましては、年２回から３回ぐらいを予定しています。２点目、それから地域バランス等を考えて、改築のほうは進めていくという考え方です。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"校舎の改築のところは、ここを何とかしてほしいというような、そういったところも対応していただけるということでいいですか。お聞きいたします。","respondent":"品川庶務課長","answer":"総合教育会議について文教委員会で報告するかという点ですが、基本的には議事録等を公開する予定ですので、文教委員会で報告する考えはございません。やはり総合バランスを考えなければいけませんので、学校の意見は意見としてそれは聞きますが…","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"バランスというところもあるとは思うのですが、実態把握をしながら、早急にすべきところはしてほしいと求めました。平成２５年度から減ってきてしまったのですが、平成２７年度はどうなるかをお伺いしたいと思います。","respondent":"野呂瀬学務課長","answer":"放射性物質検査ですけれども、基本的には昨年度並み。ですから、平成２７年度も平成２６年度と同じようにやっていく、こういう考えです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"確認","question":"そうしたら、確認ですけれども、年間２回、そして、ストロンチウム検査も年間１回という確認でよろしいか尋ねました。","respondent":"野呂瀬学務課長","answer":"そうすると、学校ごとになると、年間１回という。それで、セシウムのほうは毎月２回ずつやっているということですので、各学校からすると、昨年度分ですけれども、年間２回という形になります。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"４３ページの一番最初のところにはご説明があるのですけれども、その方たちがどれくらい回っていて、もう一回詳しく教えていただきたいと。それと、予算の面では、人件費はどのくらいになっていくかというのも説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"それぞれ子どもたち、児童・生徒のさまざまな現状、また課題について対応できるような仕組みを今進めているところです。巡回相談にかかる経費につきましては、４,２１６万８,０００円です。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"ごめんなさい、予算だけ聞いてしまったのですけれども、人数、ソーシャルワーカーが何人で、どれだけ学校を回っている、週に何回とか。それで、ソーシャルワーカーが何人いてどれだけ回るのか、巡回相談員は何人でどれだけ回るのかというのを、小・中学校別に教えていただけますか。","respondent":"村尾教育総合支援センター長","answer":"スクールソーシャルワーカーなのですが、実際には、ＨＥＡＲＴＳのメンバーは７名なのですが、ソーシャルワーカーについては４名です。ソーシャルワーカー４名については、また、現在は各中学校を月１回は巡回をしているという流れです。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"意見","question":"それで、スクールカウンセラー、巡回相談員が各校を回って、課題を把握してということがあるのですけれども、課題となったものというのは、学校や教職員みんなで話し合う場というのはつくられていませんかとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"もちろん各学校に行って、校長、養護教諭、また、各学校に特別支援コーディネーターという教員が１名います。は生活指導の支援についてどのような体制で現在行っているか、どのような形で子どもたちへの学習支援や生活支援ができるかということについて。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教職員の方々も結構ハードなスケジュールだということもたびたび伺っていますけれども、教えてほしいと求めました。国と都の動向がどうなっているのかということと、品川の区教委の少人数学級への、今の段階でのお考えを聞かせてほしいと求めました。","respondent":"品川庶務課長、村尾教育総合支援センター長、野呂瀬学務課長","answer":"１点目ですが、総合教育会議の報告につきましては、先ほど申しましたように、議事録等が公開されていますので、委員会等でやる考えはございません。今後… 日程等につきましては、従来どおり、教育委員会の定例会または臨時会等を踏まえながら、それぞれ順次進めていくところです。… 学級編制の考え方ですけれども、先ほど申し上げたとおり、国の法律では１学年３５人、これは決まっていますので、守っていかなければいけない。…","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ質疑の時間を設けていただきたい。でないと、どこで議論したらいいのかわからないので、ぜひそこは再考してほしいと求めましたが、もう一度答えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"意見","question":"おおよそはわかっておるつもりなのですけれども、また改めてというと、どこの時点になるのかと。どういう位置づけにあるのかを把握しながら、意見を言っていかなくてはいけないと思っているので、十分それはわかっているつもりなのでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"国では１年生、ぜひ一日も早く全学年に広がっていくような方向性を持ってほしいと求めましたので、よろしくお願いいたします。ぜひ事業者も載せていただきたいし、傾向なんかも知っていきたいと思うので、その辺の報告もぜひお願いしたいと思いますが、いかがか尋ねました。","respondent":"木村品川図書館長","answer":"今、おっしゃられた、実際の４月以降の中身でありますとか、事業者のことでありますとか、ご報告をしてまいりたいと考えていますので、よろしくお願いいたします。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"どこかで指定管理者の、指定先というのは教えていただけるのですか。どこにも表示がないので。","respondent":"木村品川図書館長","answer":"もし口頭でよろしければ、今こちらで事業者の名前、紹介はできますけれどもよろしいでしょうか。図書館流通センターという企業と、それからウーヴという、子どもに本の読み聞かせをするＮＰＯ法人の共同事業体になっております。","id":"exchange-013"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１つは、教職員の健康管理なのですけれども、１９ページに「ＶＤＴ」と書いてあるのは何なのでしょうか。それがまず１つと、３２ページの学校保健の健康診断というところの寄生虫卵検査、これはいかがか尋ねました。","respondent":"品川庶務課長、野呂瀬学務課長","answer":"１点目、ＶＤＴの検査ですが、こちらは、パソコン等で目の疲れ、それから肩のこりとか、そういうものがあるかどうかという検査をするものです。健康診断等でレントゲンをやると思いますので、レントゲンの中で… 施行が平成２８年４月ということですので、今年度が最後の寄生虫卵検査ということになりますので、平成２７年度は入っております。来年度は入ってこない年になります。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"法制化に向けてのスパンというのですか、この２月２０日のときに今後の方向をぼんと本当に話をされるとか、スパンをお願いします。課題をどう解決したらいいかというところがなかなか見えないまま、また、私どもでわかるのか尋ねました。","respondent":"渋谷指導課長","answer":"フォーラムについては、一定程度、その段階で話し合われた進捗状況をご報告するというような形になろうかと考えているところです。昨年度から全ての９年生に対して４技能の一斉テスト、先駆けて実施しておりますので、またご報告させていただきたいと考えているところです。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"４７ページの、品川区いじめ根絶協議会、年３回終わって、今年は同じぐらいの回数をして、テーマは何にしていくというのはあるのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"本年度も基本的には年３回予定しております。それぞれ意見を出していただきながら、では、どういうテーマでやっていきましょうかというのを、１回目に相談する予定です。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、では、昨年のネットいじめ、テーマで議論されたことは、この中に「情報発信・意見交換により」ということで、これを発信されているのかもしれないのですけれども、どこで見られるのかわからないのですけれども、傍聴できるのか、それで公開されているのかを伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"表については、裏面につきましては、各家庭で約束を決めましょうというような書き込み用の資料をつくっております。それを各学校、また保護者等に配布して、協力をいただくということになっております。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは、私たちは手にして見るとか、画面にして見るということはできないのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"その辺については、もし可能であれば、ホームページ、またはいじめ根絶協議会のリーフレットにつきましては、この場でお示しすることはできると思います。","id":"exchange-018"},{"speaker":"伊藤副委員長","kind":"確認","question":"(4)に「ＩＣＴ環境を整備し」とあるのですが、１点だけ確認なのですけれども、斉藤さんというサイトはご存じですか。だから、やはりこれは、今日確認しておきたいのは、非常にこれから大きな問題になっていくと思うのですよ、総合的な対策をとっていかないと。","respondent":"村尾教育総合支援センター長","answer":"私ども、本当にネット関係につきましては、日進月歩でさまざまな、やってもまた次のものが出てくるということについては十分認識しているところです。各学級での指導というような、今、大きな考え方で進めていこうというふうに考えております。","id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"質問","question":"それはそのとおりなのですけれども、だけど、もう少し考えていくと、全ての、全国の教育委員会に共通する話題であるわけではないですか。品川区だけでつくるのは難しいでしょうから、新たな展開で検討していく必要があると思うのですが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長、塚本委員長、金子子ども未来部長、伊崎子ども育成課長、廣田子ども家庭支援課長、竹田保育課長、今井待機児童対策担当課長","answer":"東京都のほうと連携をとるとか、また、他の自治体での取り組み等を十分検討させていただきながら進めていこうというふうには考えているところです。 ほかになければ、教育委員会の事務事業概要につきましては、これで終了いたします。 ２つ目の児童相談係は、児童の養育から虐待に関する相談、また、それへの対応ということを所掌しております。詳細に関しては… 青少年の地域貢献活動につきましても一連の取り組みを進めており、(10)青少年ボランティアガイドを実施し、交流を図ってまいっております。…","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"２歳児、３歳児向けというのであるのですけれども、この親子のひろばなのでしょうか。わからないもので、何をしているのかと思っていつも見ているのですけれども、それをまずお聞かせほしいと求めました。","respondent":"伊崎子ども育成課長","answer":"親子のひろばというのは、年齢を区切った幼児クラブを中心にやっているものでして、これは定期的に開催をしております。ご自由にお使いいただける場所がありますので、それで常時、お子さん連れのお母様がいらっしゃるという状況になっております。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、親子のひろばの設置の目的というか、どういう考え方で設置されているのかというのが見当たらないと思っているのですが、そこを教えていただきたいと思うのですけれども。","respondent":"伊崎子ども育成課長","answer":"全ての事業についてのご説明は省かせていただいているのですが、年齢に合った支援を行うというところで、年齢別のものとなっております。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"６１ページ、貸付者の人数だけが載っているのですけれども、ここに相談に来られている方というのはカウントしていないのか。何らかの苦労があるのかと察するのですが、そういうところで、相談はどれぐらい来ているのかというのは把握されているか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"奨学金の貸付に関しましては１０月から募集をして、学校の推薦という形できて、相談という形にはのってきておりません。５０ページに、修学資金だけではないのですが、こちらのほうに相談件数は計上しています。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その次の次世代育成支援の計画がどういう関係になっていて、新制度などがスタートした平成２７年度、ひとつ教えてください。１歳、３歳以降の受け皿の考え方というか、基本的なところを教えてほしいと求めました。","respondent":"伊崎子ども育成課長、今井待機児童対策担当課長","answer":"各自治体が次世代に対する支援を実施していくようにということで進めてまいりましたが、また１０年、時限立法ということで延びております。平成２７年４月に成立しました計画の進捗状況を管理、説明をすることということで… ３歳児以降の受け皿について、ご質問にお答えいたします。新制度の中で、平成２７年度から５年以内に、３歳児の受け皿を区としても調整していく予定です。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今までは認可保育園のところだけ求められていたのに対して、平成２７年度から変えるのは、全部数字が変わっているのですよね。今日お伺いしたいのは、具体的に数字に出るのかどうか、お伺いしたいと思います。","respondent":"伊崎子ども育成課長、今井待機児童対策担当課長","answer":"私からは、子ども・子育て計画自体は５年スパンで策定されておりまして、子ども・子育て支援事業計画のほうに数値目標が入っております。単年度ごとに事業の実施状況等を確認しまして、会議で報告をし… 前も、４０ページの中では、認可保育園、認証保育所と家庭的保育事業を合わせた定員数、園児数で出しております。いわゆる入れなかった数、１,０１５人の年齢別内訳につきましては、こちらのほうはお出ししておりません。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"どういう場で伺ったらここの、どこの段階で伺ったら教えてくださるのかを、ひとつお伺いしたいのと。２１５人、品川区が待機児と認めた２１５人、ぜひここのところを説明を求めました。","respondent":"塚本委員長","answer":"飯沼委員、今日、概要説明なので、もちろん全部の数字がおそらく出るということはなかなか難しいと思うので、答えられる範囲でということでお願いします。","id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１つは、２３ページのプレママ・プチママタウンと、その事業に対する評価というのはどの程度されているのでしょうか。４９ページなのですけれども、家庭福祉の家庭相談の中で、この専門の家庭相談員というのはどのような資格をお持ちの方なのか尋ねました。","respondent":"伊崎子ども育成課長、廣田子ども家庭支援課長","answer":"２カ所ともなかなか妊婦さんの参加が少なかったということで、そこをどうやって増やしていこうかというところが一つ課題として残っております。参加人数、申込み率が大変よかったということで… 家庭相談員につきましては、家庭裁判所等で調停員とかを務めた方のＯＢの方にお願いしております。","id":"exchange-027"},{"speaker":"浅野委員","kind":"質問・要望","question":"２カ所教えていただきたいのですが、実際、どのように評価をしているのかということをひとつ教えてほしいと求めました。その後どうなっているのか、どのぐらいの利用、需要があるのかということについて説明を求めました。","respondent":"伊崎子ども育成課長","answer":"児童センターや学校関係などを通じて、保育園なども通じて、何らかの効果が生まれればいいなと思っているところです。貸出数については年々減ってきておりまして、昨年度末で１１台という状況でございました。","id":"exchange-028"},{"speaker":"浅野委員","kind":"質問・要望","question":"私も議会で質問したことがあるので、何らかの形でフィードバックをもらって、報告をしてほしいと求めました。継続していっていただきたいということと、そういう意味では、これからもいい意味で拡大できるように取り組みをしていただけたらと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"伊藤副委員長","kind":"確認","question":"その子どもがいることを確認したのか、そういうふうな確認方法はどうなのかということと、当然いろいろな情報が担当の中にそろってくるでしょうから。そのことの確認と、そういう後追いについてどうなのかということの３点かな、確認したいと思いますので。","respondent":"伊崎子ども育成課長、野呂瀬学務課長","answer":"あるいは、転出をしている場合は転出先の児童相談所あるいは区市町村できちんと対応していくという、これは全国的なルールでやっております。６歳の入学時につきましては、学務課のほうで調査をしております。 入管等で、いわゆる正式な公文書等でやりとりして実態を把握しているところで、私どもの数字を子ども育成課のほうに回答しているです。","id":"exchange-030"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"客観的な事実を積み重ねていって、子どもがいたと思われるところに虐待があったというのが、よくあるではないですか。だから、実際にそういうお子さんがいらっしゃるということの、目視なり確認する方法をやっていただきたいという希望はあるのですよ。","respondent":"伊崎子ども育成課長","answer":"そういった場合は児童相談所と連携しながら対応していくことになると考えていますが、簡単に言うと、踏み込んでいく権利はあるのですけれども。ですので、そこについては、これは国としての法制度上、どうにか対策をとっていただきたいと考えているところです。","id":"exchange-031"},{"speaker":"伊藤副委員長","kind":"質問","question":"この話し合いというのは現状の中では難しいと思いながら質問するのだけれども、でも、どうしてかまたもやあるわけですよね。客観的事実を積み重ねていって、いないと思っていたのに実際いたとか、いろいろなケースがあるわけで、ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つだけ。平成２６年度にそういう仕組みにしなければいけないというか、あるいは明確にしたというのでしょうか、お尋ねします。","respondent":"伊崎子ども育成課長","answer":"平成２６年度までは、八潮は１カ所なのですけれども、あるいは職員を通してすまいるスクールの状況などを見ることができるというところがあります。そういったところを目的にしております。","id":"exchange-033"}]},{"id":"topic-03","title":"平成２６年度品川区立学校における体罰等実態把握","agenda":"平成２６年度品川区立学校における体罰等実態把握","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"第三日野小学校のこの体罰というのは、この生徒の子は何年生で、性別はどちらか尋ねました。","respondent":"渋谷指導課長","answer":"体罰の被害を受けた子どもは、６年生の男児です。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この体罰が起きたときにどういう報告があったのかというのが気になって、こういう調査をして、明らかになったことではないですよね。その辺の経過を教えていただきたいのと、どういうことがされていたのかというのと、対策がとられているのかということも聞かせてください。","respondent":"渋谷指導課長","answer":"ケアについてですが、約１カ月強ございましたが、じっくりと子どもと人間関係が構築できるような対応をとらせていただいたところです。担任が５年生から６年生でかわったというところで…","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"停職１カ月ということだったのですけれども、これで済んだのでしょうか。ご家族の方の感情とか、その辺は特別なかったのか尋ねました。","respondent":"渋谷指導課長","answer":"事案が発生したのは５月１４日で、その後、６月２日に日光移動教室がございました。結果的にはいい卒業式ができたというふうに報告は受けているところです。","id":"exchange-036"}]},{"id":"topic-04","title":"臨時福祉給付金および子育て世帯臨時特例給付金の実施","agenda":"臨時福祉給付金および子育て世帯臨時特例給付金の実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それで、やはり前回が１万円だったのに、３,０００円になってしまう。では、併給できるのは何人ぐらいなのかというのをお聞きしたかったのですけれども、これだけ下がってしまった理由は何か尋ねました。","respondent":"廣田臨時給付金担当課長","answer":"考え方として、平成２６年度につきましては、平成２６年４月から消費税が上がりまして、平成２７年９月までの期間を見込んだ数字ということです。平成２７年度につきましては…","id":"exchange-037"}]},{"id":"topic-05","title":"認可保育園等の新規開設","agenda":"認可保育園等の新規開設","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"質問ではなくて、委員長にお願いがあるのですけれども、ただいまのご説明の中での株式会社の認可保育園、また、区立幼保一体施設、あと小規模保育事業という３つなのですけれども、さまざまな保育施設ができていますので、ぜひ視察を考えてほしいと求めました。","respondent":"塚本委員長","answer":"わかりました。こちらの理事者と、また委員長、副委員長で検討します。","id":"exchange-038"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（し）委員","kind":"意見","question":"小学校が逃げて、幼稚園のほうは園内で待機という判断の違いは、それぞれの校長先生と園長が判断されて、要するに、校長先生のほうの判断で外で、あと、園長の判断で中でというところなのですが、何もなかったのでそれぞれいいのですけれども…","respondent":"品川庶務課長","answer":"やはり煙が少しでも出ているということで、これは園内に入っているほうがいいという判断で、園内に待機という形をとりました。","id":"exchange-039"},{"speaker":"塚本委員長","kind":"提案","question":"では、ないようですので、最後に、今後の委員会運営について私のほうから提案があります。常に意識しておくべき事項等について、委員の皆様よりご意見・ご要望を聴取し、具体性を深めていきたいと考えておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/184577?Template=document&Id=4854#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":61199,"voices":157}},{"id":"h27-20150608-5","meetingId":"h27-cm06","date":"2015年6月8日","dateIso":"2015-06-08","committee":"総務委員会","time":"午後 １時００分～午後 ３時３３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今日は概要ということなので、区の基本的な姿勢や概要について簡潔に幾つか伺いたいと思います。総務部の平成２７年度主要課題の中に、平和事業にかかわって伺いますが、この事業のかかわりで伺いたいと思います。","respondent":"江部総務課長","answer":"平和に関するお尋ねの中で、国の法案ですが、こちらにつきましては、これまでの品川区の方針といたしまして、国政にかかわることについて言及する立場にはございませんという立場です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"改めて伺いますけれども、これでどうして核兵器の廃絶や恒久平和が実現するのか、区民の生命・財産が守れるのか、この点を伺いたいと思います。ぜひ、早くに、区民はもちろん、議会にも日程を示すべきだと思いますけれども、この点についてもいかがか尋ねました。","respondent":"江部総務課長","answer":"先ほどの法案につきまして、見解は変わりませんので、ご理解いただきたいと思います。５月か６月ごろ、大体１回目が開催予定ということでございましたので、特に支障はないと思うものです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"大綱についてどのような内容かと伺ったので、１週間前に発表しているから問題ないのだと、それは問題だと思うのです。個人情報のセキュリティについて同時に伺いたいと思うのですけれども、区民からも不安の声が上がっている、私のところにも寄せられています。","respondent":"江部総務課長、仁平情報推進課長","answer":"２点ございまして、明日から始まります総合教育会議の中で検討されていくものですので、事務局から現段階で申し上げることはございません。第１回を実施するに当たりまして、かなり検討を要したという事情もございまして… こちらのほうも、現在、区民の方々の情報を管理する立場としまして、同じような安全対策を十分検討していきたいと考えています。それと、今回の情報漏えいにつきまして、何か区民からの問い合わせということは、今のところ…","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"経理課と監査についても伺いたいのですけれども、６月で契約が切れるという話ですから、契約内容は何かを伺いたいと思います。それで、区長はどのような基準で区議会議員を指名しているのか、議会からの推薦や調整などがあるのか、その状況について伺いたいと思います。","respondent":"江部総務課長、立川経理課長、齋藤監査委員事務局長","answer":"総合教育会議での協議事項につきましての議会報告の考え方ということにつきましてですが、会議の運営についてということで諮ることにしております。 広町２丁目の保育園建設用地の駐車場の契約ですけれども、こちらにつきましては、現契約は６月３０日までとなっております。新規の契約として７月１日から… 議員の選任ですが、地方自治法第１９６条に、いわゆる識見監査員と議員のうちから監査委員を選任するという規定があります。議員のうち…","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"契約日について、私の言い方がまずくて、７月１日から新たな契約が始まると思うのですけれども、その契約をするのがいつなのかということを伺いたかったので、それを説明を求めました。","respondent":"立川経理課長","answer":"６月１１日に入札を実施いたしまして、入札後すぐ契約ということになります。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、議会の議論を踏まえていただきたいと思うのですけれども、この点、伺いたいと思います。ぜひ、議会への報告については調整の上に丁寧にやっていただきたいと思うのですが、いかがか尋ねました。","respondent":"立川経理課長","answer":"今回の普通財産の土地の貸付けにつきましては、公有財産管理規則に則り行っておるものですので、契約等を延期する考えはございません。議決案件につきましては、地方自治法に定められておりますので、その規定のとおり実施していきたいというふうに考えております。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"我々も質問をするときに、企画のほうは、こういうふうに財政課ときちっと分かれているのだと。明確に説明できるようにしてもらうとありがたいのですが、説明を求めました。","respondent":"柏原企画調整課長","answer":"私のほうからお答えしますけれども、役割をある程度分担して、ということです。その仕事の進め方のところで、総合的な視野から政策を進めるというところと財政計画についての役割をはっきり明確にしたというところであります。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"それだと、今後、品川区のいろいろな事業計画云々に関しては、企画調整課のほうに質問する、説明を求めるということでいいのですか。でも、どちらに聞いたらいいのかというのが迷うところが今あるので、そこはどうなのか尋ねました。","respondent":"柏原企画調整課長","answer":"政策の部分に関しては進行管理を進めたいというところがありますので、企画調整課のほうにお問い合わせいただくということで結構です。そこの部分については、場合によっては財政課としてお答えする部分もありますので…","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"細かいことですが、広報広聴課の中で電子アンケートというのがあったのですけれども、１５ページ。これはどの程度、平成１５年からどんな感じでされていったのか尋ねました。","respondent":"中元広報広聴課長","answer":"実績としては、平成２６年度２件、実施をさせていただいてあります。中身としては、しながわガイドについてと区ホームページについて実施をしたところです。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"それから、選挙管理委員会なのですけれども、つい昨日ぐらいだったでしょうか。二十歳になってすぐに引っ越してしまったら、こういうことというのは、自治体レベルで何か救済策を設けることはできるのか尋ねました。","respondent":"工藤選挙管理委員会事務局長","answer":"現在のところ、公職選挙法の中でそのような形で、いわゆる救済という形であれ、今の制度の中では選挙権が発生しないですので、各自治体で救済という部分は難しいというふうに思っております。","id":"exchange-010"},{"speaker":"あべ委員","kind":"意見","question":"であれば、もう国の動向を見守ってということになるのかと思いますが、今後、１８歳への選挙権引き下げなどもありますので、広く選挙権がきちんと行使されるような形で、新しい制度をご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"企画部の１５ページの広聴等事務のところなのですが、結果としてこれくらいということと、区としての評価ですね。どういうふうにもっと広げようとしているかとか、力を入れようとしているかとか、その辺の考えを教えていただけますか。","respondent":"中元広報広聴課長","answer":"一度、夜間開催を予定して、参加機会の拡大を図っているところです。本年度につきましては、テーマ別方式を２回ほど予定してございまして、現在はまだ調整中のところです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"公募方式というのは、広く募って、来た人はみんなという意味か尋ねました。","respondent":"中元広報広聴課長","answer":"やはり会場の制約もありますので、人数を抽選等で絞らせていただいてあります。","id":"exchange-013"},{"speaker":"あくつ副委員長","kind":"質問","question":"企画部の１７ページのシティプロモーションなのですけれども、予算特別委員会でも同じ質問が出たと思うのですが、今後のスケジュールというか方向性というか、シティプロモーションとしての打ち出しをいつぐらいの期間にお考えなのか、今後のスケジュールを説明を求めました。","respondent":"中元広報広聴課長","answer":"今後のスケジュール感、大雑把なところですけれども、現在、戦略プラン案の最終調整を図っているところでございまして、今後は当総務委員会のほうにも、今月下旬のところの総務委員会でご報告をさせていただいた上で、またまとめてまいりたいと思っているところです。","id":"exchange-014"}]},{"id":"topic-02","title":"特別区全国連携プロジェクト","agenda":"特別区全国連携プロジェクト","exchanges":[{"speaker":"本多委員","kind":"質問","question":"どうしても事業をやったり交流するのに予算がかかって、そういう従来の市町村交流と比べて、この全国連携はどういうイメージなのか。それにかかわってくる予算面とか、その辺は従来とどう違うのか、その辺を説明を求めました。","respondent":"柏原企画調整課長","answer":"ずっと画一的な進め方をするというよりは、各区がそれぞれ、一緒に連携をとっていくというものに向かっていくのだろうというふうに思ってあります。ですので、予算的なところで…","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問","question":"ちょっとよくわからないのですけれども、立ち上げとありますね。どういうふうに立ち上げることを進めて、この１枚ではどうもよくわからないのですけれども、時間と主語を入れて経緯を教えていただけますか。","respondent":"柏原企画調整課長","answer":"地方の発展に協力するためにどういった対応ができるのかというのを２３区の特別区長会のほうで検討してきたといったところです。そういった検討の中で、特別区と全国とが連携できるような、一緒に進んでいけるような仕組みができないかという協議がなされているです。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"お金はどこから出てくるのでしょうか。先ほど２,３００万円というような数字も出てきましたし、その都度ごとに集金をされるのか、どういうことになっているのか尋ねました。","respondent":"柏原企画調整課長","answer":"実際、各区がそれぞれの市町村に対して連携をとっていきますので、その部分についてお金がかかるかどうかというのは各区の判断というものです。この六魂祭に支援事業費で出しますということで、２,３００万円なのですが…","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問・要望","question":"２３区としてはどうしようもないわけですし、２３区として、そんな解決はできないわけではないですか。２３区として発信していったりとか、ほとんど２３区外では理解されていないことなどについて、税金を使ってやるわけですから。","respondent":"中山企画部長","answer":"１個目としては、２３区が個別にあり、税源のあり方の議論も地方間との冷静な話の中で持っていけるのではないか。これで根本的に変わるものではありませんが、よりよい地方創生の形をつくっていくための一歩目であるというふうにお考えいただければと思います。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"内側にとっても誤解のないように進めていただきたいと思うのですが、どういう表現になるか、そういった視点も持ってやってほしいと求めました。重ねてお答えいただいていいか尋ねました。","respondent":"中山企画部長","answer":"さまざまな連携のチャンネルを増やす中で、形としては、そういうポジティブなものにつなげる。特別区全体で取り組み、また、活動の中では個性もなるべく出せるよう芽が出てくればです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"交流というのはとても大事だと思うのですけれども、都市や地方の問題の解決にどういう関係をここで見ているのか、ちょっとそこを伺いたいと思います。地域の活性化が求められているとありますが、これは２３区を指しているのか、それともそれ以外の地方を指しているのか。","respondent":"柏原企画調整課長","answer":"事業を連携したりとか諸々あると思いますけれども、まず入り口の部分というふうにご理解いただければと思ってあります。最初の説明であれだったかもしれませんけれども、これも全てということではありませんので、特別区と全国と連携しながら。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"東京自身、また２３区自身が、自ら正すべきところはあるのではないかと思うのです。東京に吸い取られているというような感じをいろいろなところでよく伺うだけに、また２３区自身が人、その点についてはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"相互の連携のプロジェクトでありますので、新しい視点で、地方のほうからそういった芽が出てくるというところもあろうと思います。このプロジェクトというのは、小さい部分からではありますけれども、進めていくところには意義はあるのではないかというふうに思っております。","id":"exchange-021"},{"speaker":"あくつ副委員長","kind":"質問","question":"２,３００万円支出をして、私もＥＣＯフェスティバルに伺って、今回の動きの中で生まれたということで例に出されたのかどうかということ。６分の１ぐらいの回答ということで、連携できるかどうかというような内容のアンケートというお話でしたけれども、わかれば説明を求めました。","respondent":"柏原企画調整課長","answer":"アンケート等は実施はしておるのですけれども、まだ共通的に何か情報を得るようなツールはでき上がっていないというところもあります。何かできることはないかということで検討させていただいて、雪を当日入れて、イベントの盛り上がりにしたというものです。","id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"意見","question":"最初の一歩だというお話もありましたので、決して悪いことではないと思うのですけれども、広がっていけばいいと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"それを手助けして、せっかく特別区長会でこういうふうにやっていくということですから、慎重に動いてほしいと求めました。意見だけ言わします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"では具体的にどういうことなのかというときには、お話を伺うと、連携といっても単発のイベントに終わってしまっているというのがあります。どういうアンケートをとるのかとか、それからそれへの答えがどういうものなのかとかということを、私たちは知ることができるのか尋ねました。","respondent":"柏原企画調整課長","answer":"どういうつくりがいいですかとか、例えば、観光ＰＲの促進が必要だとかといったお答えをいただいているというのは概略のところでは聞いてあります。その辺は確認しますが、必要に応じて、こういったところでご報告するというふうに思ってあります。","id":"exchange-025"}]},{"id":"topic-03","title":"債権放棄","agenda":"債権放棄","exchanges":[{"speaker":"吉田委員","kind":"意見","question":"この債権の放棄についてはわかりましたが、私、全然把握していなくて、どうしても破産手続とかになると債権放棄せざるを得ないと思うのですけれども、こういう事例は、どれくらい起きる、または起きることを見込んでいらっしゃるものなのかとの意見を述べました。","respondent":"福島会計管理者","answer":"見込みというのはなかなか難しいのですけれども、あるいは住宅ですとか、そういうところはあります。私どもは、それが上がってきたものを集約していくという立場ですので、今すぐ今年何件を想定しているとかというものはございません。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"そうしたら、聞き方を変えまして、今まではどんな感じというか、１年間でどれぐらいあったのでしょうか。もちろん年によって違うと思いますけれども。","respondent":"福島会計管理者","answer":"あるいは３年、２年、それなりの件数は出てきます。まとめて第３回定例会で全体の報告をさせていただきたいというふうに思っております。","id":"exchange-027"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"今までもマイナス１５％を目標にして行われてきたのだと思いますが、その実績は教えていただけますか。だから、マイナス１５％を目標にしてきたが、どれくらい実績が上がっているのか。","respondent":"江部総務課長","answer":"そこから比較しての１５％なのですが、たしか記憶によりますと、年によって達成できた年と１５％にいかなかった年とあるかと思います。ちょっと詳細は持ち合わせてございません。","id":"exchange-028"},{"speaker":"あべ委員","kind":"確認","question":"一点だけ、ここでわかれば確認したいのですけれども、この避暑シェルターですが、これは区施設でされていますか。民間で手を挙げたところなどもなっているのか尋ねました。","respondent":"江部総務課長","answer":"ちょっと環境課で把握しているかは今わかりません。","id":"exchange-029"},{"speaker":"あべ委員","kind":"確認","question":"民間でそういうふうなものをお持ちの方もいらっしゃるみたいなので、両方で可能であれば活用できればと考えていますので、ご確認ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"本多委員","kind":"意見","question":"たくさんあるのですけれども、その中で２つだけ絞って、一つは人材育成。ほかにもたくさんあるのですけれども、まず２点を案として述べさせていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"その点について、公会計制度について、勉強したいなということが一つあります。これも先ほどのお話だと、もうちょっと幅広い観点ですけれども、取り上げていただきたいという気持ちがあります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"中塚委員","kind":"意見","question":"先ほど、総務委員会としてもしっかりと調査研究を深める必要があるのではないかということで、総合教育会議についてということ。特に個人情報のセキュリティ対策が現状どうなっているのか、どういう対策が今は必要になっているのか、その２つですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問・要望","question":"内容の前に、今後の所管事務調査を決めていくスケジュールを委員長、副委員長のほうでどのようにお考えなのかを教えてほしいと求めました。今回、意見聴取して、次回に向けてということなのか尋ねました。","respondent":"松澤委員長","answer":"６月１２日までに、とりあえず調査項目を各会派でありましたら、今は意見聴取をしていますけれども、出ない場合は出していただいて、それを正副委員長、理事者等と協議して進めていきたいというふうに思います。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"やはり情報化と言ったらいいのですか、よりＩＣＴ化を図っていくとともに、特に情報発信の部分です。ビッグデータなど、民間企業なども含めて、そういった情報化に対応した区政運営について検討ができたらいいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"須貝委員","kind":"意見","question":"今後、企画部のほうでも考えていくのでしょうけれども、できれば大都市の問題等について考えていったほうがいいのではないか。多くの人口を抱えて、これからどういう方向性を持って、所管事務調査として考えたほうがいいのではないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"中塚委員","kind":"意見","question":"何か変化があったとき、事業だったり計画だったり企画だったり、そういうときを捉えてもいいのかと思うのです。ほかの区議会がどういう対応をされているのか、次回以降、わかるところでご説明いただけたらとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"須貝委員","kind":"提案","question":"例えば横浜市とか２３区の中でもいいですが、そういう品川区と同じような問題を抱えた自治体を回るということのほうがすごく有効だと思うのです。予算が毎年削減されている状況を見ると、その辺のことも、やめるということも考えられたらいかがでしょうかという提案をしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"あべ委員","kind":"意見","question":"ただ、地方が一律に内容的に参考にならないとは全く思っていないです。そこはぜひ、柔軟に考えていただき、その内容本位で今後議論していければいいと私としては考えておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"中塚委員","kind":"意見","question":"その結果、遠い、近いは、それにふさわしい場所というところになるのかというふうに思います。テーマは次回までに考えておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858739?Template=document&Id=2016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":50283,"voices":149}}]);
